[1404] = "Dézoomer",
-- 0e47f09a English: Zoom in
-- Context: Tooltip of the plus icon button in the zoom bar at the bottom right of the rotation
--     diagram: makes the diagram larger (verb).
[1405] = "Zoomer",
-- ed28d6c9 English: Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is
--     unchanged.
[1406] = "Réinitialiser le zoom du canevas à 100%. Faites glisser un espace vide du canevas pour le déplacer. L'échelle de la fenêtre est inchangée.",
-- a7f6faca English: Diagram / List changes only the rotation view; General settings choose the
--     default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll
--     to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty
--     diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms,
--     False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in
--     every view. Each workspace currently shows at most 200 cards; the remaining saved cards are
--     preserved.
[1407] = "Diagramme / Liste ne change que la vue de la rotation ; les paramètres Généraux choisissent la vue par défaut. Le diagramme dispose de contrôles flottants moins, pourcentage et plus en bas à droite. Faites défiler pour zoomer de 25% à 200% ; cliquez sur le pourcentage ou faites un clic milieu pour revenir à 100%. Faites glisser un espace vide du diagramme pour le déplacer. La liste utilise des barres de défilement normales, avec des cartes accolées et des bras de branche encadrés, Faux avant Vrai. Les temps de recharge utilisent une grille défilante séparée. Faire glisser des cartes les réordonne dans toutes les vues. Chaque espace de travail affiche actuellement au plus 200 cartes ; les cartes enregistrées restantes sont conservées.",
-- b1fd3756 English: Custom emote
-- Context: Announcement output channel: sends the message as a custom emote. Entry in the channel
--     dropdown of an announcement output (shown only for emote outputs) and a topic title in the
--     Announces help.
[1408] = "Emote personnalisée",
-- 6dd86cd7 English: Use spell recipient ({{target}})
[1409] = "Utiliser le destinataire du sort ({{target}})",
-- 3cb40b84 English: Automatic Say and Yell are unavailable. Choose another announcement
--     destination.
[1410] = "Dire et Crier automatiques sont indisponibles. Choisissez une autre destination d'annonce.",
-- 38f252ac English: Press Enter or leave a text field to stage its value; Apply saves the draft.
--     Invalid text stays red and blocks navigation until corrected. Searchable selectors open on
--     click and filter as you type. Section headings collapse or expand their contents.
[1411] = "Appuyez sur Entrée ou quittez un champ de texte pour préparer sa valeur ; Appliquer enregistre le brouillon. Un texte invalide reste en rouge et bloque la navigation jusqu'à sa correction. Les sélecteurs avec recherche s'ouvrent au clic et filtrent à mesure que vous tapez. Les titres de section replient ou développent leur contenu.",
-- c546b857 English: Default rotation view
-- Context: General settings: label of the dropdown that chooses whether rotations open as a diagram
--     or a list by default; also a help topic title and a row label in the profile comparison.
[1412] = "Vue de rotation par défaut",
-- d11b9246 English: Choose Diagram or List as the starting rotation view. This profile preference
--     applies when opening a rotation; changing the view inside the editor does not change this
--     setting. Cooldowns always use a scrolling grid.
[1413] = "Choisissez Diagramme ou Liste comme vue de rotation initiale. Cette préférence de profil s'applique à l'ouverture d'une rotation ; changer de vue dans l'éditeur ne modifie pas ce paramètre. Les temps de recharge utilisent toujours une grille défilante.",
-- 769b3ebc English: Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty
--     space to pan.
[1414] = "Réinitialiser le zoom du diagramme à 100%. Faites défiler pour zoomer ; clic milieu pour réinitialiser. Faites glisser un espace vide pour déplacer la vue.",
-- a3dd333a English: Move this and following entries
[1415] = "Déplacer cette entrée et les suivantes",
-- ffcd3171 English: Drag one entry; Ctrl-drag moves it and all following siblings.
[1416] = "Faites glisser une entrée ; Ctrl-glisser la déplace avec toutes ses sœurs suivantes.",
-- 773001f9 English: %d cards
-- Context: Small count label on the stacked hover card of the rotation view, e.g. "3 cards"; %d is
--     the number of cards stacked together.
-- %d #1: %d #1: the number of cards being dragged, e.g. 3
[1417] = "%d cartes",
-- 454b5fb4 English:  (%d hidden)
-- Context: Suffix on a True/False branch button in the rotation diagram when part of that branch is
--     folded away; %d is the number of hidden steps. Keeps its leading space, appended right after
--     "True" or "False".
-- %d #1: %d #1: the number of cards hidden inside the folded branch, e.g. 4 (the text starts with a space and follows "True" or "False")
[1418] = " (%d masquées)",
-- 9db3d1ae English: Click to fold or unfold this branch arm. Other cards and conditions are
--     unchanged.
[1419] = "Cliquez pour replier ou déplier ce bras de branche. Les autres cartes et conditions restent inchangées.",
