[1505] = "Intégrations",
-- 90c92d4c English: Lua editor
-- Context: Title of the Lua editor help window, and the name of a Lua editor settings row in the
--     profile comparison.
[1506] = "Éditeur Lua",
-- d8cfde4d English: Choose optional addon integrations.
[1507] = "Choisissez les intégrations d'addons facultatives.",
-- 67af476d English: Automatic uses an available editor integration, with built-in syntax
--     highlighting as its fallback. Plain text disables highlighting. Apply changes the editor used
--     the next time you open a custom condition.
[1508] = "Automatique utilise une intégration d'éditeur disponible, avec la coloration syntaxique intégrée en repli. Texte brut désactive la coloration. Appliquer change l'éditeur utilisé la prochaine fois que vous ouvrez une condition personnalisée.",
-- 9fe3f474 English: Loaded; editor integration not connected.
[1509] = "Chargé ; intégration de l'éditeur non connectée.",
-- a79eae91 English: Not loaded.
[1510] = "Non chargé.",
-- 87b30347 English: These addons are optional. Only connected editor providers appear in the Editor
--     menu. Choosing an unavailable or failing editor falls back to the built-in editor.
[1511] = "Ces addons sont facultatifs. Seuls les fournisseurs d'éditeur connectés apparaissent dans le menu Éditeur. Choisir un éditeur indisponible ou défaillant revient à l'éditeur intégré.",
-- f1fa67bf English: Choose the editor for custom Lua conditions. Built In syntax highlighting and
--     Plain text work without another addon. Automatic uses a registered optional provider when
--     available and falls back safely. Apply saves the choice; an open editor keeps its current
--     provider until reopened. LuaWorkbench and WowLua loading status is shown separately from
--     integration availability.
[1512] = "Choisissez l'éditeur des conditions Lua personnalisées. Coloration syntaxique intégrée et Texte brut fonctionnent sans autre addon. Automatique utilise un fournisseur facultatif enregistré lorsqu'il est disponible et se replie sans risque. Appliquer enregistre le choix ; un éditeur ouvert garde son fournisseur actuel jusqu'à sa réouverture. L'état de chargement de LuaWorkbench et WowLua est affiché séparément de la disponibilité de l'intégration.",
-- dfab6835 English: Invalid condition: %s
-- %s #1: %s #1: why the custom condition is invalid, a short reason, e.g. "unexpected symbol near end"
[1513] = "Condition invalide : %s",
-- a3d021a9 English: Unavailable condition: %s
-- %s #1: %s #1: the description of the condition, e.g. "In Combat"
[1514] = "Condition indisponible : %s",
