[1960] = "cette édition n'a pas de Report",
-- 70b12e8e English: this edition has no Eclipse
[1961] = "cette édition n'a pas d'éclipse",
-- 864ee126 English: this client has no assigned group roles
[1962] = "ce client n'a pas de rôles de groupe attribués",
-- 1eb43a88 English: /rm debug timeline [seconds] - Report what the Retail and Forever encounter
