[1980] = "le soigneur attribué de votre groupe",
-- 1f321239 English: your group's assigned healer's
[1981] = "du soigneur attribué de votre groupe",
-- 343dc906 English: your group's leader
-- Context: Phrase for the unit choice 'group leader' in condition summaries, e.g. '<this> {{!is|is
--     not}} your group's leader'; the next string is its possessive form.
[1982] = "le chef de votre groupe",
-- 1d3180fa English: your group's leader's
-- Context: Possessive form of 'your group's leader' used in condition summaries before a noun, e.g.
--     'your group's leader's health'.
[1983] = "du chef de votre groupe",
-- fad43537 English: Absolute health target (negative means deficit) or percentage fraction.
[1984] = "Cible de points de vie absolue (négative pour un déficit) ou fraction de pourcentage.",
-- 29a55788 English: All original results, preserving nil positions and return count.
[1985] = "Tous les résultats d'origine, en conservant les positions nil et le nombre de valeurs renvoyées.",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[1986] = "Applique l'ancien test d'écriture d'entier ou de chaîne numérique canonique. Les nombres utilisent l'égalité après floor ; les chaînes doivent être identiques à l'écriture obtenue après conversion numérique et floor. Les autres types renvoient false. Ce n'est pas un validateur de nombre fini.",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[1987] = "Arguments transmis tels quels à la fonction observée.",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[1988] = "Arguments transmis tels quels ; les types, l'identité, l'arité et les positions nil distinguent les entrées du cache.",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[1989] = "Motif de disponibilité ou de validation de la requête pour une observation de niveau nil.",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[1990] = "Motif de disponibilité ou de validation de la requête pour un niveau nil.",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[1991] = "Motif de disponibilité ou de validation de la requête lorsqu'aucun état actuel ne peut être lu.",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[1992] = "Motif de disponibilité ou de validation de la requête lorsque l'observation entière est indisponible.",
-- 11483c22 English: Availability or validation reason for a nil result.
[1993] = "Motif de disponibilité ou de validation pour un résultat nil.",
-- bd62d347 English: Availability or validation reason when the record is nil.
[1994] = "Motif de disponibilité ou de validation lorsque l'enregistrement est nil.",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[1995] = "Motif de disponibilité ou de validation lorsque le résultat est nil.",
-- 37cddc45 English: Availability reason for a nil result.
[1996] = "Motif de disponibilité pour un résultat nil.",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[1997] = "Motif de disponibilité en cas d'échec de la résolution ; nil en cas de succès.",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[1998] = "Met en cache une observation dès qu'elle renvoie une valeur non nil ; réessaie les observations dont tout le tuple renvoyé est nil. Utilise les mêmes clés d'arguments exactes que getCached.",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[1999] = "Calcule un taux contrôlé d'historique des points de vie à partir d'une fenêtre et d'une horloge finies explicites. Conserve la pondération ordonnée, l'arrondi canonique en direct ligne par ligne, les flux ignorés, les trous de tableau, les clés fractionnaires et les âges finaux visités. Un budget fixe de 4096 unités couvre les lignes visitées et les intervalles d'accumulation des deux flux ; tout dépassement ou calcul consommé invalide renvoie « indisponible », jamais une estimation partielle ni une valeur bornée. Cette nouvelle API a sa propre identité de source ; les fonctions de tendance historiques restent inchangées.",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2000] = "Appelle une observation une seule fois par cache et par tuple d'arguments exact, y compris pour les résultats nil. Passez le cache d'évaluation pour partager les observations au sein d'un cycle de recommandation ; avec un cache nil, l'appel est direct.",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2001] = "Fonction de rappel appelée après le changement de l'unité sélectionnée.",
-- f4755bc2 English: Callback receiving the committed spell value.
[2002] = "Fonction de rappel recevant la valeur de sort validée.",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2003] = "Cache d'observations d'évaluation appartenant à l'appelant ; nil interroge à nouveau.",
-- d07ec966 English: Capability or clock observation availability reason.
[2004] = "Motif de disponibilité de la capacité ou de l'observation de l'horloge.",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2005] = "Motif de disponibilité de la capacité ou de l'observation pour une classe nil.",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2006] = "Vérifie si un sort peut être recommandé maintenant, en acceptant un sort dont le temps de recharge restant se termine avec le temps de recharge global actuel. Sur Retail et Forever, où les durées de recharge sont secrètes en combat, la disponibilité provient plutôt des indicateurs isEnabled, isActive et isOnGCD, qui ne sont jamais secrets. Seule la disponibilité du temps de recharge est vérifiée ; ni l'apprentissage, ni la portée, ni la ressource ne sont vérifiés. Passez le temps d'évaluation depuis evalStart ou GetTime().",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2007] = "Vérifie si une table possède une valeur non nil à une clé. Une valeur false enregistrée compte comme présente ; les valeurs de la table ne sont pas parcourues.",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2008] = "Widget case à cocher avec une valeur booléenne et des méthodes de rappel.",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2009] = "Choisit la valeur joueur fournie uniquement pour l'identifiant d'unité littéral player ; toute autre unité sélectionne la valeur non-joueur. Les valeurs false et nil sélectionnées sont conservées.",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2010] = "Motif de classification, de validation ou de disponibilité pour un résultat nil.",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2011] = "Classe un objet numérique comme glyphe de la classe demandée, à l'aide des métadonnées d'objet natives protégées. La classe est facultative et vaut par défaut la classe lisible du joueur. Cela établit uniquement la classification de l'objet, ni son statut équipé ni la correspondance entre ID d'objet et ID de sort de glyphe.",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2012] = "Motif de famille de client, de validation de la requête ou de disponibilité d'une observation requise pour un résultat nil.",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2013] = "Motif de politique client, de capacité, d'appel ou de disponibilité de l'observation pour une forme nil.",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2014] = "Motif de politique client, de capacité, d'appel ou de disponibilité de l'observation pour un enregistrement nil.",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2015] = "Motif de politique client, d'appel natif ou de disponibilité de l'appartenance requise pour un enregistrement nil.",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2016] = "Type fermé : runner, resist ou immune.",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2017] = "Type scalaire fermé : current ou maximum.",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2018] = "Collecte les clés d'une table et les trie selon leurs valeurs associées, par comparaison Lua « inférieur à ». Ce sont les valeurs qui sont triées, pas les noms de clés ; l'ordre des clés à valeurs égales n'est pas garanti.",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2019] = "Motif de politique de combat, de capacité, d'observation ou de budget de parcours pour un décompte nil.",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2020] = "Taux pondéré signé combiné issu de la formule d'origine ; les entrées mal formées ou non finies conservent l'ancien comportement (erreur ou valeur numérique).",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2021] = "Compare l'ID de créature de l'unité sélectionnée à une clé de type de créature enregistrée existante. La correspondance fixe clé-ID est résolue dans un unique mappeur exécutable privé ; la correspondance en jeu ne dépend pas de la table modifiable des libellés localisés de l'interface. Les observations natives complètes sont partagées dans le cache de passe d'évaluation fourni selon l'observateur, le récepteur et l'unité effectifs, y compris les absences et les motifs d'indisponibilité. Une absence connue ou un ID différent connu renvoie false ; une observation requise indisponible renvoie nil avec un motif. Aucun état à long terme ni modification de libellé n'est ajouté.",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2022] = "Compare deux identifiants d'unité exacts avec UnitIsUnit, après avoir vérifié uniquement le premier avec UnitExists. Une première unité absente et lisible renvoie false sans comparaison. Les observations requises manquantes, en échec, restreintes ou mal formées renvoient nil avec un motif. Aucune seconde requête d'existence, recherche de GUID ni identité déduite n'est ajoutée.",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2023] = "Compare deux valeurs à l'aide d'un identifiant d'opérateur RM : LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS ou DIVISIBLE. Les opérateurs invalides émettent un avertissement et renvoient nil ; les opérandes doivent prendre en charge l'opération Lua choisie.",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2024] = "Clé d'opérateur de comparaison, comme EQUALS ou LESSTHAN.",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2025] = "Résultat de la comparaison, ou nil pour un opérateur inconnu.",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2026] = "Texte de comparaison conservant le balisage des alternatives booléennes nommées.",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2027] = "Décompte complet des classes correspondantes, zéro compris, ou nil si indisponible.",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2028] = "Décompte observé complet et non négatif, zéro compris, ou nil si indisponible.",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2029] = "Conteneur de condition prenant en charge SetLayout, AddChild, SetUserData, SetWidth et DoLayout.",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2030] = "Enregistrement de valeur de condition contenant les champs spell, ranked et disabled ; mis à jour sur place.",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2031] = "Enregistrement de valeur de condition mis à jour lorsqu'une unité est choisie.",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2032] = "Sélecteur d'unité configuré ; ajoutez-le avec parent:AddChild(widget).",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2033] = "Copie une table en utilisant tostring de chaque clé d'origine comme clé de destination. Les valeurs conservent leur identité d'origine. Les clés converties en chaîne qui entrent en collision s'écrasent mutuellement, dans l'ordre non spécifié du parcours pairs.",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2034] = "Compte toutes les entrées visitées par pairs, y compris les valeurs false et les clés numériques éparses ou non numériques. Une table nil a une longueur nulle.",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2035] = "Compte les jetons de classe correspondants dans la composition fixe actuelle. Lit d'abord l'appartenance au groupe ; si demandé, l'appartenance à un raid sélectionne raid1 à raid40 sans fait joueur distinct. En solo et en groupe, player est lu en premier, puis party1 à party4 si vous êtes groupé. Une composition complète et connue renvoie un décompte, zéro compris ; tout fait requis indisponible renvoie nil avec un motif. Les observations complètes partagent le cache de passe d'évaluation ; aucune classe de joueur n'est conservée d'une passe à l'autre. Les anciens rappels bruts archivés conservent séparément leur classe d'origine lue au chargement.",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2036] = "Ne compte que les unités indexées par GUID déjà présentes dans l'instantané d'appartenance observé. Vérifie l'identité actuelle de l'identifiant avant d'utiliser l'observateur de menace publié ; les identifiants absents connus ou réutilisés sont exclus sans être remplacés. Les observations complètes d'identité et de menace ne partagent que le cache d'évaluation fourni, tandis que l'appartenance est parcourue à nouveau. Une unité connue comme non ennemie ou une menace nil facultative n'est pas comptée ; des faits requis illisibles, mal formés ou en échec rendent tout le résultat indisponible. Cela n'énumère pas une composition complète, n'applique pas de filtre de portée et ne modifie pas les enregistrements suivis.",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2037] = "Crée un conteneur de champs de condition avec les dispositions List, Table et le champ de sort adaptatif propres à RM. Il accepte les widgets de condition natifs enregistrés ; ajoutez les enfants avec AddChild et attachez le groupe au parent du rappel.",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2038] = "Crée un sélecteur d'unité configuré lié à un enregistrement de valeur de condition. Renvoie le widget, que l'appelant ajoute au parent du rappel de condition.",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2039] = "Crée un contrôle de condition booléen natif. Configurez SetLabel, SetValue, SetDisabled et OnValueChanged ; ajoutez-le avec parent:AddChild(widget).",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2040] = "Crée un bouton natif utilisant le cycle de vie commun des widgets de condition et le thème de l'atelier (workbench). SetText, SetDisabled et SetCallback configurent son libellé et son interaction ; OnClick reçoit le bouton de la souris. Ajoutez-le au parent du rappel avec parent:AddChild(widget).",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2041] = "Crée un sélecteur de condition natif. SetList accepte des tables clé-libellé ou clé-entrée ; SetValue sélectionne une clé et OnValueChanged signale les changements. Ajoutez-le avec parent:AddChild(widget).",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2042] = "Crée un contrôle d'image natif utilisant le cycle de vie des widgets de condition. SetImage et SetImageSize choisissent la texture ; SetText ajoute éventuellement une légende. OnClick, OnEnter et OnLeave suivent le contrat de rappel commun. Ajoutez le contrôle au parent du rappel avec parent:AddChild(widget).",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2043] = "Crée une saisie numérique de condition native avec un curseur et un champ numérique. Configurez SetSliderValues, SetValue, SetIsPercent et SetCallback ; OnValueChanged signale les valeurs validées. Ajoutez-la avec parent:AddChild(widget).",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2044] = "Crée un pavé de position natif utilisant les contrôles directionnels communs. OnOffsetChanged signale la direction horizontale et verticale, si Centre a été pressé, et l'incrément (un, ou dix avec Maj). SetDisabled contrôle l'interaction ; ajoutez le pavé au parent du rappel avec parent:AddChild(widget).",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2045] = "Crée une saisie de texte native selon le contrat des widgets de condition. SetLabel, SetText, SetDisabled et SetCallback la configurent ; OnEnterPressed valide le texte. Ajoutez-la au parent du rappel avec parent:AddChild(widget).",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2046] = "Crée une copie superficielle filtrée, malgré le nom historique deepcopy. Les valeurs imbriquées conservent leur identité d'origine et la métatable source n'est pas copiée. Par défaut, exclut les clés figurant parmi les valeurs de except ; avec invert à true, seules les clés listées sont incluses. Une entrée nil renvoie nil.",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2047] = "Crée une saisie de sort avec suggestions, validation et prise en charge des liens de sort pour les widgets de condition personnalisée. Le rappel de mise à jour se charge d'enregistrer la valeur choisie ; ajoutez le widget renvoyé au parent du rappel.",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2048] = "Crée un résumé de condition nommé et temporaire. Utilisez {name} pour les valeurs scalaires et {{positive|negative}} pour les alternatives de prédicat ; préfixez l'alternative principale par !. Échappez les doubles accolades littérales en {{{{ et }}}}. Les valeurs sont insérées littéralement, sans interpréter leurs signes pourcentage, liens, couleurs ou accolades. Les valeurs de prédicat typées participent à la sélection principale. Les modèles, les valeurs et le texte rendu sont bornés ; une entrée mal formée produit un résumé « indisponible » localisé. Cela ne modifie que la présentation et n'exécute aucune observation de condition.",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2049] = "Crée un prédicat de comparaison typé pour une phrase de condition nommée. La formulation positive utilise la table d'opérateurs capturée d'origine et la formulation négative la table actuelle des opérateurs niés. Un prédicat principal a priorité sur les qualificatifs ; seul le premier prédicat admissible est nié. Les opérateurs inconnus utilisent le substitut d'opérateur existant. Cela met en forme la formulation sans comparer de valeurs ni évaluer de condition.",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2050] = "Crée un itérateur sur un instantané trié des clés d'une table. L'ordre par défaut compare les clés ; une fonction d'ordre personnalisée reçoit la table d'origine et deux clés. Les valeurs sont lues dans la table d'origine au moment où chaque clé est produite. L'ancien itérateur s'arrête lorsque la clé capturée suivante est nil ou false.",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2051] = "Crée un texte natif à retour à la ligne qui mesure sa hauteur à partir de sa largeur et de sa police. SetText, SetFont ou SetFontObject configurent son contenu. Ajoutez-le au parent du rappel avec parent:AddChild(widget) pour que la disposition suive sa hauteur mesurée.",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2052] = "Crée un texte natif à retour à la ligne avec une image facultative en tête et des rappels de pointeur. SetImage et SetImageSize configurent l'image ; OnEnter, OnLeave et OnClick suivent le contrat de rappel des conditions. Ajoutez-le au parent du rappel avec parent:AddChild(widget) ; les rappels expirent lorsque son bail est libéré.",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2053] = "Temps d'évaluation actuel en secondes, issu de GetTime(), normalement evalStart.",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2054] = "Distance de visibilité positive actuelle, en mètres ; nil si indisponible.",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2055] = "Identifiant de l'unité actuelle dont la distance au joueur doit être observée.",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2056] = "Tableaux damage/heals de lignes temps/valeur ; seuls les flux sélectionnés sont consommés.",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2057] = "Nombre de décimales, zéro par défaut ; les valeurs négatives arrondissent à la dizaine ou à une puissance de dix supérieure.",
-- c1094708 English: Dense array of keys sorted by associated value.
[2058] = "Tableau dense de clés triées selon leur valeur associée.",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2059] = "Tableau dense de champs de texte non vides.",
-- ba17b32f English: Destination array modified in place.
[2060] = "Tableau de destination, modifié sur place.",
-- 9d65688a English: Display lookup table.
[2061] = "Table de correspondance pour l'affichage.",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2062] = "Estime la variation signée des points de vie à partir de l'historique pondéré des dégâts et des soins. Les dégâts contribuent un taux négatif et les soins un taux positif. Lit la fenêtre du profil en direct si aucune fenêtre n'est fournie, utilise l'horloge en direct et l'ancien service d'arrondi, et conserve la pondération et le calcul d'âge arrondi existants. Cette fonction utilitaire ne valide ni n'assainit l'historique, ne borne pas les horodatages et ne garantit pas des résultats finis.",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2063] = "Estime le temps restant avant d'atteindre les points de vie choisis. Met en cache, par passe d'évaluation, les observations natives complètes d'identité et les observations scalaires paresseuses, tandis que le fournisseur, l'historique, la fenêtre, l'horloge et la prévision restent en direct. Une égalité exacte avec la cible renvoie zéro avant tout traitement de l'historique. Conserve les résultats volontaires false (pas d'estimation) et zéro initialisé pour les taux nuls ou de sens opposé ; des faits requis invalides, un dépassement ou l'épuisement du budget de 4096 unités donnent « indisponible ». Ne modifie jamais l'historique et n'invente jamais d'estimation partielle.",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2064] = "Cache d'évaluation, ou nil pour contourner la mise en cache.",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2065] = "Cache de passe d'évaluation pour les observations d'unité complètes ; nil observe directement. Des clés sélectionnées différentes réutilisent le même instantané d'unité.",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2066] = "Cache de passe d'évaluation, ou nil pour des observations fraîches.",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2067] = "Cache de passe d'évaluation, ou nil pour observer l'identité directement. La correspondance des ressources est résolue en direct à chaque appel.",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2068] = "Cache de passe d'évaluation, ou nil pour observer l'identité directement. Les observations réussies de la classe du joueur peuvent utiliser le cache d'identité à long terme existant ; la correspondance des ressources reste en direct.",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2069] = "Cache d'observations natives de la passe d'évaluation ; nil interroge à nouveau.",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
