[2103] = "Valeur scalaire de points de vie native, finie et non négative, ou nil si indisponible.",
-- aa23a412 English: Finite quantity in whole units with its fractional part; nil when unavailable.
[2104] = "Quantité finie en unités entières, avec sa partie fractionnaire ; nil si indisponible.",
-- 29e4a6a2 English: Finite signed combined rate, or nil for unavailable calculation.
[2105] = "Taux combiné signé fini, ou nil si le calcul est indisponible.",
-- 94c010ef English: First exact unit token, checked for existence before comparison.
[2106] = "Premier identifiant d'unité exact, dont l'existence est vérifiée avant la comparaison.",
-- 46ec876e English: First table to compare.
[2107] = "Première table à comparer.",
-- 13e6df72 English: Format comparison wording with named Boolean alternatives when the operator has
--     a negative form. The primary flag marks the positive form as the primary alternative.
--     Positive operator labels use the captured operator map; negative labels and nullable dispatch
--     retain their live addon APIs.
[2108] = "Met en forme la formulation d'une comparaison avec des alternatives booléennes nommées lorsque l'opérateur a une forme négative. L'indicateur primary désigne la forme positive comme alternative principale. Les libellés d'opérateurs positifs utilisent la table d'opérateurs capturée ; les libellés négatifs et la répartition nullable conservent leurs API d'addon en direct.",
-- b0edcb9b English: Fresh finite native clock value, or nil when unavailable.
[2109] = "Valeur d'horloge native fraîche et finie, ou nil si indisponible.",
-- b3a296d8 English: Fresh readable class filename, or nil when unavailable.
[2110] = "Nom de fichier de classe frais et lisible, ou nil si indisponible.",
-- 16428e88 English: Fresh readable finite clock, or nil when unavailable.
[2111] = "Horloge fraîche, lisible et finie, ou nil si indisponible.",
