[2350] = "true pour une unité lisible, attaquable et non morte, false pour un résultat négatif concluant, ou nil si une observation requise est indisponible.",
-- 72d71c8f English: True for an exact identity match; false for known absence or mismatch; nil when
--     required data or the query is unavailable.
[2351] = "true pour une correspondance d'identité exacte ; false pour une absence connue ou une non-correspondance ; nil si des données requises ou la requête sont indisponibles.",
-- 3286d546 English: True includes only listed entries; false or nil excludes listed entries.
