[2370] = "Identifiant de l'unité dont l'incantation ou la canalisation en cours doit être observée.",
-- 8978c94b English: Unit token whose current health should be observed.
[2371] = "Identifiant de l'unité dont les points de vie actuels doivent être observés.",
-- 16f17c11 English: Unit token whose raw level should be observed.
[2372] = "Identifiant de l'unité dont le niveau brut doit être observé.",
-- bb787bde English: Unit token whose raw level should be resolved.
[2373] = "Identifiant de l'unité dont le niveau brut doit être résolu.",
-- 4b2caef5 English: Unit token, such as target; nil uses target.
[2374] = "Identifiant d'unité, comme target ; nil utilise target.",
-- 8b73a7bd English: Validation or availability reason for a nil result.
[2375] = "Motif de validation ou de disponibilité pour un résultat nil.",
-- 193551e6 English: Validation, policy or availability reason for a nil result.
[2376] = "Motif de validation, de politique ou de disponibilité pour un résultat nil.",
-- 2b8bf1ec English: Validation, policy or required-fact availability reason for a nil count.
[2377] = "Motif de validation, de politique ou de disponibilité d'un fait requis pour un décompte nil.",
-- f4896f62 English: Value compared with each table value using Lua equality.
[2378] = "Valeur comparée à chaque valeur de la table par égalité Lua.",
-- 682b55a9 English: Value passed to the original arithmetic formula.
[2379] = "Valeur transmise à la formule arithmétique d'origine.",
-- 53d931f9 English: Value record field to edit; defaults to unit.
[2380] = "Champ de l'enregistrement de valeur à modifier ; unit par défaut.",
-- 48c786d6 English: Value returned for every other unit.
[2381] = "Valeur renvoyée pour toute autre unité.",
-- 35f7fff6 English: Value returned when unit is player.
[2382] = "Valeur renvoyée lorsque l'unité est player.",
-- 59731a4c English: Value to display; false is preserved.
[2383] = "Valeur à afficher ; false est conservé.",
-- d488fb09 English: Visit entries in both tables and compare each value with the indexed value in
--     the other table using Lua equality. Normal indexing and equality metamethods apply; nested
--     contents are not compared recursively.
[2384] = "Parcourt les entrées des deux tables et compare chaque valeur à la valeur indexée de l'autre table par égalité Lua. L'indexation et les métaméthodes d'égalité normales s'appliquent ; les contenus imbriqués ne sont pas comparés récursivement.",
-- b4707a12 English: Weighted health-snapshot change from the original total/count formula; zero for
--     falsy input or when no weighted change was recorded.
[2385] = "Variation pondérée des instantanés de points de vie selon la formule d'origine total/nombre ; zéro pour une entrée fausse ou lorsqu'aucune variation pondérée n'a été enregistrée.",
-- c3ba802c English: Weighting window in seconds; nil or false uses the current profile
--     damage_history setting.
[2386] = "Fenêtre de pondération en secondes ; nil ou false utilise le paramètre damage_history du profil actuel.",
-- c6cfccd1 English: Whether the original floor-equality or exact numeric-spelling predicate
--     matches.
[2387] = "Indique si le prédicat d'origine (égalité après floor ou écriture numérique exacte) correspond.",
-- 8c0b7ad7 English: Whether the text begins with the exact prefix.
[2388] = "Indique si le texte commence par le préfixe exact.",
-- 37054b01 English: Whether the text ends with the exact suffix.
[2389] = "Indique si le texte se termine par le suffixe exact.",
-- 2ae8305f English: With restricted-value only: isActive, true while a cooldown (its own or the
--     global one) is running.
[2390] = "Avec restricted-value uniquement : isActive, true tant qu'un temps de recharge (le sien ou le global) est en cours.",
-- 08c56f26 English: With restricted-value only: isEnabled, false while the cooldown is on hold.
[2391] = "Avec restricted-value uniquement : isEnabled, false tant que le temps de recharge est suspendu.",
-- 11f0d805 English: With restricted-value only: isOnGCD, true when the running cooldown is the
--     global cooldown; may be nil.
[2392] = "Avec restricted-value uniquement : isOnGCD, true quand le temps de recharge en cours est le temps de recharge global ; peut être nil.",
-- 303e2b6b English: Work-limit, data or arithmetic availability reason for nil rate/age.
[2393] = "Motif de disponibilité (limite de travail, données ou calcul) pour un taux ou un âge nil.",
-- 01efc08d English: Wrap text at whitespace boundaries near a target column count. Long words are
--     retained intact.
[2394] = "Ajoute des retours à la ligne aux espaces les plus proches d'un nombre de colonnes cible. Les mots longs restent intacts.",
-- 07e1e312 English: mana selects the explicit live Mana enum; current reads and forwards the actual
--     UnitPowerType identity, including Mana zero.
[2395] = "mana sélectionne l'énumération Mana explicite en direct ; current lit et transmet l'identité UnitPowerType réelle, y compris Mana zéro.",
-- c383f3b4 English: noheals selects damage only; nodmg selects healing only; other readable values
--     select both.
[2396] = "noheals sélectionne uniquement les dégâts ; nodmg uniquement les soins ; toute autre valeur lisible sélectionne les deux.",
-- d6f5cde1 English: Observe memory for ten minutes without changing polling or forcing garbage
--     collection. /rm perf memory accepts 1–1800 seconds (default 600), plus stop and report.
--     Whole-Lua heap is sampled each second; bounded retained counts every thirty seconds. Addon
--     attribution refreshes only at start and completion; intermediate values are cached with
--     unknown age. Stop completes the final boundary before you open the report. Refreshes can
--     hitch, and their cost is reported. Heap decreases do not prove collection or a leak.
[2397] = "Observe la mémoire pendant dix minutes sans modifier l'interrogation ni forcer le ramasse-miettes. /rm perf memory accepte de 1 à 1800 secondes (600 par défaut), ainsi que stop et report. Le tas Lua complet est échantillonné chaque seconde ; les décomptes conservés bornés, toutes les trente secondes. L'attribution par addon n'est actualisée qu'au début et à la fin ; les valeurs intermédiaires sont mises en cache avec un âge inconnu. Stop achève la dernière borne avant que vous n'ouvriez le rapport. Les actualisations peuvent provoquer des saccades, et leur coût est indiqué. Une baisse du tas ne prouve ni un ramassage ni une fuite.",
-- 65848052 English: Open the copyable lifetime report: whole-heap range and decreases, start/end
--     addon attribution, explicitly cached intermediate values, retained key/row counts and capture
--     overhead. Counts are not bytes; unavailable and capped observations stay explicit. Viewing
--     the report never resamples memory.
[2398] = "Ouvre le rapport de durée complète, copiable : plage et baisses du tas complet, attribution par addon au début et à la fin, valeurs intermédiaires explicitement mises en cache, décomptes de clés et de lignes conservées et surcoût de la capture. Les décomptes ne sont pas des octets ; les observations indisponibles et plafonnées restent explicites. Afficher le rapport n'échantillonne jamais la mémoire de nouveau.",
-- 35fde7b4 English: Measure normal rotation evaluation calls for ten seconds with the native
--     profiler. /rm perf runtime accepts 1–60 seconds (default 10), plus stop and report. The
--     512-dispatch safety limit can end a longer capture sooner. Polling stays unchanged. Stop
--     finalizes partial measurements; the legacy Cancel capture action still cancels. Close
--     configuration after starting. Instrumentation adds overhead; allocation is not retained
--     memory or proof of a leak. Cumulative CPU captures cannot overlap this capture.
[2399] = "Mesure pendant dix secondes, avec le profileur natif, les appels normaux d'évaluation des rotations. /rm perf runtime accepte de 1 à 60 secondes (10 par défaut), ainsi que stop et report. La limite de sécurité de 512 appels peut mettre fin plus tôt à une capture plus longue. L'interrogation reste inchangée. Arrêter finalise les mesures partielles ; l'ancienne action Annuler la capture annule toujours. Fermez la configuration après le lancement. L'instrumentation ajoute une surcharge ; une allocation n'est ni de la mémoire retenue ni la preuve d'une fuite. Les captures CPU cumulatives ne peuvent pas se chevaucher avec cette capture.",
-- b429fad0 English: Open the copyable runtime report: measured evaluation calls, native elapsed
--     time and gross allocation/deallocation counters. Missing metrics remain unavailable.
--     Measurement covers evaluation calls only, not all addon events or rendering. Reading the
--     report does not sample gameplay.
[2400] = "Ouvre le rapport d'exécution copiable : appels d'évaluation mesurés, temps écoulé natif et compteurs bruts d'allocation et de désallocation. Les métriques manquantes restent indisponibles. La mesure ne couvre que les appels d'évaluation, et non l'ensemble des événements ou de l'affichage de l'addon. La lecture du rapport n'échantillonne pas le jeu.",
-- 0eebb1cd English: Enable observation cache
-- Context: Help topic title (General settings help) for the option in the performance section that
--     turns the observation cache on or off.
[2401] = "Activer le cache d'observations",
-- 5309abf9 English: Optional reuse of repeated getCached and getRetryCached lookups. Observation
--     caching is off by default to reduce table allocations; enabling it can help conditions that
--     repeat the same lookup. Compiled condition facts are independent of this option. The checkbox
--     shows the saved choice for the next reload. Pending means it differs from the running mode.
--     Use /reload to apply it; no full game restart is needed. This choice saves immediately
--     without applying or discarding other pending settings.
[2402] = "Réutilisation facultative des recherches getCached et getRetryCached répétées. Le cache d'observations est désactivé par défaut pour réduire les allocations de tables ; l'activer peut aider les conditions qui répètent la même recherche. Les faits des conditions compilées ne dépendent pas de cette option. La case à cocher indique le choix enregistré pour le prochain rechargement. « En attente » signifie qu'il diffère du mode en cours. Utilisez /reload pour l'appliquer ; il n'est pas nécessaire de redémarrer complètement le jeu. Ce choix est enregistré immédiatement, sans appliquer ni abandonner les autres paramètres en attente.",
-- e2747e8f English: Capture native cumulative function CPU costs and call counts for ten seconds.
--     /rm perf cpu starts the same capture; /rm perf cpu 30 chooses 30 seconds (range 1–60). /rm
--     perf cpu stop finalizes partial counters; /rm perf cpu report opens the copyable result.
--     Capture uses live settings and does not apply pending changes. Close configuration after
--     starting. WoW scriptProfile must already be enabled before a reload; RM never changes it or
--     resets shared counters. Profiling itself adds overhead.
[2403] = "Capture pendant dix secondes les coûts CPU cumulés natifs des fonctions et leurs nombres d'appels. /rm perf cpu lance la même capture ; /rm perf cpu 30 choisit 30 secondes (de 1 à 60). /rm perf cpu stop finalise les compteurs partiels ; /rm perf cpu report ouvre le résultat copiable. La capture utilise les paramètres actifs et n'applique pas les modifications en attente. Fermez la configuration après le lancement. Le scriptProfile de WoW doit déjà être activé avant un rechargement ; RM ne le modifie jamais et ne réinitialise jamais les compteurs partagés. Le profilage lui-même ajoute une surcharge.",
-- 144f6416 English: Open a selectable, copyable report with total addon CPU, measured function
--     costs and calls, sample boundaries, and unavailable or replaced functions. Inclusive costs
--     overlap and must not be added together. Boundary state does not prove configuration or combat
--     stayed unchanged throughout the capture. Untracked functions and native work may account for
--     remaining costs.
[2404] = "Ouvre un rapport sélectionnable et copiable avec le CPU total de l'addon, les coûts et appels des fonctions mesurées, les bornes de l'échantillon, et les fonctions indisponibles ou remplacées. Les coûts inclusifs se chevauchent et ne doivent pas être additionnés. L'état aux bornes ne prouve pas que la configuration ou le combat sont restés inchangés pendant toute la capture. Les fonctions non suivies et le travail natif peuvent expliquer les coûts restants.",
-- 8c53a218 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. These are dependency records even when the source and local names match; a
--     different local name is an optional alias. The records identify helpers for loading, export
--     and availability checks. Accepting a completion records the dependency automatically. Typing
--     a call does not infer a dependency: add its qualified name explicitly or accept a completion.
--     WoW globals and existing addon APIs remain directly available. Namespaces are private to this
--     callback and do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is shorthand for object.method(object, x). Click the bound source name to
--     open its function; the adjacent arrow changes the mapping. Pending edits offer Apply, Discard
--     or Cancel before navigation. Renaming a function, namespace or binding does not rewrite code.
--     Missing, disabled or invalid dependencies keep consumers unavailable.
[2405] = "Choisissez un assistant source et son nom dans ce corps Lua, par exemple custom.ready ou utils.getCached. Ce sont des enregistrements de dépendance même lorsque le nom source et le nom local sont identiques ; un nom local différent est un alias facultatif. Ces enregistrements identifient les assistants pour le chargement, l'export et les vérifications de disponibilité. Accepter une complétion enregistre automatiquement la dépendance. Saisir un appel ne déduit pas de dépendance : ajoutez explicitement son nom qualifié ou acceptez une complétion. Les globales de WoW et les API existantes des addons restent directement disponibles. Les espaces de noms sont privés à ce rappel et ne fournissent pas self. Passez explicitement le receveur d'une méthode dans un appel pointé à espace de noms ; object:method(x) est un raccourci pour object.method(object, x). Cliquez sur le nom source lié pour ouvrir sa fonction ; la flèche voisine modifie l'association. Les modifications en attente proposent Appliquer, Abandonner ou Annuler avant la navigation. Renommer une fonction, un espace de noms ou une liaison ne réécrit pas le code. Les dépendances manquantes, désactivées ou invalides rendent leurs consommateurs indisponibles.",
-- 476ed166 English: Validity Function
-- Context: Yellow heading in the custom condition help: the function that checks the condition
--     itself is valid (all required fields have valid values).
[2406] = "Fonction de validité",
-- fb4e0028 English: Evaluation Function
-- Context: Yellow heading in the custom condition help: the function that evaluates the condition
--     at run time and returns true or false.
[2407] = "Fonction d'évaluation",
-- d7868586 English: Print Function
-- Context: Yellow heading in the custom condition help: the function that produces the condition's
--     one-line summary text.
[2408] = "Fonction d'affichage",
-- d548d39d English: Widget Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     editing widgets.
[2409] = "Fonction de widget",
-- e136f1bc English: Help Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     own help page.
[2410] = "Fonction d'aide",
-- 4efca0d1 English: About
-- Context: Name of the About page of the settings window (version, author, credits and links); also
--     the title of its help window.
[2411] = "À propos",
-- 96c34a07 English: Invalid
-- Context: Status label (with icon) in the rotation help: the rotation or step is not valid, so it
--     cannot be used.
[2412] = "Invalide",
-- 29ab8f0c English: Currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     true right now (shown green).
[2413] = "Actuellement satisfaite",
-- 28f0d12b English: Not currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     not true right now (shown red).
[2414] = "Non satisfaite actuellement",
-- 82e28aca English: True while your enabled boss mod (DBM or BigWigs, chosen on the Integrations
--     page) reports a boss encounter in progress. Leave Encounter ID blank for any encounter, or
--     enter the game's encounter ID, which DBM and BigWigs share, to match one boss; while an
--     encounter is active the editor shows its name and ID. This is the boss mod's report, not game
--     state: it starts when the boss mod engages and ends when it records a win, wipe or reset. Use
--     it as a switch condition for encounter-specific rotations; automatic switching picks it up on
--     its normal re-check interval. Unavailable, never simply false, when no boss mod is enabled or
--     loaded.
[2415] = "Vrai tant que votre boss mod activé (DBM ou BigWigs, choisi sur la page Intégrations) indique une rencontre de boss en cours. Laissez l'ID de rencontre vide pour accepter n'importe quelle rencontre, ou saisissez l'ID de rencontre du jeu, commun à DBM et BigWigs, pour cibler un seul boss ; pendant une rencontre active, l'éditeur affiche son nom et son ID. Il s'agit du rapport du boss mod, et non de l'état du jeu : il commence lorsque le boss mod détecte l'engagement et se termine lorsqu'il enregistre une victoire, un wipe ou une réinitialisation. Utilisez-la comme condition de bascule pour des rotations propres à une rencontre ; la bascule automatique la prend en compte à son intervalle normal de revérification. Indisponible, et jamais simplement fausse, lorsqu'aucun boss mod n'est activé ou chargé.",
-- 67327949 English: The stage (phase) your boss mod reports for the current encounter. An encounter
--     whose boss mod has not reported a stage counts as stage 1, and some intermissions are
--     reported as half stages such as 1.5. False when no encounter is in progress; unavailable when
--     no boss mod is enabled or loaded.
[2416] = "La phase que votre boss mod indique pour la rencontre en cours. Une rencontre pour laquelle le boss mod n'a indiqué aucune phase compte comme la phase 1, et certains intermèdes sont indiqués comme des demi-phases, par exemple 1.5. Fausse lorsqu'aucune rencontre n'est en cours ; indisponible lorsqu'aucun boss mod n'est activé ou chargé.",
-- 0aea56a9 English: Compares the time left on your boss mod's timer for one boss ability,
--     identified by the ability's spell ID; while timers run, the editor lists them with their IDs.
--     Timers are the boss mod's predictions and can shift, pause or be canceled. When no timer for
--     that ability is running the condition is false, so 'is less than 5 seconds' is only true
--     while a timer is actually counting down. Bars without a spell ID, such as pull or respawn
--     timers, are not tracked. Unavailable when no boss mod is enabled or loaded.
[2417] = "Compare le temps restant sur le minuteur de votre boss mod pour une technique de boss, identifiée par l'ID de sort de cette technique ; pendant que des minuteurs tournent, l'éditeur les liste avec leurs ID. Les minuteurs sont des prédictions du boss mod et peuvent se décaler, être mis en pause ou être annulés. Lorsqu'aucun minuteur n'est en cours pour cette technique, la condition est fausse : « est inférieur à 5 secondes » n'est donc vrai que lorsqu'un minuteur décompte réellement. Les barres sans ID de sort, comme les minuteurs de pull ou de réapparition, ne sont pas suivies. Indisponible lorsqu'aucun boss mod n'est activé ou chargé.",
-- 68c38a65 English: Sound Alert
-- Context: Yellow heading in the rotation help, in the announcements part: the sound that can be
--     played along with an announcement.
[2418] = "Alerte sonore",
-- 7a0ac7f9 English: Any (OR) checks children in order and stops at the first match. An empty group
--     does not match. Encountered unavailable data remains unavailable; later children are skipped.
[2419] = "N'importe laquelle (OU) vérifie les sous-conditions dans l'ordre et s'arrête à la première correspondance. Un groupe vide ne correspond pas. Les données indisponibles rencontrées restent indisponibles ; les sous-conditions suivantes sont ignorées.",
-- 0cda3eb2 English: Every rotation has an identifier (ID), shown beside its priority: type /rm set
--     <id> to choose it (any case), /rm set auto to go back to automatic switching, and /rm list to
--     see every identifier. A Built In's identifier is fixed; yours is made from its name until you
--     change it.
[2420] = "Chaque rotation a un identifiant (ID), affiché à côté de sa priorité : tapez /rm set <id> pour la choisir (majuscules ou minuscules), /rm set auto pour revenir à la bascule automatique et /rm list pour voir tous les identifiants. L'identifiant d'une rotation intégrée est fixe ; le vôtre est formé à partir de son nom jusqu'à ce que vous le changiez.",
-- 5530025a English: Choosing a rotation
-- Context: Heading in the rotation help: how the addon decides which rotation is used. Noun phrase
--     with gerund.
[2421] = "Choisir une rotation",
-- 359bbdff English: Automatic switching tries the enabled rotations in priority order, yours and
--     Built Ins alike: higher numbers are tried first, equal priorities by name. It picks the first
--     that matches; a rotation with no switch condition always matches, so turn it off to keep it
--     from being chosen. The fallback (Default) is used only when none matches. The rotation list
--     is sorted in this same order and shows each priority.
[2422] = "La bascule automatique essaie les rotations activées par ordre de priorité, les vôtres comme les rotations intégrées : les nombres les plus élevés sont essayés en premier, et les priorités égales par nom. Elle choisit la première qui correspond ; une rotation sans condition de bascule correspond toujours, désactivez-la donc pour éviter qu'elle soit choisie. La rotation de repli (Par défaut) n'est utilisée que si aucune ne correspond. La liste des rotations est triée dans ce même ordre et affiche chaque priorité.",
-- 1adf9c9d English: Priority sits beside Enabled at the top of the editor. A Built In cannot be
--     edited, but its Enabled setting and priority are yours to change for this profile: they are
--     saved at once, shown in amber when they differ from how it ships, and Reset to default puts
--     it back. Copy a Built In to your rotations to edit anything else.
[2423] = "La priorité se trouve à côté de Activé, en haut de l'éditeur. Une rotation intégrée ne peut pas être modifiée, mais son réglage Activé et sa priorité vous appartiennent pour ce profil : ils sont enregistrés immédiatement, affichés en ambre quand ils diffèrent de la livraison d'origine, et Rétablir les valeurs par défaut les remet comme avant. Copiez une rotation intégrée dans vos rotations pour modifier tout le reste.",
-- 89d48b07 English: A Built In shows a blue Read-Only pill in place of Undo and Redo; Duplicate
--     makes your own copy. It loads only for the edition and class it was written for (the pill's
--     tooltip). The specializations it is for show in the picker before its name; any level it
--     needs is part of its switch condition. The switch's tooltip says when it can be selected
--     together with another rotation, or is for another specialization.
[2424] = "Une rotation intégrée affiche une pastille bleue Lecture seule à la place de Défaire et Refaire ; Dupliquer en crée votre propre copie. Elle ne se charge que pour l'édition et la classe pour lesquelles elle a été écrite (l'infobulle de la pastille). Les spécialisations auxquelles elle est destinée s'affichent dans le sélecteur avant son nom ; tout niveau requis fait partie de sa condition de bascule. L'infobulle de l'interrupteur indique quand elle peut être sélectionnée en même temps qu'une autre rotation, ou si elle est destinée à une autre spécialisation.",
-- c85105a0 English: In the list, a red border means the rotation cannot be selected (the tooltip
--     names why), gray means it is switched off, and an amber bar means it can be selected at the
--     same time as another rotation (yours or Built In), so only priority decides between them; a
--     wider bar means they also have the same priority and the name decides. /rm why lists the
--     order and what automatic switching would choose now.
[2425] = "Dans la liste, une bordure rouge signifie que la rotation ne peut pas être sélectionnée (l'infobulle en donne la raison), le gris qu'elle est désactivée, et une barre ambre qu'elle peut être sélectionnée en même temps qu'une autre rotation (la vôtre ou une rotation intégrée), de sorte que seule la priorité les départage ; une barre plus large signifie qu'elles ont aussi la même priorité et que le nom décide. /rm why liste l'ordre et ce que la bascule automatique choisirait maintenant.",
-- 929902f7 English: Each rotation says which specializations it is for, in the picker before its
--     name: several, or Any. It is listed, in the minimap menu and for /rm set, only while you play
--     one of them; its switch condition never hides it. Automatic switching checks the
--     specialization first, then the switch condition, then priority; a rotation with no switch
--     condition matches whenever its specialization and level apply, so priority alone decides;
--     turn it off to keep it for choosing by hand. The specialization menu above the list's search
--     box starts at the one you are playing; choose another, or All specializations, to see theirs.
--     Where the game has dual specialization instead of named specializations (Classic Era, TBC,
--     Wrath, Cataclysm and Forever), they are your primary and secondary talents: exports leave
--     them out, and an import is for the talents the list shows.
[2426] = "Chaque rotation indique, dans le sélecteur avant son nom, pour quelles spécialisations elle est faite : plusieurs, ou N'importe laquelle. Elle n'est listée, dans le menu de la minicarte et pour /rm set, que lorsque vous jouez l'une d'elles ; sa condition de bascule ne la masque jamais. La bascule automatique vérifie d'abord la spécialisation, puis la condition de bascule, puis la priorité ; une rotation sans condition de bascule correspond dès que sa spécialisation et son niveau s'appliquent, la priorité seule décide donc ; désactivez-la pour ne la choisir qu'à la main. Le menu de spécialisation au-dessus de la zone de recherche de la liste commence par celle que vous jouez ; choisissez-en une autre, ou Toutes les spécialisations, pour voir les leurs. Lorsque le jeu propose la double spécialisation au lieu de spécialisations nommées (Classic Era, TBC, Wrath, Cataclysm et Forever), il s'agit de vos talents principaux et secondaires : les exports les omettent, et un import vaut pour les talents que la liste affiche.",
-- 4c969557 English: Stop ends lower priority actions. The implicit auto-attack (Attack or Shoot)
--     remains eligible unless you suppress it. An unavailable Stop condition also suppresses it.
--     Optional reminders remain independent.
[2427] = "Arrêt met fin aux actions de priorité inférieure. L'attaque automatique implicite (Attaque ou Tir) reste éligible, sauf si vous la supprimez. Une condition d'Arrêt indisponible la supprime aussi. Les rappels facultatifs restent indépendants.",
-- 4db9065c English: All (AND) checks children in order and stops at the first non-match. An empty
--     group matches. Encountered unavailable data remains unavailable; later children are skipped.
[2428] = "Toutes (ET) vérifie les sous-conditions dans l'ordre et s'arrête à la première non-correspondance. Un groupe vide correspond. Les données indisponibles rencontrées restent indisponibles ; les sous-conditions suivantes sont ignorées.",
-- 2253ae22 English: Select cards with Ctrl-click or Shift-click. Group with All or Any, negate
--     each, move or drag, and remove. Undo and Redo affect only the draft until Apply. Groups can
--     be named and collapsed.
[2429] = "Sélectionnez des cartes avec Ctrl-clic ou Maj-clic. Groupez-les avec Toutes ou N'importe laquelle, inversez chacune, déplacez-les ou faites-les glisser, et retirez-les. Défaire et Refaire n'affectent que le brouillon jusqu'à Appliquer. Les groupes peuvent être nommés et réduits.",
-- ef5cde35 English: Built In and custom rotations use the same cards. Built In rotations are
--     read-only; enable or disable them, inspect their conditions, or Duplicate to edit.
[2430] = "Les rotations intégrées et personnalisées utilisent les mêmes cartes. Les rotations intégrées sont en lecture seule : activez-les ou désactivez-les, inspectez leurs conditions, ou utilisez Dupliquer pour les modifier.",
-- 598c73a5 English: Custom edits stay in a private draft. Apply saves; Discard restores the saved
--     rotation. Undo and Redo include card deletion, movement, fields and conditions. Apply before
--     reloading or logging out.
[2431] = "Les modifications personnalisées restent dans un brouillon privé. Appliquer enregistre ; Abandonner restaure la rotation enregistrée. Défaire et Refaire couvrent la suppression et le déplacement des cartes, les champs et les conditions. Appliquez avant de recharger ou de vous déconnecter.",
-- 55e4c200 English: Closing the window retains drafts for this session. Switching rotations or
--     opening comparison or transfer asks whether to Apply, Discard or Cancel when changes are
--     pending.
[2432] = "Fermer la fenêtre conserve les brouillons pour cette session. Changer de rotation, ou ouvrir la comparaison ou le transfert, demande s'il faut Appliquer, Abandonner ou Annuler lorsque des modifications sont en attente.",
-- 770e0bb6 English: The switch condition selects the rotation automatically; with none, it is
--     selected whenever its specialization and level apply. Edit changes its condition tree. The
--     fallback rotation is selected when no other rotation matches.
[2433] = "La condition de bascule sélectionne la rotation automatiquement ; sans condition, elle est sélectionnée dès que sa spécialisation et son niveau s'appliquent. Modifier change son arbre de conditions. La rotation de repli est sélectionnée lorsqu'aucune autre rotation ne correspond.",
-- 7423362f English: Cooldown cards have their own scrolling workspace and highlight independently
--     of the sequence. Add cooldown creates a reminder; clicking its action shows local highlight
--     settings.
[2434] = "Les cartes de temps de recharge ont leur propre espace de travail défilant et sont mises en surbrillance indépendamment de la séquence. Ajouter un temps de recharge crée un rappel ; cliquer sur son action affiche les paramètres locaux de surbrillance.",
-- 758bf6a1 English: Add action appends a priority action. Drag an Add control into a gap to insert
--     there. Click a card name to rename it, expand for action fields, or click its condition text
--     to edit the guard.
[2435] = "Ajouter une action ajoute une action prioritaire à la fin. Faites glisser un contrôle Ajouter dans un espace pour l'insérer à cet endroit. Cliquez sur le nom d'une carte pour la renommer, développez-la pour afficher les champs d'action, ou cliquez sur le texte de sa condition pour modifier la garde.",
-- 9b6cac99 English: Adding a branch moves following steps into its True arm. False is on the left
--     in red; True is on the right in green. The mode pill cycles Evaluate condition, Always true
--     and Always false. Unreachable cards are gray.
[2436] = "Ajouter une branche déplace les étapes suivantes dans son bras Vrai. Faux est à gauche en rouge ; Vrai est à droite en vert. La pastille de mode alterne entre Évaluer la condition, Toujours vrai et Toujours faux. Les cartes inaccessibles sont grisées.",
-- 5fc9817f English: Ordinary dragging moves one card and its own subtree. Hold Ctrl when starting a
--     drag to carry that card and every following sibling, including their branch subtrees. Drop
--     into a branch arm gap to move there. Up / Down always moves one card. A group cannot be
--     dropped into itself or a carried descendant.
[2437] = "Un glisser ordinaire déplace une carte et son propre sous-arbre. Maintenez Ctrl au début du glisser pour emporter cette carte et toutes les cartes sœurs suivantes, y compris leurs sous-arbres de branches. Déposez dans un espace d'un bras de branche pour l'y déplacer. Monter / Descendre déplace toujours une seule carte. Un groupe ne peut pas être déposé dans lui-même ni dans un descendant emporté.",
-- a6e094f9 English: An evaluated branch follows one arm, then rejoins later siblings. Stop ends the
--     sequence. Independent cooldowns still apply; implicit auto-attack (Attack or Shoot) remains
--     available unless the Stop suppresses it.
[2438] = "Une branche évaluée suit un bras, puis rejoint les cartes sœurs suivantes. Arrêt met fin à la séquence. Les temps de recharge indépendants s'appliquent toujours ; l'attaque automatique implicite (Attaque ou Tir) reste disponible, sauf si l'Arrêt la supprime.",
-- 4e0f26c5 English: Invalid or incomplete cards remain editable. Apply validates both branch arms
--     without running custom condition code. Deleting a whole custom rotation requires confirmation
--     and cannot be undone.
[2439] = "Les cartes invalides ou incomplètes restent modifiables. Appliquer valide les deux bras de chaque branche sans exécuter le code des conditions personnalisées. La suppression d'une rotation personnalisée entière demande une confirmation et est irréversible.",
-- c54e950a English: List and Cooldowns use flat scrollbars or the mouse wheel. Diagram uses wheel
--     zoom and dragging empty space to pan. Window scaling applies when the slider is released and
--     also affects RM child windows.
[2440] = "Liste et Temps de recharge utilisent des barres de défilement plates ou la molette de la souris. Diagramme utilise la molette pour zoomer et le glisser d'un espace vide pour se déplacer. La mise à l'échelle de la fenêtre s'applique au relâchement du curseur et affecte aussi les fenêtres secondaires de RM.",
-- e90e0aef English: Highlight preview
-- Context: Help topic title in General settings help for the highlight preview (the example that
--     shows the chosen highlight).
[2441] = "Aperçu de la surbrillance",
-- aafdf428 English: Add category
-- Context: Help topic title in the Conditions help for the Add category button.
[2442] = "Ajouter une catégorie",
-- 539a15c9 English: Choose and edit
-- Context: Section title in the condition editor help: how to choose a condition type and edit its
--     fields.
[2443] = "Choisir et modifier",
-- cfb4186c English: Click a condition type to search or browse categories. Dismissing the picker or
--     choosing the same type keeps its fields. Click the condition summary to edit its fields. The
--     chevron switches between name only and summary; the double chevron closes the fields.
[2444] = "Cliquez sur un type de condition pour rechercher ou parcourir les catégories. Fermer le sélecteur ou choisir le même type conserve ses champs. Cliquez sur le résumé de la condition pour modifier ses champs. Le chevron bascule entre le nom seul et le résumé ; le double chevron ferme les champs.",
-- 0e19bead English: Click a name to rename it. Clear a custom step name to restore its action name.
--     Click a collapsed title to show its summary. Click action or condition text to open its
--     details; the double chevron returns from fields to the summary.
[2445] = "Cliquez sur un nom pour le renommer. Effacez le nom personnalisé d'une étape pour rétablir le nom de son action. Cliquez sur un titre replié pour afficher son résumé. Cliquez sur le texte d'une action ou d'une condition pour ouvrir ses détails ; le double chevron revient des champs au résumé.",
-- 73ff3024 English: Click condition text to edit when this card can run. Enabled / Disabled
--     preserves the card while switching its participation. Actions also require known or carried
--     actions, usable resources, cooldown readiness and valid range.
[2446] = "Cliquez sur le texte de la condition pour modifier quand cette carte peut s'exécuter. Activé / Désactivé conserve la carte tout en changeant sa participation. Les actions exigent aussi des actions connues ou portées, des ressources utilisables, un temps de recharge prêt et une portée valide.",
-- 9c1c1630 English: Click the action to edit its type, spell or item. The leading icon previews the
--     effect. Effect selects a style; Magnification changes its size. Click the swatch or edit RGBA
--     on the 0–1 scale. Arrows adjust position; V / H show offsets. Default restores profile
--     values. Sound selection and Play preview an audible reminder.
[2447] = "Cliquez sur l'action pour modifier son type, son sort ou son objet. L'icône de tête prévisualise l'effet. Effet sélectionne un style ; Agrandissement change sa taille. Cliquez sur l'échantillon de couleur ou modifiez les valeurs RGBA sur l'échelle 0–1. Les flèches ajustent la position ; V / H affichent les décalages. Par défaut rétablit les valeurs du profil. Le choix du son et Lire prévisualisent un rappel sonore.",
-- 3edd382d English: Click the guard text to edit the branch condition. Evaluate uses that
--     condition; Always true / Always false skips it. False is left and red; True is right and
--     green. The branch icon hides both arms without changing them. Click True or False to fold
--     only that arm; its hidden count remains visible. Gray cards in a forced arm are unreachable.
[2448] = "Cliquez sur le texte de garde pour modifier la condition de la branche. Évaluer utilise cette condition ; Toujours vrai / Toujours faux l'ignore. Faux est à gauche, en rouge ; Vrai est à droite, en vert. L'icône de branche masque les deux bras sans les modifier. Cliquez sur Vrai ou Faux pour replier uniquement ce bras ; son nombre d'éléments masqués reste visible. Les cartes grises dans un bras forcé sont inaccessibles.",
-- 55129537 English: Conditions and state
-- Context: Section title in the rotation editor help for the cards that combine conditions and the
--     state they show.
[2449] = "Conditions et état",
-- eacf49cb English: Configure recommendation timing, automatic switching, history, preview and
--     profile highlight defaults. Labels are on the left. Checkboxes toggle options, sliders show
--     numeric values, and fields validate before saving.
[2450] = "Configurez le délai des recommandations, la bascule automatique, l'historique, l'aperçu et les valeurs par défaut de surbrillance du profil. Les libellés sont à gauche. Les cases à cocher activent les options, les curseurs affichent des valeurs numériques et les champs sont validés avant l'enregistrement.",
-- 63ee762f English: Drag one card into a highlighted gap; hold Ctrl when starting the drag to carry
--     that card and all following siblings. A branch always carries its children. Use Up / Down on
--     the left to move one card. Duplicate copies the card and the red trash can deletes it.
--     Cooldowns are independent, so they have no move arrows.
[2451] = "Faites glisser une carte dans un espace en surbrillance ; maintenez Ctrl en commençant le glissement pour emporter cette carte et toutes ses sœurs suivantes. Une branche emporte toujours ses enfants. Utilisez Haut / Bas à gauche pour déplacer une carte. Dupliquer copie la carte et la corbeille rouge la supprime. Les temps de recharge sont indépendants, ils n'ont donc pas de flèches de déplacement.",
-- 24e03e5b English: Drag a card into one highlighted gap, or use the left-side Up / Down arrows.
--     Hold Ctrl when starting a drag to carry the card and all following siblings. Groups always
--     carry their children. Unavailable moves are gray. Ctrl-click or Shift-click selects several
--     cards for grouping; dragging an existing selection moves that selection. Duplicate copies a
--     card; Split group removes its wrapper; the red trash can deletes it. Add condition and Add
--     group append when clicked or insert where dropped.
[2452] = "Faites glisser une carte dans un espace en surbrillance, ou utilisez les flèches Haut / Bas à gauche. Maintenez Ctrl en commençant un glissement pour emporter la carte et toutes ses sœurs suivantes. Les groupes emportent toujours leurs enfants. Les déplacements impossibles sont grisés. Ctrl-clic ou Maj-clic sélectionne plusieurs cartes pour les grouper ; faire glisser une sélection existante déplace cette sélection. Dupliquer copie une carte ; Dissocier le groupe retire son conteneur ; la corbeille rouge la supprime. Ajouter une condition et Ajouter un groupe ajoutent à la fin au clic ou insèrent à l'endroit du dépôt.",
-- adb0a440 English: Editing settings
-- Context: Section title in the settings help: how text fields and the Apply/Discard draft work.
[2453] = "Modification des paramètres",
-- 1352b3ca English: Highlight effects
-- Context: Section title in the rotation editor help for the highlight effect options of an action
--     card.
[2454] = "Effets de surbrillance",
-- fc1e5a5a English: If / Unless toggles negation. Enabled / Disabled keeps the saved fields while
--     skipping evaluation. All / Any changes AND / OR. Click a group name to rename it; the branch
--     icon hides or shows its children. Gray descendants cannot be reached.
[2455] = "Si / Sauf si inverse la condition. Activé / Désactivé conserve les champs enregistrés tout en ignorant l'évaluation. Toutes / N'importe laquelle bascule entre ET / OU. Cliquez sur le nom d'un groupe pour le renommer ; l'icône de branche masque ou affiche ses enfants. Les descendants grisés sont inaccessibles.",
-- 0e86051f English: Names and details
-- Context: Section title in the rotation editor help: how to rename steps and open their details.
[2456] = "Noms et détails",
-- e0d1f576 English: Search or filter the rotation roster, then select a rotation. Blue Built In
--     rotations use the same editor but remain read-only; Duplicate makes an editable copy. The
--     name and Metadata describe the rotation. Switch condition selects when it applies. Use the
--     Rotation and Cooldowns tabs to select the content below the switch condition. Cooldowns
--     highlight independently of the ordered rotation.
[2457] = "Recherchez ou filtrez la liste des rotations, puis sélectionnez une rotation. Les rotations Intégrées, en bleu, utilisent le même éditeur mais restent en lecture seule ; Dupliquer en crée une copie modifiable. Le nom et les Métadonnées décrivent la rotation. La condition de bascule détermine quand elle s'applique. Utilisez les onglets Rotation et Temps de recharge pour sélectionner le contenu sous la condition de bascule. Les temps de recharge sont mis en surbrillance indépendamment de la rotation ordonnée.",
-- 42691826 English: The question mark opens full Help for its subject. Hover controls for brief
--     tips. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes.
--     Red borders mark invalid or incomplete data.
[2458] = "Le point d'interrogation ouvre l'aide complète sur son sujet. Survolez les contrôles pour obtenir de brèves astuces. Défaire / Refaire agissent sur le brouillon. Appliquer enregistre ; Abandonner ou Annuler renonce aux modifications du brouillon. Les bordures rouges signalent des données invalides ou incomplètes.",
-- d68ae9c9 English: Using this page
-- Context: Section title at the top of the help for the Functions and Integrations pages: a short
--     guide to the page.
[2459] = "Utiliser cette page",
-- 642f28cb English: Version, author, credits and project links are shown here. Click a link field
--     to select its text for copying.
[2460] = "La version, l'auteur, les remerciements et les liens du projet sont affichés ici. Cliquez sur un champ de lien pour sélectionner son texte et le copier.",
-- 9cea69fd English: Window controls
-- Context: Section title in the help: the buttons and controls of the window frame.
[2461] = "Contrôles de la fenêtre",
-- efe10c80 English: Primary
-- Context: Help topic title for the settings made for the first (primary) talent specialization;
--     used only when the game has no word for it.
[2462] = "Principal",
-- 62f2ccff English: Secondary
-- Context: Help topic title for the settings made for the second (secondary) talent specialization;
--     used only when the game has no word for it.
[2463] = "Secondaire",
-- a91d0087 English: Delete category
-- Context: Help topic title in the Conditions help for the Delete category button.
[2464] = "Supprimer la catégorie",
-- 315dca68 English: Rename the selected category in Manage categories. Built-in categories cannot
--     be renamed or deleted.
[2465] = "Renommez la catégorie sélectionnée dans Gérer les catégories. Les catégories intégrées ne peuvent être ni renommées ni supprimées.",
-- f6fad90e English: Add an empty named category from the category-management list. Move To in
--     condition settings assigns a condition to it.
[2466] = "Ajoutez une catégorie nommée vide depuis la liste de gestion des catégories. Déplacer vers, dans les paramètres de condition, lui attribue une condition.",
-- b31029f7 English: In Manage categories, move the selected category earlier in the category list.
[2467] = "Dans Gérer les catégories, avancez la catégorie sélectionnée dans la liste des catégories.",
-- 277b5e7b English: In Manage categories, move the selected category later in the category list.
[2468] = "Dans Gérer les catégories, reculez la catégorie sélectionnée dans la liste des catégories.",
-- 32a806a4 English: Delete a named category after confirmation. Its conditions remain available
--     under Other; their definitions are preserved.
[2469] = "Supprimez une catégorie nommée après confirmation. Ses conditions restent disponibles dans Autre ; leurs définitions sont conservées.",
-- e20c9279 English: Filter the visible condition list by name or identifier. The category filter
--     still applies.
[2470] = "Filtrez la liste des conditions visibles par nom ou identifiant. Le filtre de catégorie s'applique toujours.",
-- 2715ffec English: Allow this condition type to be used when automatically selecting a rotation.
[2471] = "Autoriser l'utilisation de ce type de condition lors de la sélection automatique d'une rotation.",
-- 91c0665b English: Hide this condition from the Other picker category. Explicit named-category and
--     Switch membership remain available.
[2472] = "Masquer cette condition de la catégorie Autre du sélecteur. L'appartenance explicite à une catégorie nommée et à Bascule reste disponible.",
-- 4a954399 English: Condition order
-- Context: Help topic title in the Conditions help: how to reorder conditions and categories.
[2473] = "Ordre des conditions",
-- 54375409 English: Apply / Cancel
-- Context: Help topic title for the pair of buttons that save or abandon changes in the announce
--     and effect editors.
[2474] = "Appliquer / Annuler",
-- af06c200 English: Choose a named category or Other, then use Apply beside the destination to
--     stage the move. Page Apply saves all pending changes. Use Switch Condition separately for
--     automatic-switch availability.
[2475] = "Choisissez une catégorie nommée ou Autre, puis utilisez Appliquer à côté de la destination pour préparer le déplacement. Appliquer, sur la page, enregistre toutes les modifications en attente. Utilisez Condition de bascule séparément pour la disponibilité de la bascule automatique.",
-- 304b61a5 English: Select several cards
-- Context: Section title in the rotation editor help: how to select more than one rotation card.
[2476] = "Sélectionner plusieurs cartes",
-- 1e77459b English: Ctrl-click cards to add or remove them from the selection; Shift-click selects
--     the siblings between it and the last clicked card. Shift-drag on empty canvas draws a box
--     that selects every card it touches (Ctrl+Shift-drag adds). With several cards selected, the
--     strip above the canvas groups them as All or Any, and Duplicate, Enable, Disable and Delete
--     act on every selected card; one Undo reverses each. Drag any selected card to move the
--     selection.
[2477] = "Ctrl-clic sur des cartes les ajoute à la sélection ou les en retire ; Maj-clic sélectionne les cartes sœurs entre celle-ci et la dernière carte cliquée. Maj-glisser sur une zone vide du canevas trace un cadre qui sélectionne toutes les cartes qu'il touche (Ctrl+Maj-glisser ajoute). Lorsque plusieurs cartes sont sélectionnées, la bande au-dessus du canevas les regroupe en Toutes ou N'importe laquelle, et Dupliquer, Activer, Désactiver et Supprimer agissent sur chaque carte sélectionnée ; un seul Défaire annule chaque opération. Faites glisser n'importe quelle carte sélectionnée pour déplacer la sélection.",
-- 47834c1a English: Ctrl-click cards to add or remove them from the selection; Shift-click a title
--     or condition to select the siblings between it and the last clicked card. Shift-drag on empty
--     canvas draws a box that selects every card it touches (Ctrl+Shift-drag adds). Drag any
--     selected card to move the whole selection to one gap. Beside Apply, Duplicate, Enable,
--     Disable and Delete act on every selected card, and one Undo reverses each. Branches keep
--     their Evaluate / Always mode. Click empty canvas to clear the selection.
[2478] = "Ctrl-clic sur des cartes les ajoute à la sélection ou les en retire ; Maj-clic sur un titre ou une condition sélectionne les cartes sœurs entre celle-ci et la dernière carte cliquée. Maj-glisser sur une zone vide du canevas trace un cadre qui sélectionne toutes les cartes qu'il touche (Ctrl+Maj-glisser ajoute). Faites glisser n'importe quelle carte sélectionnée pour déplacer toute la sélection vers un même espace. À côté d'Appliquer, Dupliquer, Activer, Désactiver et Supprimer agissent sur chaque carte sélectionnée, et un seul Défaire annule chaque opération. Les branches conservent leur mode Évaluer / Toujours. Cliquez sur une zone vide du canevas pour effacer la sélection.",
-- 2c6fdc3c English: Select a profile in the sidebar to inspect it, then Activate profile to switch.
--     New and Duplicate open a named draft with Apply and Cancel. Import stages a validated new
--     profile; Compare shows setting differences. Copy and Reset replace the active profile after
--     confirmation; the red trash deletes an inactive profile.
[2479] = "Sélectionnez un profil dans la barre latérale pour l'examiner, puis Activer le profil pour en changer. Nouveau et Dupliquer ouvrent un brouillon nommé avec Appliquer et Annuler. Importer prépare un nouveau profil validé ; Comparer montre les différences de paramètres. Copier et Réinitialiser remplacent le profil actif après confirmation ; la corbeille rouge supprime un profil inactif.",
-- 80f29cb1 English: The condition ordering controls are arrows and draggable rows in the sidebar of
--     the selected category. In Manage categories, the same controls order the categories
--     themselves.
[2480] = "Les contrôles d'ordre des conditions sont les flèches et les lignes déplaçables de la barre latérale de la catégorie sélectionnée. Dans Gérer les catégories, les mêmes contrôles ordonnent les catégories elles-mêmes.",
-- fdef8f0b English: Unticked, any rank of the spell matches: a numeric spell selection also
--     recognizes auras with the same readable localized spell name. Ticked, only the exact spell ID
--     you chose matches. Conditions saved before this option keep the exact ID until you untick it.
--     Spell names already match by name. Unavailable metadata or restricted aura identity stays
--     unavailable, including under NOT. Different spells sharing a name can match; tick the option
--     when that distinction matters.
[2481] = "Décochée, n'importe quel rang du sort correspond : une sélection numérique de sort reconnaît aussi les auras portant le même nom de sort localisé lisible. Cochée, seul l'ID de sort exact choisi correspond. Les conditions enregistrées avant cette option conservent l'ID exact jusqu'à ce que vous la décochiez. Les noms de sort correspondent déjà par nom. Des métadonnées indisponibles ou une identité d'aura restreinte restent indisponibles, y compris sous NOT. Des sorts différents partageant un nom peuvent correspondre ; cochez l'option lorsque cette distinction compte.",
-- a851dbf4 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches.
[2482] = "Décochée (par défaut), n'importe quel rang du sort correspond. Cochée, seul le rang choisi correspond.",
-- 6ef93df0 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches, and that rank must be on your action bars.
[2483] = "Décochée (par défaut), n'importe quel rang du sort correspond. Cochée, seul le rang choisi correspond, et ce rang doit se trouver sur vos barres d'action.",
-- 5c9c3144 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Conditions saved with a spell name keep matching by that name. If
--     the client cannot read the spell being cast, the condition is unavailable, including under
--     NOT.
[2484] = "Un sort choisi dans l'éditeur est comparé par son ID de sort, de sorte que la condition fonctionne dans toutes les langues du client. Les conditions enregistrées avec un nom de sort continuent de correspondre par ce nom. Si le client ne peut pas lire le sort lancé, la condition est indisponible, y compris sous NOT.",
-- c647cb40 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Any rank of that spell matches unless Use this exact spell rank is
--     ticked. Conditions saved with a spell name keep matching by that name. If the client cannot
--     read the spell being cast, the condition is unavailable, including under NOT.
[2485] = "Un sort choisi dans l'éditeur est reconnu par son ID de sort, de sorte que la condition fonctionne dans toutes les langues du client. Tout rang de ce sort correspond, sauf si Utiliser exactement ce rang de sort est coché. Les conditions enregistrées avec un nom de sort continuent de correspondre à ce nom. Si le client ne peut pas lire le sort en cours d'incantation, la condition est indisponible, y compris sous NOT.",
-- 51b10901 English: Navigating rotations
-- Context: Section title in the rotation editor help: zooming, panning and switching views.
[2486] = "Naviguer dans les rotations",
-- 35f68027 English: Enabled / Disabled
-- Context: Help topic title in the Announces help for the checkbox that switches an announcement on
--     or off.
[2487] = "Activé / Désactivé",
-- 922d8056 English: Announcement substitutions
-- Context: Help topic title in the Announces help: the {{target}}, {{spell}} and {{event}}
--     placeholders that can be put into announcement text.
[2488] = "Substitutions d'annonce",
-- 63ff2d53 English: New, Duplicate, Import/Export and Compare
[2489] = "Nouveau, Dupliquer, Importer/Exporter et Comparer",
-- baa6c2fc English: Announcement details stay always expanded while editing. Press Enter or leave a
--     text field to stage its value; Apply saves the draft. Invalid fields must be corrected before
--     Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you
--     type. The page Help icon explains every option and text substitution.
[2490] = "Les détails de l'annonce restent toujours développés pendant la modification. Appuyez sur Entrée ou quittez un champ de texte pour préparer sa valeur ; Appliquer enregistre le brouillon. Les champs invalides doivent être corrigés avant Appliquer ; Abandonner renonce aux modifications en attente. Les sélecteurs avec recherche s'ouvrent au clic et filtrent à mesure que vous tapez. L'icône d'aide de la page explique chaque option et chaque substitution de texte.",
-- 79d463fa English: Announce selected spell casts or item uses independently of your active
--     rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the
--     sidebar, or use New to prepare one. The trigger applies to every ordered output card; each
--     card has its own destination and conditions. These settings do not cast spells or use items.
--     Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only
--     clients.
[2491] = "Annoncez certains lancers de sorts ou utilisations d'objets indépendamment de votre rotation active, ou invoquez directement une entrée Via script/macro configurée. Sélectionnez une entrée dans la barre latérale, ou utilisez Nouveau pour en préparer une. Le déclencheur s'applique à chaque carte de sortie ordonnée ; chaque carte a sa propre destination et ses propres conditions. Ces paramètres ne lancent pas de sorts et n'utilisent pas d'objets. Les annonces déclenchées par un lancer suivent la politique de RM sur les données de combat et ne s'exécutent pas sur les clients en mode référence uniquement.",
-- 405280cc English: An optional name identifies this announcement in the sidebar. Without one, the
--     action name or Via Script/Macro identifier is used. Changing this display name does not
--     change the watched action or callable identifier.
[2492] = "Un nom facultatif identifie cette annonce dans la barre latérale. Sans nom, le nom de l'action ou l'identifiant Via script/macro est utilisé. Changer ce nom d'affichage ne change ni l'action surveillée ni l'identifiant appelable.",
-- d90e5cae English: Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the
--     previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast
--     event or stored action; switching back restores the event selector. Choosing the current type
--     keeps its fields.
[2493] = "Choisissez Sort, Sort de familier, Objet ou Via script/macro. Changer de type efface l'action précédente et le choix de rang exact. Via script/macro utilise un Identifiant au lieu d'un événement de lancer ou d'une action enregistrée ; revenir en arrière rétablit le sélecteur d'événement. Choisir le type actuel conserve ses champs.",
-- 198d0d82 English: Watch one of your spells. Choose the spell in the searchable field below Action
--     Type.
[2494] = "Surveiller l'un de vos sorts. Choisissez le sort dans le champ avec recherche sous Type d'action.",
-- bb010073 English: Watch a spell from your pet spellbook. The spell selector uses the pet catalog
--     for this action type.
[2495] = "Surveiller un sort du grimoire de votre familier. Le sélecteur de sort utilise le catalogue du familier pour ce type d'action.",
-- c331b8d1 English: Watch item-use spells from a reusable item set or a custom list. This is an
--     announcement trigger; it does not choose an item to use for you.
[2496] = "Surveiller les sorts d'utilisation d'objet d'un ensemble d'objets réutilisable ou d'une liste personnalisée. Il s'agit d'un déclencheur d'annonce ; il ne choisit pas pour vous un objet à utiliser.",
-- 6e216ab8 English: Search by spell name, select a result, or drag a spell from your spellbook or
--     action bar into the field. The icon and name identify the selected spell. Spell and pet spell
--     choices keep their respective catalog scope.
[2497] = "Recherchez par nom de sort, sélectionnez un résultat, ou faites glisser un sort depuis votre grimoire ou votre barre d'action dans le champ. L'icône et le nom identifient le sort sélectionné. Les choix de sort et de sort de familier conservent la portée de leur catalogue respectif.",
-- 691e05e6 English: Unchecked (the default), any known rank of the spell matches. Checked limits
--     matching to the rank you chose. This checkbox is shown only for Spell and Pet Spell, and only
--     on clients with spell ranks.
[2498] = "Décochée (par défaut), n'importe quel rang connu du sort correspond. Cochée, limite la correspondance au rang choisi. Cette case n'apparaît que pour Sort et Sort de familier, et uniquement sur les clients qui ont des rangs de sort.",
-- c75f5c21 English: Choose a reusable set, or Custom to edit this announcement's own list. For a
--     custom list, search for or drag items into the fields; Add item appends one and a red trash
--     can removes an entry. Any matching item-use spell in the list can trigger the announcement;
--     list order does not limit announcements to the first carried item. Changes to a shared set
--     belong on the Item Sets page.
[2499] = "Choisissez un ensemble réutilisable, ou Personnalisé pour modifier la liste propre à cette annonce. Pour une liste personnalisée, recherchez des objets ou faites-les glisser dans les champs ; Ajouter un objet en ajoute un à la fin et une corbeille rouge retire une entrée. Tout sort d'utilisation d'objet correspondant de la liste peut déclencher l'annonce ; l'ordre de la liste ne limite pas les annonces au premier objet porté. Les modifications d'un ensemble partagé se font sur la page Ensembles d'objets.",
-- 09fd4592 English: For automatic action types, choose which observed cast event triggers this
--     entry. A start, stop, interruption, failure or delay is different from a successful cast.
--     Client support determines which events and observations are available. Via Script/Macro has
--     no cast event.
[2500] = "Pour les types d'action automatiques, choisissez quel événement de lancer observé déclenche cette entrée. Un début, un arrêt, une interruption, un échec ou un retard diffère d'un lancer réussi. Le client détermine quels événements et observations sont disponibles. Via script/macro n'a pas d'événement de lancer.",
-- d9dcc847 English: The cast or channel started. This event does not mean it will finish
--     successfully.
[2501] = "L'incantation ou la canalisation a commencé. Cet événement ne signifie pas qu'elle se terminera avec succès.",
-- 2e1b963f English: The cast or channel stopped. A stop alone does not establish whether it
--     succeeded.
[2502] = "L'incantation ou la canalisation s'est arrêtée. Un arrêt seul n'établit pas si elle a réussi.",
-- 37c82b71 English: The client reported a successful spell cast or item-use spell. For a channel,
--     this can occur as channeling begins rather than after its final tick.
[2503] = "Le client a signalé un lancer de sort ou un sort d'utilisation d'objet réussi. Pour une canalisation, cela peut se produire au début de la canalisation plutôt qu'après son dernier tick.",
-- 94a29d0b English: The client reported that the cast was interrupted. This can include canceling a
--     cast yourself.
[2504] = "Le client a signalé que l'incantation a été interrompue. Cela peut inclure l'annulation d'une incantation par vous-même.",
-- 7c5f19c7 English: The client reported that the cast failed. This is separate from the
--     successful-cast event.
[2505] = "Le client a signalé que l'incantation a échoué. Cet événement est distinct de l'événement de lancer réussi.",
-- 9ae70605 English: The client reported a delay to the cast. This event is not a completion or
--     success notification.
[2506] = "Le client a signalé un retard de l'incantation. Cet événement n'est pas une notification d'achèvement ni de réussite.",
-- 326e2b60 English: Choose a chat destination, local output, a named Emote or Audible. Emote
--     replaces Text with an emote selector and optional recipient. Audible replaces Text with
--     Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels
--     are offered only for Via Script/Macro and remain subject to native restrictions.
[2507] = "Choisissez une destination de discussion, une sortie locale, une Emote nommée ou Sonore. Emote remplace Texte par un sélecteur d'emote et un destinataire facultatif. Sonore remplace Texte par Son. Le texte est conservé lors du changement de mode. Dire, Crier, Chuchoter et les canaux nommés rejoints ne sont proposés que pour Via script/macro et restent soumis aux restrictions natives.",
-- 8352df04 English: Play the selected sound locally on the Master audio channel; no chat message is
--     sent. Choose an available sound before applying the announcement.
[2508] = "Joue le son sélectionné localement sur le canal audio principal ; aucun message de discussion n'est envoyé. Choisissez un son disponible avant d'appliquer l'annonce.",
-- b952981f English: Use raid chat while in a raid, party chat while in a party, or your local chat
--     frame while solo.
[2509] = "Utilise la discussion de raid en raid, la discussion de groupe en groupe, ou votre fenêtre de discussion locale en solo.",
-- 0048ad2e English: Use party chat when grouped, including your party within a raid. This
--     destination produces no solo chat message.
[2510] = "Utilise la discussion de groupe lorsque vous êtes groupé, y compris votre groupe au sein d'un raid. Cette destination ne produit aucun message en solo.",
-- 4dd62130 English: Request group warning output. Depending on group membership and permissions, RM
--     may use raid chat, party chat, or local output instead.
[2511] = "Demande une sortie en avertissement de groupe. Selon l'appartenance au groupe et les permissions, RM peut utiliser à la place la discussion de raid, la discussion de groupe ou la sortie locale.",
-- 5a88e05c English: A saved free-text emote keeps its original message. Select Emote to use a named
--     client emote instead.
[2512] = "Une emote en texte libre enregistrée conserve son message d'origine. Sélectionnez Emote pour utiliser à la place une emote nommée du client.",
-- 0bab8021 English: Choose a named emote from this client's slash commands, such as /cheer. This
--     does not send the Text field as a custom emote.
[2513] = "Choisissez une emote nommée parmi les commandes slash de ce client, comme /cheer. Cela n'envoie pas le champ Texte comme emote personnalisée.",
-- a7a449d8 English: Choose the emote to perform when the configured cast event is observed. The
--     client may restrict an emote or require a hardware action; RM does not retry through another
--     output path.
[2514] = "Choisissez l'emote à effectuer lorsque l'événement de lancer configuré est observé. Le client peut restreindre une emote ou exiger une action matérielle ; RM ne réessaie pas par une autre voie de sortie.",
-- 7c9bf8c3 English: For cast entries, checked directs the emote to the recipient recorded for this
--     exact cast, including click casting. It does not use your current target or a previous cast's
--     recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient
--     skips targeted output. Unchecked performs the emote without a target.
[2515] = "Pour les entrées de lancer, coché dirige l'emote vers le destinataire enregistré pour ce lancer précis, y compris le lancer au clic. Elle n'utilise ni votre cible actuelle ni le destinataire d'un lancer précédent. Pour Via script/macro, coché utilise l'unité de macro fournie. Un destinataire manquant ignore la sortie ciblée. Décoché, l'emote est effectuée sans cible.",
-- 24d388c2 English: Write to your own chat frame. Other players do not receive this message.
[2516] = "Écrire dans votre propre fenêtre de discussion. Les autres joueurs ne reçoivent pas ce message.",
-- 2224d247 English: Enter the message for a chat destination. The substitutions below insert action
--     and cast information when it is available. This text is not used for Audible or named Emote
--     output.
[2517] = "Saisissez le message pour une destination de discussion. Les substitutions ci-dessous insèrent les informations d'action et de lancer lorsqu'elles sont disponibles. Ce texte n'est pas utilisé pour les sorties Sonore ou Emote nommée.",
-- 5625f190 English: For cast entries, {{spell}} is a spell link, {{item}} an item link and
--     {{event}} the localized event name. {{target}} uses the recorded cast target, with the last
--     recorded target for that spell as a fallback; it does not automatically use your selected
--     target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro
--     instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required
--     missing inputs skip output; this API supplies no {{item}}.
[2518] = "Pour les entrées de lancer, {{spell}} est un lien de sort, {{item}} un lien d'objet et {{event}} le nom localisé de l'événement. {{target}} utilise la cible de lancer enregistrée, avec en repli la dernière cible enregistrée pour ce sort ; il n'utilise pas automatiquement votre cible sélectionnée ni votre nom. Les substitutions de lancer indisponibles peuvent rester inchangées. Via script/macro utilise plutôt la cible et le sort fournis, {{event}} devient Via script/macro, et l'absence d'entrées requises annule la sortie ; cette API ne fournit pas de {{item}}.",
-- a7af0c5c English: Choose a sound supplied by the shared-media catalog, then click Play to preview
--     it. Preview is local and does not save the draft. An unavailable sound cannot be previewed;
--     Audible announcements require a nonempty sound selection.
[2519] = "Choisissez un son fourni par le catalogue de médias partagés, puis cliquez sur Lire pour l'écouter. L'écoute est locale et n'enregistre pas le brouillon. Un son indisponible ne peut pas être écouté ; les annonces Sonores exigent un son sélectionné.",
-- 58fc69dd English: The pill turns this entry on or off while keeping its fields. Disabled entries
--     do not announce matching casts or macro invocations. Apply saves the changed state.
[2520] = "La pastille active ou désactive cette entrée tout en conservant ses champs. Les entrées désactivées n'annoncent pas les lancers ou invocations de macro correspondants. Appliquer enregistre le changement d'état.",
-- 2ca49225 English: Edits stay in a draft until Apply. Complete the action or Via Script/Macro
--     identifier and other required fields before saving. Discard abandons changes to saved
--     announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply,
--     Discard or Cancel navigation.
[2521] = "Les modifications restent dans un brouillon jusqu'à Appliquer. Complétez l'action ou l'identifiant Via script/macro et les autres champs requis avant d'enregistrer. Abandonner renonce aux modifications des annonces enregistrées ; Annuler ferme un brouillon de création. Quitter avec des modifications en attente propose Appliquer, Abandonner ou Annuler la navigation.",
-- af92b7de English: Use the sidebar buttons to create, duplicate, transfer or compare
--     announcements. Apply saves the imported draft; Compare does not merge entries. Via
--     Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh
--     identity. Series exports use version 2; version 1 remains available for legacy single-output
--     entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes
--     the selected saved entry after confirmation. Resolve pending edits first; deletion does not
--     carry into the next selected draft.
[2522] = "Utilisez les boutons de la barre latérale pour créer, dupliquer, transférer ou comparer des annonces. Appliquer enregistre le brouillon importé ; Comparer ne fusionne pas les entrées. Dupliquer une entrée Via script/macro attribue un identifiant distinct, et chaque sortie copiée reçoit une nouvelle identité. Les exportations de séries utilisent la version 2 ; la version 1 reste disponible pour les anciennes entrées à sortie unique. Les importations et Appliquer rejettent les identifiants ambigus. La corbeille rouge supprime définitivement l'entrée enregistrée sélectionnée après confirmation. Résolvez d'abord les modifications en attente ; la suppression ne se reporte pas sur le brouillon sélectionné ensuite.",
-- 2aefc10f English: An item set is an ordered list of alternatives, such as different mana potions.
--     Runtime selection checks the list from the top for a carried or, where requested, equipped
--     item. Priority comes from the order you choose, not the item level. Selecting an item does
--     not by itself prove that it is usable, off cooldown, or in range; action readiness is checked
--     separately.
[2523] = "Un ensemble d'objets est une liste ordonnée d'alternatives, comme différentes potions de mana. La sélection en jeu parcourt la liste depuis le haut à la recherche d'un objet porté ou, si demandé, équipé. La priorité vient de l'ordre que vous choisissez, pas du niveau d'objet. Sélectionner un objet ne prouve pas à lui seul qu'il est utilisable, hors temps de recharge ou à portée ; la disponibilité de l'action est vérifiée séparément.",
-- f684e8a2 English: Name the selected set so it can be found in the sidebar and referenced by
--     rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add
--     items afterward and Apply again to save them. Discarding later item edits keeps that already
--     saved set. Renaming a set does not change its identity in saved references.
[2524] = "Nommez l'ensemble sélectionné pour le retrouver dans la barre latérale et le référencer dans des rotations ou des conditions. Nouveau ouvre un formulaire de nom ; son premier Appliquer enregistre un ensemble nommé vide. Ajoutez ensuite des objets et appliquez de nouveau pour les enregistrer. Abandonner des modifications d'objets ultérieures conserve l'ensemble déjà enregistré. Renommer un ensemble ne change pas son identité dans les références enregistrées.",
-- 21312192 English: Checked stores this set in the shared global collection, available to other
--     profiles and characters using this addon database. Unchecked stores it in the current
--     profile, which can itself be shared by characters. This is a staged move; Apply saves it. A
--     profile set takes precedence if a global set has the same saved identity.
[2525] = "Coché, cet ensemble est stocké dans la collection globale partagée, disponible pour les autres profils et personnages utilisant cette base de données de l'addon. Décoché, il est stocké dans le profil actuel, qui peut lui-même être partagé entre personnages. Ce déplacement est préparé ; Appliquer l'enregistre. Un ensemble de profil a la préséance si un ensemble global a la même identité enregistrée.",
-- 0ba4e811 English: The list of item cards is the priority order. Put preferred items first. RM can
--     leave a selection unavailable when required inventory or identity observations are missing;
--     it does not treat unknown data as proof that a lower-priority item should be used. The
--     sidebar icon represents the first defined item and need not be the currently carried or
--     highlighted one.
[2526] = "La liste des cartes d'objets constitue l'ordre de priorité. Placez les objets préférés en premier. RM peut laisser une sélection indisponible lorsque des observations requises d'inventaire ou d'identité manquent ; il ne considère pas des données inconnues comme la preuve qu'un objet de moindre priorité doit être utilisé. L'icône de la barre latérale représente le premier objet défini et n'est pas forcément celui qui est actuellement porté ou en surbrillance.",
-- a5bf7ef1 English: Search by item name and choose a result, or drag an item from your bags or
--     action bar into its field. The icon identifies the item; metadata can take time to load. Edit
--     a row to replace that entry. Use its red trash can to remove it rather than clearing a
--     required item field.
[2527] = "Recherchez par nom d'objet et choisissez un résultat, ou faites glisser un objet depuis vos sacs ou votre barre d'action dans son champ. L'icône identifie l'objet ; le chargement des métadonnées peut prendre du temps. Modifiez une ligne pour remplacer cette entrée. Utilisez sa corbeille rouge pour la retirer plutôt que de vider un champ d'objet obligatoire.",
-- 67b1eae9 English: Choose or drag an item into the empty item field above the list, then click Add
--     item to append it to the priority list, or drag Add item into a gap between cards to insert
--     it there. Entering an item in this field alone does not add a row.
[2528] = "Choisissez ou faites glisser un objet dans le champ d'objet vide au-dessus de la liste, puis cliquez sur Ajouter un objet pour l'ajouter à la fin de la liste de priorités, ou faites glisser Ajouter un objet dans un espace entre les cartes pour l'y insérer. Saisir un objet dans ce champ n'ajoute pas de ligne à lui seul.",
-- 50b0f89c English: Move Up / Move Down
[2529] = "Monter / Descendre",
-- 69b751c9 English: Use the arrows on the left, or drag an item row into a highlighted insertion
--     gap. Ctrl-drag moves that row and all following entries together. The floating preview
--     identifies what you are moving. Moves past the beginning or end are unavailable. Reordering
--     changes priority and stays in the draft until Apply.
[2530] = "Utilisez les flèches à gauche, ou faites glisser une ligne d'objet dans un espace d'insertion en surbrillance. Ctrl-glisser déplace cette ligne avec toutes les entrées suivantes. L'aperçu flottant indique ce que vous déplacez. Les déplacements au-delà du début ou de la fin sont indisponibles. Réordonner change la priorité et reste dans le brouillon jusqu'à Appliquer.",
-- 2b906316 English: Bind / Unbind
-- Context: Help topic title in the item set help for the buttons that connect an item set to a
--     macro/action button or remove the link.
[2531] = "Lier / Délier",
-- 81abb5f4 English: Outside combat, apply pending item-set edits before binding. Drag the set (its
--     row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving
--     its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up
--     the first available item of the set. RM records the slot and updates it as item availability
--     changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar
--     items. Replaced bar actions are preserved. Binding changes are immediate action-bar
--     operations, independent of the draft and its history.
[2532] = "Hors combat, appliquez les modifications en attente de l'ensemble d'objets avant de le lier. Faites glisser l'ensemble (sa ligne dans la liste, ou la pastille Lier) sur n'importe quel emplacement de barre d'action ; un emplacement occupé est échangé, et son action précédente reste sur le curseur. Ou cliquez sur Lier puis sur un emplacement vide. Les deux méthodes prennent le premier objet disponible de l'ensemble. RM enregistre l'emplacement et le met à jour à mesure que la disponibilité des objets change. La pastille affiche les numéros des emplacements liés ; cliquez dessus pour délier et retirer les objets de barre encore correspondants. Les actions de barre remplacées sont conservées. Les changements de liaison sont des opérations immédiates sur les barres d'action, indépendantes du brouillon et de son historique.",
-- 7c8417f1 English: Restore the packaged item list for this set. Reset is available only for a set
--     with a packaged default. The restored list is staged until Apply; the name is kept.
[2533] = "Restaurer la liste d'objets fournie avec l'addon pour cet ensemble. Réinitialiser n'est disponible que pour un ensemble ayant une valeur par défaut fournie. La liste restaurée est préparée jusqu'à Appliquer ; le nom est conservé.",
-- 70b9c94e English: The red trash can at the top right permanently removes the selected saved set
--     after confirmation. Resolve pending edits before the final warning. References in rotations
--     or conditions then need another set. Deletion reconciles still-matching bound bar actions and
--     keeps the set if unbinding fails; the next selection opens without an unsaved deletion
--     marker.
[2534] = "La corbeille rouge en haut à droite supprime définitivement l'ensemble enregistré sélectionné après confirmation. Résolvez les modifications en attente avant l'avertissement final. Les références dans les rotations ou les conditions auront alors besoin d'un autre ensemble. La suppression réconcilie les actions de barre liées encore correspondantes et conserve l'ensemble si la déliaison échoue ; la sélection suivante s'ouvre sans marqueur de suppression non enregistrée.",
-- 49c1588e English: Undo / Redo
-- Context: Help topic title in the item set help for the undo and redo buttons.
[2535] = "Défaire / Refaire",
-- cd68dbfd English: Undo and Redo travel through recent item-set draft edits, including
--     replacements, additions, ordering and row removals. They are unavailable when that direction
--     has no history. Apply, Discard or leaving the page clears this bounded history. They do not
--     reverse confirmed entity deletion or explicit action-bar binding operations.
[2536] = "Défaire et Refaire parcourent les modifications récentes du brouillon de l'ensemble d'objets, y compris les remplacements, ajouts, réordonnancements et retraits de lignes. Ils sont indisponibles lorsque cette direction n'a pas d'historique. Appliquer, Abandonner ou quitter la page efface cet historique limité. Ils n'annulent ni une suppression d'entité confirmée ni les opérations explicites de liaison aux barres d'action.",
-- 68ab50bb English: Ordinary item-set edits stay in a draft until Apply. Discard restores the saved
--     item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply,
--     Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can
--     abandon them.
[2537] = "Les modifications ordinaires d'un ensemble d'objets restent dans un brouillon jusqu'à Appliquer. Abandonner rétablit les ensembles d'objets enregistrés. Annuler ferme un brouillon de création. Quitter avec des modifications en attente propose Appliquer, Abandonner ou Annuler la navigation. Les champs invalides doivent être corrigés avant Appliquer ; Abandonner permet d'y renoncer.",
-- b81b94df English: Use the buttons below the sidebar to create, duplicate, transfer, or compare
--     sets. Duplicate makes an independent profile copy. Import shows the source name and can
--     create a renamed copy or replace the selected list; Apply saves the staged result. Compare
--     inspects differences without merging or modifying either set.
[2538] = "Utilisez les boutons sous la barre latérale pour créer, dupliquer, transférer ou comparer des ensembles. Dupliquer crée une copie de profil indépendante. Importer affiche le nom de la source et peut créer une copie renommée ou remplacer la liste sélectionnée ; Appliquer enregistre le résultat préparé. Comparer examine les différences sans fusionner ni modifier aucun des deux ensembles.",
-- 147db4bf English: Legacy macro buttons
-- Context: Help topic title in the item set help: older macro buttons made before the current
--     system.
[2539] = "Anciens boutons de macro",
-- 77908784 English: Legacy clients may allow /click to invoke an RM item-set button separately from
--     action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters
--     removed, then an underscore and unit token. For a set named Bandages, an example is /click
--     [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet,
--     target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons
--     contain item-use macro lines and do not provide the same readiness or first-item guarantee as
--     the recommendation engine. Availability is subject to the client's secure-button and macro
--     restrictions; reference-only support does not promise executable macro buttons.
[2540] = "Les anciens clients peuvent permettre à /click d'invoquer un bouton d'ensemble d'objets de RM indépendamment de la liaison aux barres d'action. Le nom est RM_ suivi du nom de l'ensemble sans ses caractères non alphanumériques, puis d'un tiret bas et d'un identifiant d'unité. Pour un ensemble nommé Bandages, un exemple est /click [@mouseover,nodead,help] RM_Bandages_mouseover. Les autres suffixes d'unité incluent player, pet, target, focus, pettarget, targettarget, focustarget et mouseovertarget. Ces boutons contiennent des lignes de macro d'utilisation d'objet et n'offrent pas les mêmes garanties de disponibilité ou de premier objet que le moteur de recommandation. Leur disponibilité dépend des restrictions du client sur les boutons sécurisés et les macros ; la prise en charge en mode référence uniquement ne garantit pas de boutons de macro exécutables.",
-- 0378c27f English: Search for an item or drag it into the item field or icon. Choose the result to
--     retain its exact item identity. The icon and name may be unavailable until metadata loads.
--     Field clearing and save behavior belong to the editor that contains this list; use Delete
--     when you intend to remove an entry.
[2541] = "Recherchez un objet ou faites-le glisser dans le champ d'objet ou sur l'icône. Choisissez le résultat pour conserver l'identité exacte de l'objet. L'icône et le nom peuvent être indisponibles jusqu'au chargement des métadonnées. L'effacement des champs et l'enregistrement relèvent de l'éditeur qui contient cette liste ; utilisez Supprimer lorsque vous voulez retirer une entrée.",
-- 6a348c09 English: Move this entry to the first position in the item priority list, when that
--     control is offered.
[2542] = "Placer cette entrée en première position de la liste de priorités des objets, lorsque ce contrôle est proposé.",
-- 3b1a1705 English: Move this entry one position earlier. A move before the first entry is
--     unavailable.
[2543] = "Avancer cette entrée d'une position. Un déplacement avant la première entrée est indisponible.",
-- a147318d English: Move this entry one position later. A move past the final entry is unavailable.
[2544] = "Reculer cette entrée d'une position. Un déplacement après la dernière entrée est indisponible.",
-- 4b77e29f English: Move this entry to the final position in the item priority list, when that
--     control is offered.
[2545] = "Placer cette entrée en dernière position de la liste de priorités des objets, lorsque ce contrôle est proposé.",
-- 0c112c0c English: Remove this entry from the list. In a draft editor this remains pending until
--     Apply, and Discard abandons the row edit. Undo is available where the containing editor
--     provides draft history. This differs from permanently deleting the entire set after
--     confirmation.
[2546] = "Retirer cette entrée de la liste. Dans un éditeur à brouillon, ce retrait reste en attente jusqu'à Appliquer, et Abandonner annule la modification de la ligne. Défaire est disponible lorsque l'éditeur conteneur fournit un historique de brouillon. Cela diffère de la suppression définitive de l'ensemble entier après confirmation.",
-- df1955d5 English: Use All, Built In or Custom to choose the condition source, then filter by
--     Switch, Other or a named category. Search above these controls narrows the visible list
--     without changing assignments.
[2547] = "Utilisez Toutes, Intégrées ou Personnalisées pour choisir la source des conditions, puis filtrez par Bascule, Autre ou une catégorie nommée. La recherche au-dessus de ces contrôles restreint la liste visible sans modifier les attributions.",
-- 190e427d English: Open Manage categories below the list for category maintenance. Manage
--     conditions returns to individual condition settings.
[2548] = "Ouvrez Gérer les catégories sous la liste pour l'entretien des catégories. Gérer les conditions revient aux paramètres de chaque condition.",
-- a9dcdfe2 English: Below the condition list, Import/Export opens the selected custom definition
--     for transfer and code review; it is disabled for built-in conditions. In Manage categories,
--     transfer a category’s ordered condition identifiers. Named categories and Other are exclusive
--     destinations. Switch membership is independent.
[2549] = "Sous la liste des conditions, Importer/Exporter ouvre la définition personnalisée sélectionnée pour le transfert et la vérification du code ; ce bouton est désactivé pour les conditions intégrées. Dans Gérer les catégories, transférez les identifiants ordonnés des conditions d'une catégorie. Les catégories nommées et Autre sont des destinations exclusives. L'appartenance à Bascule est indépendante.",
-- 936a161c English: Editor
-- Context: Help topic title in Integrations settings help for the Lua editor options.
[2550] = "Éditeur",
-- 0c601351 English: Optional addons
-- Context: Help topic title in Integrations help: the list of other addons Rotation Master can work
--     with.
[2551] = "Addons facultatifs",
-- 0413ac9a English: Undo and Redo edit the Lua body. Reset restores the saved body or new-function
--     template and can be undone. Check syntax executes no custom Lua. Apply saves the body and
--     metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or
--     Cancel.
[2552] = "Défaire et Refaire modifient le corps du code Lua. Réinitialiser rétablit le corps enregistré ou le modèle de nouvelle fonction, et peut être défait. Vérifier la syntaxe n'exécute aucun code Lua personnalisé. Appliquer enregistre ensemble le corps et les métadonnées ; Abandonner renonce au brouillon. Quitter avec des modifications propose Appliquer, Abandonner ou Annuler.",
-- 5e86a29a English: Include custom function dependencies exports their source with the selected
--     definition. Without it, the bundle records required helper identities and versions. Review
--     source shows every imported Lua body. Resolve each original name and destination with Reuse,
--     Replace or a new identifier. Apply import saves the complete reviewed bundle and can register
--     imported Lua. Only apply code you trust.
[2553] = "Inclure les dépendances de fonctions personnalisées exporte leur source avec la définition sélectionnée. Sans cette option, le lot enregistre les identités et versions des fonctions utilitaires requises. Vérifier la source affiche chaque corps de code Lua importé. Résolvez chaque nom d'origine et destination avec Réutiliser, Remplacer ou un nouvel identifiant. Appliquer l'importation enregistre le lot complet vérifié et peut inscrire le code Lua importé. N'appliquez que du code de confiance.",
-- b696d1d1 English: Arguments and returns
-- Context: Section title in the Functions help: how the Arguments and Returns lists work.
[2554] = "Arguments et retours",
-- 2be54423 English: Choose an existing namespace from the suggestions or type a new dotted
--     namespace. Built In namespaces follow source files; custom namespaces are implied by saved
--     functions and need no separate maintenance.
[2555] = "Choisissez un espace de noms existant parmi les suggestions ou saisissez un nouvel espace de noms pointé. Les espaces de noms Intégrés suivent les fichiers sources ; les espaces de noms personnalisés découlent des fonctions enregistrées et ne nécessitent aucun entretien séparé.",
-- f6a949d3 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. The code signature shows the qualified namespace.name used by callers.
[2556] = "Les noms de fonction utilisent des lettres, des chiffres et des tirets bas, et commencent par une lettre ou un tiret bas. La signature du code montre le nom qualifié namespace.name utilisé par les appelants.",
-- 330af7d6 English: Search helpers by name or description, then filter Built In / Custom and
--     namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom
--     copy.
[2557] = "Recherchez des fonctions utilitaires par nom ou description, puis filtrez par Intégrées / Personnalisées et par espace de noms. Les fonctions utilitaires fournies utilisent le même panneau en lecture seule. Dupliquer crée une copie personnalisée modifiable.",
-- e67ec7ba English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Return rows describe those results; moving them does not rewrite
--     return statements. Reordering a saved function warns because positional callers may need
--     changes; RM does not rewrite call sites.
[2558] = "Cliquez sur un titre Arguments ou Retours pour le replier ou le développer. + Argument et + Retour ajoutent à la fin au clic, ou insèrent dans un espace en surbrillance par glisser-déposer. Faites glisser une ligne ou utilisez Haut / Bas pour réordonner ; Ctrl-glisser emporte les lignes suivantes. La corbeille retire une ligne. Type et Nil autorisé documentent les valeurs acceptées ; Description explique chaque entrée ou résultat. Lua peut renvoyer plusieurs résultats ordonnés. Les lignes de retour décrivent ces résultats ; les déplacer ne réécrit pas les instructions return. Réordonner une fonction enregistrée affiche un avertissement, car les appelants positionnels peuvent nécessiter des modifications ; RM ne réécrit pas les sites d'appel.",
-- 183f4958 English: Enable Rotation Master recommendations, automatic rotation switching and bound
--     item-set updates. Disabling clears active advice and highlights and hides the preview. Apply
--     saves the change.
[2559] = "Activez les recommandations de Rotation Master, la bascule automatique de rotation et la mise à jour des ensembles d'objets liés. La désactivation efface les conseils et surbrillances actifs et masque l'aperçu. Appliquer enregistre la modification.",
-- c25b80af English: Set how often Rotation Master reevaluates the active rotation and independent
--     cooldowns, in seconds. A shorter interval updates advice more often and uses more processing
--     time. It does not cast spells, queue actions, or predict future combat.
[2560] = "Définissez la fréquence, en secondes, à laquelle Rotation Master réévalue la rotation active et les temps de recharge indépendants. Un intervalle plus court met à jour les conseils plus souvent et consomme plus de temps de traitement. Il ne lance pas de sorts, ne met pas d'actions en file d'attente et ne prédit pas le combat à venir.",
-- 693c25ac English: Out of combat with no target and no focus, Rotation Master skips a polling tick
--     unless something it watches has changed: auras, cooldowns, health or power of you, your pet
--     or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at
--     least this often, for time-based conditions (aura or cooldown remaining), distance, and
--     custom code. In combat, with any target or focus, or while configuration is open, every
--     polling tick is evaluated. Zero evaluates every polling tick.
[2561] = "Hors combat, sans cible ni focalisation, Rotation Master saute un cycle d'interrogation sauf si un élément qu'il surveille a changé : auras, temps de recharge, points de vie ou ressource de vous-même, de votre familier ou de votre groupe, déplacement, incantation, équipement, sacs, forme, familiers ou groupe. Il revérifie tout de même au moins à cette fréquence, pour les conditions temporelles (temps restant d'une aura ou d'un temps de recharge), la distance et le code personnalisé. En combat, avec une cible ou une focalisation, ou lorsque la configuration est ouverte, chaque cycle d'interrogation est évalué. Zéro évalue chaque cycle d'interrogation.",
-- 658535de English: With automatic switching, Rotation Master checks this often, in and out of
--     combat, whether a different rotation's switch conditions now match, so conditions that change
--     on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and
--     pet changes are checked straight away. Zero turns automatic switching off. Choosing a
--     rotation manually still overrides automatic switching until you choose Auto again.
[2562] = "Avec la bascule automatique, Rotation Master vérifie à cette fréquence, en combat comme hors combat, si les conditions de bascule d'une autre rotation correspondent désormais, afin que les conditions qui changent d'elles-mêmes (nombre d'ennemis proches, menace, déplacement, points de vie) prennent effet. Les changements de cible, de focalisation et de familier sont vérifiés immédiatement. Zéro désactive la bascule automatique. Choisir manuellement une rotation reste prioritaire sur la bascule automatique jusqu'à ce que vous choisissiez de nouveau Auto.",
-- 93a9cab7 English: Hide the main rotation recommendation on action bars. Independent cooldown
--     highlights remain available. Enable Preview Spells if you want to see the main advice in a
--     separate window; with both displays off, the main recommendation has no visible icon.
[2563] = "Masquez la recommandation principale sur les barres d'action. Les surbrillances des temps de recharge indépendants restent disponibles. Activez Aperçu des sorts si vous voulez voir le conseil principal dans une fenêtre séparée ; si les deux affichages sont désactivés, la recommandation principale n'a aucune icône visible.",
-- 186fa30f English: How often, in seconds, the rotation editor checks each card's condition for the
--     colored bar on the left of its condition field: green when it currently matches for you, red
--     when it does not, gray when it cannot be read at the moment (hover the condition for why and
--     when it was checked). Conditions are checked only while the editor is open; zero turns the
--     bars off. This is separate from the recommendation polling interval.
[2564] = "Fréquence, en secondes, à laquelle l'éditeur de rotations vérifie la condition de chaque carte pour la barre colorée à gauche de son champ de condition : verte quand elle est remplie pour vous, rouge quand elle ne l'est pas, grise quand elle ne peut pas être lue pour le moment (survolez la condition pour savoir pourquoi et quand elle a été vérifiée). Les conditions ne sont vérifiées que lorsque l'éditeur est ouvert ; zéro désactive les barres. Ce réglage est distinct de l'intervalle d'interrogation des recommandations.",
-- 8fc06fca English: Show the Rotation Master minimap icon. Left-click toggles the configuration
--     window. Right-click opens the quick menu for enabling recommendations and choosing a rotation
--     or automatic switching.
[2565] = "Affichez l'icône de minicarte de Rotation Master. Un clic gauche ouvre ou ferme la fenêtre de configuration. Un clic droit ouvre le menu rapide pour activer les recommandations et choisir une rotation ou la bascule automatique.",
-- a64c178e English: Choose how many seconds of previous spell casts to retain for history-based
--     conditions. Older casts are removed as recommendations update. A longer history retains more
--     records.
[2566] = "Choisissez combien de secondes de lancers de sorts précédents conserver pour les conditions basées sur l'historique. Les lancers plus anciens sont supprimés à mesure que les recommandations se mettent à jour. Un historique plus long conserve davantage d'enregistrements.",
-- 6572d0ab English: Choose how many seconds of combat events to retain for conditions such as
--     recent hits, parries and blocks. Older events are removed as recommendations update.
--     Availability depends on the client combat-data policy.
[2567] = "Choisissez combien de secondes d'événements de combat conserver pour des conditions telles que les coups, parades et blocages récents. Les événements plus anciens sont supprimés à mesure que les recommandations se mettent à jour. La disponibilité dépend de la politique du client concernant les données de combat.",
-- 6c970b96 English: Choose how many seconds of observed damage and healing to retain for burn-rate
--     and time-to-die estimates. Recent observations receive more weight. A longer window uses more
--     records and smooths short changes; it cannot supply events the client does not expose.
[2568] = "Choisissez combien de secondes de dégâts et de soins observés conserver pour les estimations de vitesse d'épuisement et de temps restant avant la mort. Les observations récentes pèsent davantage. Une fenêtre plus longue utilise plus d'enregistrements et lisse les variations brèves ; elle ne peut pas fournir des événements que le client n'expose pas.",
-- 1826b95e English: Choose a whole number of upcoming recommendations, from zero (hidden) to five.
--     This is the only switch for the preview window: it is shown whenever this is above zero and
--     hidden at zero, and the window has no close button. The preview shows current priority
--     results, not a simulation of future cooldowns or combat. Icons start at 64 pixels; resizing
--     scales all icons while preserving their square shape and the window ratio.
[2569] = "Choisissez un nombre entier de recommandations à venir, de zéro (masqué) à cinq. C'est le seul interrupteur de la fenêtre d'aperçu : elle est affichée tant que cette valeur est supérieure à zéro et masquée à zéro, et la fenêtre n'a pas de bouton de fermeture. L'aperçu affiche les résultats de priorité actuels, pas une simulation des temps de recharge ou du combat à venir. Les icônes mesurent initialement 64 pixels ; le redimensionnement met toutes les icônes à l'échelle en conservant leur forme carrée et les proportions de la fenêtre.",
-- 9a03212a English: Adjust the preview background opacity without fading its icons. At zero only
--     the icons remain, the hidden background does not intercept blank-space clicks and the resize
--     grip is unavailable; an unlocked preview can still be dragged by its icons. Restore opacity
--     in General to resize it.
[2570] = "Réglez l'opacité du fond de l'aperçu sans estomper ses icônes. À zéro, seules les icônes restent : le fond masqué n'intercepte pas les clics dans les zones vides et la poignée de redimensionnement n'est pas disponible ; un aperçu déverrouillé peut toujours être déplacé par ses icônes. Rétablissez l'opacité dans Général pour le redimensionner.",
-- 7884cae2 English: Unlocked, drag the preview by any icon or its background to move it, and resize
--     it from the grip that appears at its lower-right corner on hover. Locked, it cannot be moved
--     or resized and its background lets clicks through. Right-click an icon (or the background
--     while unlocked) for a menu to lock, unlock or open these settings. Locking and unlocking take
--     effect immediately and are saved without Apply. Other pending General edits remain unchanged.
[2571] = "Déverrouillé, faites glisser l'aperçu par n'importe quelle icône ou par son fond pour le déplacer, et redimensionnez-le avec la poignée qui apparaît dans son coin inférieur droit au survol. Verrouillé, il ne peut être ni déplacé ni redimensionné et son fond laisse passer les clics. Faites un clic droit sur une icône (ou sur le fond s'il est déverrouillé) pour ouvrir un menu permettant de verrouiller, déverrouiller ou ouvrir ces paramètres. Le verrouillage et le déverrouillage prennent effet immédiatement et sont enregistrés sans Appliquer. Les autres modifications en attente de Général restent inchangées.",
-- 110dd6c2 English: Arrange preview icons horizontally (default) or vertically. Lock, Direction and
--     Reset share one row below the opacity slider. Changing direction keeps icons square and
--     adjusts the window ratio.
[2572] = "Disposez les icônes de l'aperçu horizontalement (par défaut) ou verticalement. Verrouiller, Direction et Réinitialiser partagent une ligne sous le curseur d'opacité. Changer de direction conserve des icônes carrées et ajuste les proportions de la fenêtre.",
-- 46417b1b English: This icon previews the selected profile effect, color, size, anchor and
--     offsets. Previewing an effect does not save the draft or change the spell being recommended.
[2573] = "Cette icône donne un aperçu de l'effet, de la couleur, de la taille, de l'ancre et des décalages sélectionnés dans le profil. L'aperçu d'un effet n'enregistre pas le brouillon et ne change pas le sort recommandé.",
-- 0e030acc English: Choose the highlight used for the main recommendation and as the default for
--     independent cooldowns. Manage available effects on the Effects page. A cooldown can override
--     these profile settings in its action details.
[2574] = "Choisissez la surbrillance utilisée pour la recommandation principale et, par défaut, pour les temps de recharge indépendants. Gérez les effets disponibles sur la page Effets. Un temps de recharge peut remplacer ces réglages du profil dans les détails de son action.",
-- cf6729fa English: Scale the highlight relative to its action icon. A value of 1 uses the icon
--     size. Drag the slider or type its numeric value; the preview updates as you edit.
[2575] = "Mettez la surbrillance à l'échelle par rapport à l'icône de son action. Une valeur de 1 utilise la taille de l'icône. Faites glisser le curseur ou saisissez sa valeur numérique ; l'aperçu se met à jour pendant l'édition.",
-- 15842be8 English: Choose the highlight color and opacity. Click the color swatch to open the
--     picker, or enter R, G, B and A values between 0 and 1. Alpha controls opacity; individual
--     cooldowns may override this profile color.
[2576] = "Choisissez la couleur et l'opacité de la surbrillance. Cliquez sur l'échantillon de couleur pour ouvrir le sélecteur, ou saisissez des valeurs R, G, B et A entre 0 et 1. Alpha contrôle l'opacité ; chaque temps de recharge peut remplacer cette couleur du profil.",
-- 27eafca9 English: Choose the point on the action icon where a texture highlight is anchored by
--     its center. Changing Anchor resets the offsets. The preview shows the resulting placement;
--     non-texture glows may use offsets without a texture anchor.
[2577] = "Choisissez le point de l'icône d'action où une surbrillance de type texture est ancrée par son centre. Changer l'ancre réinitialise les décalages. L'aperçu montre le placement obtenu ; les lueurs sans texture peuvent utiliser des décalages sans ancre de texture.",
-- 24139be0 English: Vertical offset in pixels. Use Up or Down on the position control, or edit V
--     directly. Hold Shift while using an arrow for ten pixels. Center resets both offsets and the
--     anchor to Center.
[2578] = "Décalage vertical en pixels. Utilisez Haut ou Bas sur la commande de position, ou modifiez V directement. Maintenez Maj enfoncée en utilisant une flèche pour avancer de dix pixels. Centre réinitialise les deux décalages et place l'ancre sur Centre.",
-- 64fcca62 English: Horizontal offset in pixels. Use Left or Right on the position control, or edit
--     H directly. Hold Shift while using an arrow for ten pixels. Non-texture glows interpret
--     offsets according to their effect shape.
[2579] = "Décalage horizontal en pixels. Utilisez Gauche ou Droite sur la commande de position, ou modifiez H directement. Maintenez Maj enfoncée en utilisant une flèche pour avancer de dix pixels. Les lueurs sans texture interprètent les décalages selon la forme de leur effet.",
-- 199fbfc5 English: Choose the display name for your primary specialization. This changes its label
--     in Rotation Master, not your character talents or specialization.
[2580] = "Choisissez le nom affiché pour votre spécialisation principale. Cela change son libellé dans Rotation Master, pas les talents ni la spécialisation de votre personnage.",
-- 1647f2ad English: Choose the display name for your secondary specialization. This changes its
--     label in Rotation Master, not your character talents or specialization.
[2581] = "Choisissez le nom affiché pour votre spécialisation secondaire. Cela change son libellé dans Rotation Master, pas les talents ni la spécialisation de votre personnage.",
-- b49fc138 English: Choose the amount of Rotation Master chat output. Silent suppresses routine
--     output. Default reports normal changes such as rotation switching. Debug adds runtime
--     statistics and trigger information. Verbose includes detailed condition and highlight
--     activity and can produce substantial output.
[2582] = "Choisissez la quantité de messages de Rotation Master dans la fenêtre de discussion. Silencieux supprime les messages courants. Par défaut signale les changements normaux, comme la bascule de rotation. Débogage ajoute des statistiques d'exécution et des informations sur les déclencheurs. Détaillé inclut l'activité détaillée des conditions et des surbrillances et peut produire beaucoup de messages.",
-- d0d316d9 English: Include component timings in the periodic Debug or Verbose profiling report.
--     Reports show measured runs, total, minimum, average and maximum in milliseconds. Timings
--     include child work; nested scopes overlap and must not be added together. The overall scope
--     starts after rotation preparation. This is elapsed timing, not the native addon CPU report.
[2583] = "Inclut la durée de chaque composant dans le rapport de profilage périodique en mode Débogage ou Détaillé. Les rapports indiquent les exécutions mesurées, le total, le minimum, la moyenne et le maximum en millisecondes. Les durées incluent le travail des sous-composants ; les portées imbriquées se chevauchent et ne doivent pas être additionnées. La portée globale commence après la préparation de la rotation. Il s'agit d'un temps écoulé, pas du rapport CPU natif des addons.",
-- fd1963a1 English: Effects define how action-bar icons are highlighted. They are shared across
--     characters. General settings select the main recommendation effect and cooldown default;
--     individual cooldowns can choose another effect. Select an effect in the sidebar to inspect or
--     edit it.
[2584] = "Les effets définissent la mise en surbrillance des icônes des barres d'action. Ils sont partagés entre les personnages. Les réglages de Général sélectionnent l'effet de la recommandation principale et celui par défaut des temps de recharge ; chaque temps de recharge peut choisir un autre effet. Sélectionnez un effet dans la barre latérale pour l'examiner ou le modifier.",
-- 40b0b9e0 English: Give the effect a name used by selectors in General and cooldown action
--     details. New drafts can change type and fields before being named, but Apply requires a
--     nonempty, unique name.
[2585] = "Donnez à l'effet un nom, utilisé par les sélecteurs de Général et des détails d'action des temps de recharge. Un nouveau brouillon peut changer de type et de champs avant d'être nommé, mais Appliquer exige un nom unique et non vide.",
-- 5a00db51 English: Choose the highlight implementation. Changing type stages the new fields and
--     resets its sequence because different sequence types store different values. Choosing the
--     current type preserves existing values. Apply saves the change; Discard restores the saved
--     effect.
[2586] = "Choisissez l'implémentation de la surbrillance. Changer de type prépare les nouveaux champs et réinitialise la séquence, car les différents types de séquence stockent des valeurs différentes. Choisir le type actuel conserve les valeurs existantes. Appliquer enregistre la modification ; Abandonner rétablit l'effet enregistré.",
-- c228a709 English: Texture: overlay a single image from game data or an installed addon. Its
--     color, magnification and position come from the profile or the individual cooldown.
[2587] = "Texture : superpose une seule image provenant des données du jeu ou d'un addon installé. Sa couleur, son agrandissement et sa position proviennent du profil ou du temps de recharge concerné.",
-- cd1a7948 English: Pixel: animate short lines around the action icon border. Lines, Frequency,
--     Length and Thickness control this library glow.
[2588] = "Pixel : anime de courts traits autour du bord de l'icône d'action. Lignes, Fréquence, Longueur et Épaisseur règlent cette lueur de la bibliothèque.",
-- 8f767bf7 English: Auto Cast: animate groups of glowing particles around the action icon.
--     Particles, Frequency and Scale control this library glow.
[2589] = "Incantation auto : anime des groupes de particules lumineuses autour de l'icône d'action. Particules, Fréquence et Échelle règlent cette lueur de la bibliothèque.",
-- 0984e57a English: Glow: use the familiar Blizzard-style button glow. Frequency controls its
--     animation rate.
[2590] = "Lueur : utilise la lueur de bouton familière, dans le style de Blizzard. Fréquence règle la vitesse de son animation.",
-- 4f13ce4d English: Dazzle: keep one texture and cycle through the sequence of colors. Each
--     sequence card contains one RGBA color.
[2591] = "Éblouissement : conserve une texture et parcourt la séquence de couleurs. Chaque carte de séquence contient une couleur RGBA.",
-- 518c7a0b English: Animate: cycle through the sequence of texture images. Each card selects one
--     image and previews that selection.
[2592] = "Animation : parcourt la séquence d'images de texture. Chaque carte sélectionne une image et en affiche l'aperçu.",
-- 7db1adc9 English: Pulse: keep one texture and cycle through the sequence of magnifications. Each
--     card selects one scale relative to the action icon.
[2593] = "Pulsation : conserve une texture et parcourt la séquence d'agrandissements. Chaque carte sélectionne une échelle relative à l'icône d'action.",
-- 04c25e44 English: Rotate: animate one texture through evenly spaced angles around a full circle.
--     Steps chooses the number of angles and Reverse changes their order.
[2594] = "Pivotement : anime une texture selon des angles régulièrement espacés sur un tour complet. Étapes choisit le nombre d'angles et Inverser change leur ordre.",
-- e239b9d1 English: Custom: cycle through cards containing a texture, angle, magnification and
--     color. Each card supplies its own settings instead of relying on one shared texture.
[2595] = "Personnalisé : parcourt des cartes contenant chacune une texture, un angle, un agrandissement et une couleur. Chaque carte fournit ses propres réglages au lieu de dépendre d'une texture partagée.",
-- 1b35109f English: The image beside Name and Type previews the current draft with a white color
--     and standard size. Texture and sequence changes update the preview without saving. Actual
--     recommendations use their profile or cooldown color, size and offsets.
[2596] = "L'image à côté de Nom et Type affiche un aperçu du brouillon actuel en blanc et à taille standard. Les changements de texture et de séquence mettent à jour l'aperçu sans enregistrer. Les recommandations réelles utilisent la couleur, la taille et les décalages de leur profil ou de leur temps de recharge.",
-- 69030e6a English: For Texture, Dazzle, Pulse and Rotate, choose the image used throughout the
--     effect. The arrow beside an image field opens the bundled overlay catalog with previews.
--     Enter an available texture path or numeric file ID to use another image. Animate and Custom
--     choose images in their sequence cards using the same controls. Selections update the draft
--     and preview; Apply saves them.
[2597] = "Pour Texture, Éblouissement, Pulsation et Pivotement, choisissez l'image utilisée dans tout l'effet. La flèche à côté d'un champ d'image ouvre le catalogue de superpositions fourni, avec aperçus. Saisissez un chemin de texture disponible ou un identifiant de fichier numérique pour utiliser une autre image. Animation et Personnalisé choisissent les images dans leurs cartes de séquence avec les mêmes commandes. Les sélections mettent à jour le brouillon et l'aperçu ; Appliquer les enregistre.",
-- 06895a3f English: Pixel effects: choose the number of animated lines around the button, from 1 to
--     20.
[2598] = "Effets Pixel : choisissez le nombre de traits animés autour du bouton, de 1 à 20.",
-- 5a02f176 English: Pixel effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every four
--     seconds.
[2599] = "Effets Pixel : cycles par seconde, avec signe. Une valeur absolue plus grande va plus vite ; une valeur négative inverse le sens. Zéro utilise la valeur par défaut de la bibliothèque de lueurs, soit un cycle toutes les quatre secondes.",
-- 912f8432 English: Pixel effects: choose line length in pixels. The glow library limits it to the
--     smaller button dimension.
[2600] = "Effets Pixel : choisissez la longueur des traits en pixels. La bibliothèque de lueurs la limite à la plus petite dimension du bouton.",
-- 888c1858 English: Pixel effects: choose line thickness in pixels, from 1 to 5.
[2601] = "Effets Pixel : choisissez l'épaisseur des traits en pixels, de 1 à 5.",
-- f169cd48 English: Auto Cast effects: choose 1 to 4 particles in each of the glow library particle
--     groups.
[2602] = "Effets Incantation auto : choisissez de 1 à 4 particules dans chacun des groupes de particules de la bibliothèque de lueurs.",
-- 439eb6b4 English: Auto Cast effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every
--     eight seconds.
[2603] = "Effets Incantation auto : cycles par seconde, avec signe. Une valeur absolue plus grande va plus vite ; une valeur négative inverse le sens. Zéro utilise la valeur par défaut de la bibliothèque de lueurs, soit un cycle toutes les huit secondes.",
-- ee4e74b2 English: Auto Cast effects: scale the particles relative to the glow library default. A
--     value of 1 uses their normal size.
[2604] = "Effets Incantation auto : met les particules à l'échelle par rapport à la valeur par défaut de la bibliothèque de lueurs. Une valeur de 1 utilise leur taille normale.",
-- 7a5e1fd3 English: Glow effects: adjust the library animation rate. Larger positive values animate
--     faster. Zero uses the library default rather than stopping the glow.
[2605] = "Effets Lueur : réglez la vitesse d'animation de la bibliothèque. Des valeurs positives plus grandes animent plus vite. Zéro utilise la valeur par défaut de la bibliothèque au lieu d'arrêter la lueur.",
-- a09487cf English: Dazzle effects: seconds between color cards. A smaller positive interval
--     changes colors more often; the sequence repeats after the last color.
[2606] = "Effets Éblouissement : secondes entre les cartes de couleur. Un intervalle positif plus court change de couleur plus souvent ; la séquence recommence après la dernière couleur.",
-- 9e3ad582 English: Animate effects: seconds between texture cards. A smaller positive interval
--     changes images more often; the sequence repeats after the last image.
[2607] = "Effets Animation : secondes entre les cartes de texture. Un intervalle positif plus court change d'image plus souvent ; la séquence recommence après la dernière image.",
-- 73861ddb English: Pulse effects: seconds between magnification cards. A smaller positive interval
--     changes size more often; the sequence repeats after the last size.
[2608] = "Effets Pulsation : secondes entre les cartes d'agrandissement. Un intervalle positif plus court change de taille plus souvent ; la séquence recommence après la dernière taille.",
-- 6f691c60 English: Rotate effects: seconds between angle steps. A smaller positive interval
--     rotates faster. One full cycle uses this interval multiplied by Steps.
[2609] = "Effets Pivotement : secondes entre les étapes d'angle. Un intervalle positif plus court fait pivoter plus vite. Un cycle complet dure cet intervalle multiplié par Étapes.",
-- 78b58b96 English: Rotate effects: choose 2 to 36 evenly spaced angles for a full turn. More steps
--     at the same Frequency interval make a longer complete cycle.
[2610] = "Effets Pivotement : choisissez de 2 à 36 angles régulièrement espacés pour un tour complet. Plus d'étapes avec le même intervalle de Fréquence allongent le cycle complet.",
-- 98768f9e English: Rotate effects: reverse the order of angle steps. Changing this checkbox does
--     not alter the texture or number of steps.
[2611] = "Effets Pivotement : inverse l'ordre des étapes d'angle. Cocher ou décocher cette case ne modifie ni la texture ni le nombre d'étapes.",
-- 0eaebb24 English: Custom effects: seconds between sequence cards. A smaller positive interval
--     changes settings more often; the sequence repeats after the last card.
[2612] = "Effets Personnalisé : secondes entre les cartes de séquence. Un intervalle positif plus court change de réglages plus souvent ; la séquence recommence après la dernière carte.",
-- a85d837a English: Sequence cards play in order and repeat. Add step, on the Sequence header row,
--     appends a card; drag Add step into a gap to insert one there. Drag a card into an insertion
--     gap to reorder it; hold Ctrl when starting to carry it and all following cards. Up and Down
--     move one card and are disabled at their respective ends. The red trash removes a card from
--     the draft. Canceling a drag restores its original position.
[2613] = "Les cartes de séquence sont jouées dans l'ordre puis recommencent. Ajouter une étape, sur la ligne d'en-tête Séquence, ajoute une carte à la fin ; faites glisser Ajouter une étape dans un intervalle pour en insérer une à cet endroit. Faites glisser une carte dans un intervalle d'insertion pour la réordonner ; maintenez Ctrl au début du glissement pour emporter aussi toutes les cartes suivantes. Haut et Bas déplacent une carte d'une position et sont désactivés à leurs extrémités respectives. La corbeille rouge retire une carte du brouillon. Annuler un glissement rétablit sa position d'origine.",
-- d5a4691e English: Animate and Custom cards: choose a texture path or numeric file ID. The card
--     preview shows the selected image. Custom also keeps an independent angle, magnification and
--     color on that card.
[2614] = "Cartes Animation et Personnalisé : choisissez un chemin de texture ou un identifiant de fichier numérique. L'aperçu de la carte montre l'image sélectionnée. Personnalisé conserve aussi un angle, un agrandissement et une couleur indépendants sur cette carte.",
-- e9c4d7cb English: Custom cards: set the texture angle in degrees from 0 to 359. This is the angle
--     for this card, rather than a continuous rotation speed.
[2615] = "Cartes Personnalisé : définissez l'angle de la texture en degrés, de 0 à 359. Il s'agit de l'angle de cette carte, et non d'une vitesse de rotation continue.",
-- f9eb09ea English: Pulse and Custom cards: scale the texture relative to the action icon. A value
--     of 1 uses the icon size. Use the slider or edit its numeric value.
[2616] = "Cartes Pulsation et Personnalisé : mettez la texture à l'échelle par rapport à l'icône d'action. Une valeur de 1 utilise la taille de l'icône. Utilisez le curseur ou modifiez sa valeur numérique.",
-- a6ca83b6 English: Dazzle and Custom cards: choose an RGBA color. Click the swatch to open the
--     picker, or edit channels between 0 and 1. Alpha controls opacity.
[2617] = "Cartes Éblouissement et Personnalisé : choisissez une couleur RGBA. Cliquez sur l'échantillon pour ouvrir le sélecteur, ou modifiez les canaux entre 0 et 1. Alpha contrôle l'opacité.",
-- d838f5ee English: Edits and sequence changes remain in a draft. Apply saves; Discard restores the
--     saved effect. Cancel closes a new creation draft. View Changes compares saved and unsaved
--     values. New drafts require a unique name and valid fields before Apply. Leaving with edits
--     offers Apply, Discard or Cancel.
[2618] = "Les modifications et les changements de séquence restent dans un brouillon. Appliquer enregistre ; Abandonner rétablit l'effet enregistré. Annuler ferme un brouillon de création. Voir les modifications compare les valeurs enregistrées et non enregistrées. Un nouveau brouillon exige un nom unique et des champs valides avant Appliquer. Quitter avec des modifications propose Appliquer, Abandonner ou Annuler.",
-- 781f5d06 English: The red trash at the upper right deletes the selected effect after a
--     permanent-deletion warning. Resolve pending edits first. Choose a replacement for any profile
--     or cooldown using that effect; deletion does not silently rewrite those references.
[2619] = "La corbeille rouge en haut à droite supprime l'effet sélectionné après un avertissement de suppression définitive. Réglez d'abord les modifications en attente. Choisissez un remplaçant pour chaque profil ou temps de recharge qui utilise cet effet ; la suppression ne réécrit pas ces références à votre insu.",
-- a8f923ca English: New, Duplicate, Import/Export and Compare are below the sidebar. Duplicate
--     copies the selected effect into a draft. Transfers show the original name and let you create
--     a renamed copy or replace the selection when allowed. Compare inspects differences without
--     saving them.
[2620] = "Nouveau, Dupliquer, Import/Export et Comparer se trouvent sous la barre latérale. Dupliquer copie l'effet sélectionné dans un brouillon. Les transferts affichent le nom d'origine et permettent de créer une copie renommée ou de remplacer la sélection lorsque c'est autorisé. Comparer examine les différences sans les enregistrer.",
-- fe52fcf9 English: Selecting a sidebar row only inspects that profile. Activate profile switches
--     the live profile immediately, including its rotations and settings. The active profile shows
--     Active profile instead. This operation does not wait for page Apply.
[2621] = "Sélectionner une ligne de la barre latérale ne fait qu'examiner ce profil. Activer le profil bascule immédiatement le profil en cours, y compris ses rotations et réglages. Le profil actif affiche Profil actif à la place. Cette opération n'attend pas l'Appliquer de la page.",
-- 605ecea0 English: Choose a source to replace the active profile after confirmation. This copies
--     settings and rotations into the active profile, even when the sidebar is inspecting a
--     different profile. It does not switch to the source or rename the active profile. Cancel at
--     the confirmation preserves the current profile.
[2622] = "Choisissez une source pour remplacer le profil actif après confirmation. Cela copie les réglages et rotations dans le profil actif, même lorsque la barre latérale examine un autre profil. Cela ne bascule pas vers la source et ne renomme pas le profil actif. Annuler lors de la confirmation conserve le profil actuel.",
-- d403202f English: Reset current profile replaces the active profile with its defaults after
--     confirmation. Custom rotations and settings in it are replaced. The control is disabled while
--     inspecting another profile. Reset is immediate after confirmation; there is no later page
--     Apply to undo it.
[2623] = "Réinitialiser le profil actuel remplace le profil actif par ses valeurs par défaut après confirmation. Les rotations et réglages personnalisés qu'il contient sont remplacés. La commande est désactivée pendant l'examen d'un autre profil. La réinitialisation est immédiate après confirmation ; aucun Appliquer ultérieur de la page ne permet de l'annuler.",
-- 071e02f8 English: The red trash can permanently removes the selected inactive profile after
--     confirmation. The active profile and Default cannot be deleted here. Selecting another
--     profile does not delete or activate it.
[2624] = "La corbeille rouge supprime définitivement le profil inactif sélectionné après confirmation. Le profil actif et Default ne peuvent pas être supprimés ici. Sélectionner un autre profil ne le supprime pas et ne l'active pas.",
-- e0223ba4 English: New and Duplicate open a named draft. Use a nonblank, unused name of at most 50
--     characters. Apply creates the profile; Cancel abandons creation. Creating a profile leaves
--     the previously active profile active, so use Activate profile when you want to switch to the
--     new copy.
[2625] = "Nouveau et Dupliquer ouvrent un brouillon nommé. Utilisez un nom non vide et inutilisé de 50 caractères au plus. Appliquer crée le profil ; Annuler abandonne la création. Créer un profil laisse actif le profil précédemment actif ; utilisez donc Activer le profil pour basculer vers la nouvelle copie.",
-- c85ff72a English: The buttons below the list create a new profile, duplicate the selected
--     profile, transfer profiles or compare saved settings. Search narrows the list without
--     activating a profile. Import/Export shows the original name and lets you replace the
--     selection or create a renamed copy. Importing a new profile opens a creation draft; Apply
--     saves it. Replacing a selected profile happens when you confirm the import, and replacing the
--     active profile updates its runtime settings. Compare does not apply changes.
[2626] = "Les boutons sous la liste créent un nouveau profil, dupliquent le profil sélectionné, transfèrent des profils ou comparent les réglages enregistrés. La recherche filtre la liste sans activer de profil. Import/Export affiche le nom d'origine et permet de remplacer la sélection ou de créer une copie renommée. Importer un nouveau profil ouvre un brouillon de création ; Appliquer l'enregistre. Le remplacement d'un profil sélectionné a lieu lorsque vous confirmez l'import, et remplacer le profil actif met à jour ses réglages en cours d'exécution. Comparer n'applique aucune modification.",
-- d58adae2 English: Status pills show Not loaded, Supported, Disabled, Enabled or Selected. Click
--     Enabled to Select or Disable. Disabling Selected chooses the sole enabled available editor,
--     offers a choice when several exist, or leaves none selected. Enabling an editor when none is
--     selected selects it automatically. Native is always available; its Syntax highlighting option
--     is independent of editor selection. With no enabled editor, emergency plain text remains
--     usable. Apply saves preferences for the next source-editor opening; Discard keeps saved
--     settings. An open editor keeps its current provider.
[2627] = "Les pastilles d'état indiquent Non chargé, Pris en charge, Désactivé, Activé ou Sélectionné. Cliquez sur Activé pour Sélectionner ou Désactiver. Désactiver l'éditeur Sélectionné choisit le seul éditeur disponible activé, propose un choix s'il y en a plusieurs, ou n'en sélectionne aucun. Activer un éditeur alors qu'aucun n'est sélectionné le sélectionne automatiquement. Natif est toujours disponible ; son option Coloration syntaxique est indépendante de la sélection de l'éditeur. Sans éditeur activé, le texte brut de secours reste utilisable. Appliquer enregistre les préférences pour la prochaine ouverture d'un éditeur de source ; Abandonner conserve les réglages enregistrés. Un éditeur ouvert conserve son fournisseur actuel.",
-- 3bdeb012 English: Show line numbers controls the gutter in every condition and function code
--     editor. It defaults to enabled. Apply saves the preference and updates open code panes;
--     Discard keeps the saved setting. It does not change the Lua source or its line breaks.
[2628] = "Afficher les numéros de ligne contrôle la gouttière de chaque éditeur de code de condition et de fonction. Activé par défaut. Appliquer enregistre la préférence et met à jour les volets de code ouverts ; Abandonner conserve le réglage enregistré. Cela ne modifie ni la source Lua ni ses sauts de ligne.",
-- e69d5940 English: Addon names open copyable official release and source links across available
--     providers. Edition filtering follows declared support for the matching addon identity;
--     unknown compatibility remains visible. An older release date alone does not prove
--     incompatibility. Listed game-edition support describes publisher release evidence, not
--     certification of the integration on your client. Some integrations have only historical or
--     unverified releases. Not loaded means unavailable to RM; Supported identifies an available
--     integration without an enable switch. Bundled libraries are excluded. Rotation Master does
--     not install or enable other addons.
[2629] = "Les noms d'addons ouvrent des liens copiables vers les versions officielles et les sources, chez les fournisseurs disponibles. Le filtrage par édition suit la prise en charge déclarée pour l'addon correspondant ; une compatibilité inconnue reste visible. Une date de publication ancienne ne prouve pas à elle seule une incompatibilité. La prise en charge des éditions du jeu indiquée reflète les publications de l'éditeur, pas une certification de l'intégration sur votre client. Certaines intégrations n'ont que des versions historiques ou non vérifiées. Non chargé signifie indisponible pour RM ; Pris en charge désigne une intégration disponible sans interrupteur d'activation. Les bibliothèques intégrées sont exclues. Rotation Master n'installe ni n'active d'autres addons.",
-- 6c182d42 English: Apply / Discard
-- Context: Help topic title for the buttons that save or abandon edits in an item list dialog and
--     the window.
[2630] = "Appliquer / Abandonner",
-- d04a65ba English: Edits stay in a draft until Apply. Discard abandons pending changes. Leaving
--     with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect
--     previews do not save changes. Action-bar binding operations are explicit and immediate.
[2631] = "Les modifications restent dans un brouillon jusqu'à Appliquer. Abandonner annule les modifications en attente. Quitter avec des modifications propose Appliquer, Abandonner ou Annuler ; Annuler garde la page et le brouillon ouverts. Les aperçus d'effets n'enregistrent pas les modifications. Les opérations de liaison aux barres d'action sont explicites et immédiates.",
-- 2be8c485 English: Diagram / List changes only the rotation view; General settings choose the
--     default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll
--     to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty
--     diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms,
--     False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in
--     every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse
--     nearby card controls as you navigate. Folded branches intentionally hide their children.
[2632] = "Diagramme / Liste ne change que la vue des rotations ; les réglages de Général choisissent la vue par défaut. Diagramme dispose de commandes flottantes moins, pourcentage et plus en bas à droite. Faites défiler pour zoomer de 25 % à 200 % ; cliquez sur le pourcentage ou faites un clic du milieu pour revenir à 100 %. Faites glisser un espace vide du diagramme pour le déplacer. Liste utilise des barres de défilement normales, avec des cartes accolées et des branches encadrées, Faux avant Vrai. Les temps de recharge utilisent une grille défilante séparée. Faire glisser des cartes les réordonne dans toutes les vues. Le corps d'une rotation valide peut contenir jusqu'à 2 000 étapes au total ; les grands espaces de travail réutilisent les commandes de cartes proches pendant la navigation. Les branches repliées masquent volontairement leurs enfants.",
-- 76bac84a English: New / Duplicate / Import / Compare
[2633] = "Nouveau / Dupliquer / Importer / Comparer",
-- c4875790 English: Choose a category and search for a condition. Hidden removes it from pickers
--     without deleting its definition. Switch Condition controls its availability for automatic
--     rotation switching. Move To stages a category destination; its Apply button confirms the
--     move. The assigned category opens category management. Sidebar arrows and dragging order
--     entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom
--     conditions can be edited, duplicated or deleted.
[2634] = "Choisissez une catégorie et recherchez une condition. Masqué la retire des sélecteurs sans supprimer sa définition. Condition de bascule contrôle sa disponibilité pour la bascule automatique de rotation. Déplacer vers prépare une catégorie de destination ; son bouton Appliquer confirme le déplacement. La catégorie attribuée ouvre la gestion des catégories. Les flèches de la barre latérale et le glisser-déposer ordonnent les entrées. L'Appliquer de la page enregistre le brouillon ; Abandonner annule les modifications d'une entrée enregistrée. Les conditions personnalisées peuvent être modifiées, dupliquées ou supprimées.",
-- be63470b English: Select an effect to edit its name, type and type-specific settings. The icon
--     previews it live. Sequence sections edit animation, color, pulse or custom frames in order.
--     Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields
--     remain editable. New effects can be configured before naming. Apply saves the draft; Discard
--     abandons edits to a saved entry. Import stages a validated replacement.
[2635] = "Sélectionnez un effet pour modifier son nom, son type et ses réglages propres au type. L'icône en affiche un aperçu en direct. Les sections de séquence modifient dans l'ordre les images d'animation, de couleur, de pulsation ou personnalisées. Dupliquer crée un effet indépendant. Faites glisser la surface d'une carte de séquence pour la réordonner ; les champs restent modifiables. Un nouvel effet peut être configuré avant d'être nommé. Appliquer enregistre le brouillon ; Abandonner annule les modifications d'une entrée enregistrée. Importer prépare un remplacement validé.",
-- e7df5868 English: Choose an item set and edit its priority list. Global shares the set across
--     profiles. Move arrows change item priority. Bind item set picks up an available item for
--     placement on an action bar; The binding pill removes matching bound bar actions when
--     unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference
--     fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are
--     explicit action-bar operations.
[2636] = "Choisissez un ensemble d'objets et modifiez sa liste de priorités. Global partage l'ensemble entre les profils. Les flèches de déplacement changent la priorité des objets. Lier l'ensemble d'objets prend un objet disponible pour le placer sur une barre d'action ; lors de la déliaison, la pastille de liaison retire, hors combat, les actions de barre liées correspondantes. Réinitialiser restaure un ensemble fourni. Recherchez ou faites glisser des objets dans les champs de référence. Appliquer enregistre les réglages ; Abandonner annule les modifications d'une entrée enregistrée. Les changements de liaison sont des opérations explicites sur les barres d'action.",
-- 27a02657 English: Press Enter or leave a text field to stage its value; Apply saves the draft.
--     Invalid text stays red and must be corrected before Apply; Discard can abandon it. Searchable
--     selectors open on click and filter as you type. Section headings collapse or expand their
--     contents.
[2637] = "Appuyez sur Entrée ou quittez un champ de texte pour préparer sa valeur ; Appliquer enregistre le brouillon. Un texte invalide reste en rouge et doit être corrigé avant Appliquer ; Abandonner permet de l'annuler. Les sélecteurs avec recherche s'ouvrent au clic et filtrent pendant la saisie. Les titres de section replient ou déplient leur contenu.",
-- 53a70ff7 English: Editing this list
-- Context: Help topic title at the top of the item list dialog help.
[2638] = "Modification de cette liste",
-- d71ea291 English: This window edits only the item list you opened. Search or drag items into the
--     fields, then arrange preferred items first. A named item set is shared by its other users; a
--     custom list belongs to the calling condition or action draft. Applying this list does not
--     apply the parent editor.
[2639] = "Cette fenêtre ne modifie que la liste d'objets que vous avez ouverte. Recherchez ou faites glisser des objets dans les champs, puis placez les objets préférés en premier. Un ensemble d'objets nommé est partagé avec ses autres utilisateurs ; une liste personnalisée appartient au brouillon de la condition ou de l'action appelante. Appliquer cette liste n'applique pas l'éditeur parent.",
-- 05cdc879 English: Use a row's red trash can to remove that entry from the draft list. This does
--     not delete a named item set or remove an item from your inventory. The removal takes effect
--     when you Apply this list.
[2640] = "Utilisez la corbeille rouge d'une ligne pour retirer cette entrée de la liste en brouillon. Cela ne supprime pas un ensemble d'objets nommé et ne retire aucun objet de votre inventaire. Le retrait prend effet lorsque vous appliquez cette liste.",
-- 3cedce54 English: Apply validates every entry and writes the edited list back to its original
--     owner. Discard closes without changing it. Closing with pending edits offers Apply, Discard
--     or Cancel; Cancel keeps this window open. View Changes compares the original list with this
--     draft. If the original list changed elsewhere, close and reopen it before applying.
[2641] = "Appliquer valide chaque entrée et réécrit la liste modifiée chez son propriétaire d'origine. Abandonner ferme sans la modifier. Fermer avec des modifications en attente propose Appliquer, Abandonner ou Annuler ; Annuler garde cette fenêtre ouverte. Voir les modifications compare la liste d'origine à ce brouillon. Si la liste d'origine a été modifiée ailleurs, fermez-la et rouvrez-la avant d'appliquer.",
-- 54637cac English: Proc Glow: use the animated actionbar proc border from LibCustomGlow. Rotation
--     Master checks the required game artwork and animation support before using it. Unsupported
--     clients use Pixel glow instead; the definition remains portable. Color and offsets come from
--     the profile or the cooldown.
[2642] = "Lueur de proc : utilise la bordure de proc animée des barres d'action de LibCustomGlow. Rotation Master vérifie que les illustrations et la prise en charge des animations requises sont présentes dans le jeu avant de l'utiliser. Les clients non pris en charge utilisent la lueur Pixel à la place ; la définition reste portable. La couleur et les décalages proviennent du profil ou du temps de recharge.",
-- 265e2457 English: Time in seconds for one repeating proc-border animation, from 0.1 to 5. Use the
--     slider or enter an exact value in its number field. Changing the value updates the preview.
[2643] = "Durée en secondes d'une animation répétée de la bordure de proc, de 0,1 à 5. Utilisez le curseur ou saisissez une valeur exacte dans son champ numérique. Modifier la valeur met à jour l'aperçu.",
-- 50bd053e English: Play the opening burst when this highlight first appears, then repeat its
--     border animation. Off by default. Refreshing an already visible Proc Glow does not restart
--     the burst.
[2644] = "Joue l'éclat initial lorsque cette surbrillance apparaît, puis répète l'animation de sa bordure. Désactivé par défaut. Actualiser une Lueur de proc déjà visible ne relance pas l'éclat.",
-- a0515628 English: Rotations belong to the active settings profile. New copies use Class, shared
--     by your characters of that class; Metadata can change this to This character. Built In
--     rotations show only for their declared class or universal use. Equal identifiers in different
--     owners remain separate entries.
[2645] = "Les rotations appartiennent au profil de réglages actif. Les nouvelles copies utilisent Classe, partagée par vos personnages de cette classe ; Métadonnées permet de passer à Ce personnage. Les rotations Intégrées ne s'affichent que pour leur classe déclarée ou pour un usage universel. Des identifiants identiques chez des propriétaires différents restent des entrées distinctes.",
-- 774a185e English: Older rotations without a recorded owner stay in an archive. Recover unassigned
--     rotations opens the current profile and character archives for inspection or copying. Choose
--     Class or This character to adopt one. Adoption preserves its identifier and evidence, refuses
--     an existing destination, and leaves incomplete records unavailable until repaired.
[2646] = "Les anciennes rotations sans propriétaire enregistré restent dans une archive. Récupérer les rotations non attribuées ouvre les archives du profil actuel et du personnage pour les examiner ou les copier. Choisissez Classe ou Ce personnage pour en adopter une. L'adoption conserve son identifiant et ses preuves, refuse une destination existante et laisse les enregistrements incomplets indisponibles jusqu'à leur réparation.",
-- 4886d663 English: Enable Questie integration
-- Context: Help topic title in Integrations help for the checkbox that turns on the Questie
--     integration.
[2647] = "Activer l'intégration de Questie",
-- 3a9724aa English: Review supported addons, detected versions and status by integration type.
--     Expand or collapse each integration group. Click an addon name to choose a copyable release
--     or source link. Configure editor and optional provider preferences here; Apply saves
--     preferences for this profile and Discard keeps saved settings.
[2648] = "Consultez les addons pris en charge, les versions détectées et l'état par type d'intégration. Dépliez ou repliez chaque groupe d'intégrations. Cliquez sur le nom d'un addon pour choisir un lien copiable vers une version ou une source. Configurez ici l'éditeur et les préférences de fournisseurs facultatifs ; Appliquer enregistre les préférences pour ce profil et Abandonner conserve les réglages enregistrés.",
-- 25f09788 English: Opt in to Questie callbacks for this profile, then Apply. Discard does not
--     change the saved connection. Readiness, API compatibility, source-tested version and native
--     acceptance are reported separately. The adapter retains recent update receipts only; they do
--     not prove quest progress or completion and do not select rotations. No background polling is
--     used.
[2649] = "Activez les callbacks de Questie pour ce profil, puis cliquez sur Appliquer. Abandonner ne modifie pas la connexion enregistrée. La disponibilité, la compatibilité de l'API, la version testée sur la source et l'acceptation native sont indiquées séparément. L'adaptateur ne conserve que les reçus de mise à jour récents ; ils ne prouvent ni la progression ni l'achèvement des quêtes et ne sélectionnent pas de rotation. Aucune interrogation en arrière-plan n'est utilisée.",
-- 3877e4d7 English: Enable DBM or BigWigs to feed the Boss Mod conditions (encounter, stage and
--     ability timers), then Apply. Only one boss mod can be enabled; enabling one disables the
--     other. RM listens to the boss mod's own callbacks and never polls it or changes its settings.
--     With none enabled, or the enabled addon not loaded, Boss Mod conditions are unavailable.
--     Supported on Classic Era, TBC and Classic progression clients.
[2650] = "Activez DBM ou BigWigs pour alimenter les conditions de module de boss (minuteurs de rencontre, de phase et de techniques), puis cliquez sur Appliquer. Un seul module de boss peut être activé ; en activer un désactive l'autre. RM écoute les callbacks propres au module de boss ; il ne l'interroge jamais et ne modifie pas ses réglages. Si aucun n'est activé, ou si l'addon activé n'est pas chargé, les conditions de module de boss sont indisponibles. Pris en charge sur les clients Classic Era, TBC et Classic progression.",
-- c9949fc6 English: Rotation Master publishes a LibDataBroker data source with the active rotation,
--     a tooltip and click menus. Titan Panel and other LibDataBroker displays show it without
--     further setup: in Titan, add Rotation Master from the plugin menu. Panel absence has no
--     effect on rotation selection.
[2651] = "Rotation Master publie une source de données LibDataBroker avec la rotation active, une infobulle et des menus au clic. Titan Panel et les autres affichages LibDataBroker l'affichent sans configuration supplémentaire : dans Titan, ajoutez Rotation Master depuis le menu des plugins. L'absence de panneau n'a aucun effet sur la sélection de la rotation.",
-- 59df493c English: Record spell cast receipts for thirty seconds without changing settings or
--     gameplay polling. While it runs this button reads Stop cast capture and ends the capture
--     early, keeping what was recorded.
[2652] = "Enregistre les reçus de lancer de sorts pendant trente secondes, sans modifier les réglages ni l'interrogation en jeu. Pendant la capture, ce bouton devient Arrêter la capture des lancers et termine la capture plus tôt, en conservant ce qui a été enregistré.",
-- 0ffbf212 English: Open the copyable cast receipt report. It stays disabled until a cast capture
--     has produced a report and while a capture is running.
[2653] = "Ouvre le rapport copiable des reçus de lancer. Il reste désactivé tant qu'aucune capture des lancers n'a produit de rapport, ainsi que pendant une capture.",
-- 472590ae English: Provider
-- Context: Column heading in the addon download links dialog: the website that hosts the download
--     (e.g. CurseForge).
[2654] = "Fournisseur",
-- e7a241de English: URL
-- Context: Column heading in the addon download links dialog: the web address of the download page.
[2655] = "URL",
-- 8ea4edb6 English: Select URL for copying (Ctrl+C)
[2656] = "Sélectionner l'URL pour la copier (Ctrl+C)",
-- 42592899 English: Syntax highlighting applies only to the Native Lua editor. Apply saves this
--     preference for the next source-editor opening; it does not switch a selected external editor.
--     Show line numbers under the editor heading applies to every provider.
[2657] = "La coloration syntaxique ne s'applique qu'à l'éditeur Lua Natif. Appliquer enregistre cette préférence pour la prochaine ouverture d'un éditeur de source ; cela ne remplace pas un éditeur externe sélectionné. Afficher les numéros de ligne, sous le titre de l'éditeur, s'applique à tous les fournisseurs.",
-- eb084da9 English: Enable separately installed Masque here and Apply. General > Preview then
--     provides a Skin dropdown that updates the preview immediately. Masque owns the skin
--     selection; /masque opens its other settings. The preview window keeps its native appearance.
--     Missing or incompatible APIs and provider errors retain the native preview.
[2658] = "Activez ici Masque, installé séparément, puis cliquez sur Appliquer. Général > Aperçu propose alors une liste déroulante Habillage qui met à jour l'aperçu immédiatement. Masque gère la sélection de l'habillage ; /masque ouvre ses autres réglages. La fenêtre d'aperçu conserve son apparence native. En cas d'API manquantes ou incompatibles ou d'erreurs du fournisseur, l'aperçu natif est conservé.",
-- 34199d23 English: Enable Masque in Integrations to choose a skin. Skin changes update the open
--     preview immediately and are saved by Masque, independently of Apply or Discard. Without
--     enabled Masque support, the preview uses Blizzard Classic. Preview toggles sample icons
--     whether Masque is enabled or not.
[2659] = "Activez Masque dans Intégrations pour choisir un habillage. Les changements d'habillage mettent à jour immédiatement l'aperçu ouvert et sont enregistrés par Masque, indépendamment d'Appliquer ou d'Abandonner. Sans prise en charge de Masque activée, l'aperçu utilise Blizzard Classic. Aperçu affiche ou masque des icônes d'exemple, que Masque soit activé ou non.",
-- 5b167013 English: Click Preview to toggle temporary sample icons when no real recommendations are
--     available. Real recommendations replace the samples. This does not change Preview Spells,
--     cast spells, or save the sample state.
[2660] = "Cliquez sur Aperçu pour afficher ou masquer des icônes d'exemple temporaires lorsqu'aucune recommandation réelle n'est disponible. Les recommandations réelles remplacent les exemples. Cela ne modifie pas Aperçu des sorts, ne lance aucun sort et n'enregistre pas l'état des exemples.",
-- 04025773 English: Optional conditions use the Announcement condition list and All, Any and Not
--     groups. For spell, pet and item announcements, they run when the configured action and event
--     match. For Via Script/Macro, they run when you invoke the saved identifier. Each output card
--     checks its own conditions. Only a matching result allows that output; unavailable data skips
--     that card while later cards remain independent. In Group can check the Spell recipient
--     recorded for this cast, including click casting, without using your selected target. Choose
--     Announcement target to check the spell recipient for automatic entries, or the supplied unit
--     for Via Script/Macro; Whisper uses that same supplied unit. Automatic entries pass the
--     recorded recipient name to native unit queries. A missing or unresolvable recipient skips its
--     required condition; an unrelated selected target is never substituted. Missing or ambiguous
--     required recipients do not match. Apply in the condition editor updates the announcement
--     draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.
[2661] = "Les conditions facultatives utilisent la liste des conditions d'annonce et les groupes Toutes, N'importe laquelle et Non. Pour les annonces de sort, de familier et d'objet, elles s'exécutent lorsque l'action et l'événement configurés correspondent. Pour Via script/macro, elles s'exécutent lorsque vous invoquez l'identifiant enregistré. Chaque carte de sortie vérifie ses propres conditions. Seul un résultat correspondant autorise cette sortie ; des données indisponibles font ignorer cette carte, tandis que les cartes suivantes restent indépendantes. Dans un groupe peut vérifier le Destinataire du sort enregistré pour ce lancer, y compris en lancement par clic, sans utiliser votre cible sélectionnée. Choisissez Cible de l'annonce pour vérifier le destinataire du sort des entrées automatiques, ou l'unité fournie pour Via script/macro ; Chuchoter utilise cette même unité fournie. Les entrées automatiques transmettent le nom du destinataire enregistré aux requêtes d'unité natives. Un destinataire manquant ou impossible à résoudre fait ignorer sa condition requise ; une cible sélectionnée sans rapport n'est jamais substituée. Des destinataires requis manquants ou ambigus ne correspondent pas. Appliquer dans l'éditeur de conditions met à jour le brouillon de l'annonce ; Appliquer dans Annonces l'enregistre. Annuler ou Abandonner abandonne les modifications du brouillon.",
-- 6c64ce13 English: Choose the unit whose membership in your party or raid is checked. Player keeps
--     the original player group-status behavior. Spell recipient uses only the current announcement
--     event context; without that readable context the result is unavailable. It never substitutes
--     your selected target or a previous cast.
[2662] = "Choisissez l'unité dont l'appartenance à votre groupe ou raid est vérifiée. Joueur conserve le comportement d'origine de l'état de groupe du joueur. Destinataire du sort utilise uniquement le contexte de l'événement d'annonce en cours ; sans ce contexte lisible, le résultat est indisponible. Il ne lui substitue jamais votre cible sélectionnée ni un lancer précédent.",
-- 27cc3255 English: Checked tests raid membership only. Unchecked tests party membership or raid
--     membership. A known nonmember is false; unavailable native data stays unavailable, including
--     under NOT.
[2663] = "Cochée, ne vérifie que l'appartenance à un raid. Décochée, vérifie l'appartenance à un groupe ou à un raid. Un non-membre connu donne faux ; des données natives indisponibles restent indisponibles, y compris sous NOT.",
-- d44133b4 English: Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item
--     Sets, Announces, Profiles and Integrations. The opened panes have their own Help for page
--     controls. Search and filters belong to the current page. Built In entries remain read-only;
--     Duplicate creates an editable copy.
[2664] = "Choisissez des onglets pour parcourir Rotations, Général, Conditions, Fonctions, Effets, Ensembles d'objets, Annonces, Profils et Intégrations. Les volets ouverts ont leur propre Aide pour les commandes de la page. La recherche et les filtres concernent la page actuelle. Les entrées Intégrées restent en lecture seule ; Dupliquer crée une copie modifiable.",
-- 28510b80 English: Scale changes the whole workbench and its child windows from 70% to 130%. Drag
--     the top-left slider or enter an integer percentage and press Enter. Escape restores the saved
--     scale text. Drag the title bar to move; drag the lower-right corner to resize.
[2665] = "Échelle modifie la taille de tout l'atelier et de ses fenêtres enfants, de 70 % à 130 %. Faites glisser le curseur en haut à gauche ou saisissez un pourcentage entier et appuyez sur Entrée. Échap rétablit le texte de l'échelle enregistrée. Faites glisser la barre de titre pour déplacer la fenêtre ; faites glisser le coin inférieur droit pour la redimensionner.",
-- 81701f02 English: Close with X, Escape, or right-click inside the frontmost RM window. Child
--     dialogs have their own close controls and follow the window scale. The language selector
--     changes the workbench language; project links open a copyable address.
[2666] = "Fermez avec X, Échap ou un clic droit dans la fenêtre RM au premier plan. Les boîtes de dialogue enfants ont leurs propres commandes de fermeture et suivent l'échelle de la fenêtre. Le sélecteur de langue change la langue de l'atelier ; les liens du projet ouvrent une adresse copiable.",
-- ae7a65d1 English: Most settings and source editors keep drafts until Apply. Leaving a dirty page
--     offers Apply, Discard or Cancel; invalid fields remain visible. Profile activation and
--     confirmed replacement, action-bar binding and diagnostic capture have their own explicit
--     actions. Help never applies or discards edits.
[2667] = "La plupart des réglages et des éditeurs de source conservent des brouillons jusqu'à Appliquer. Quitter une page modifiée propose Appliquer, Abandonner ou Annuler ; les champs invalides restent visibles. L'activation de profil et le remplacement confirmé, la liaison aux barres d'action et la capture de diagnostic ont leurs propres actions explicites. L'Aide n'applique ni n'abandonne jamais les modifications.",
-- 2d6b5cc8 English: Gold question marks open full Help for their window, page or card. Hover
--     controls for brief tips. Help does not save settings or commit pending text; spell and item
--     fields keep their native reference tooltips.
[2668] = "Les points d'interrogation dorés ouvrent l'Aide complète de leur fenêtre, page ou carte. Survolez les commandes pour de brèves astuces. L'Aide n'enregistre pas les réglages et ne valide pas le texte en attente ; les champs de sort et d'objet conservent leurs infobulles de référence natives.",
-- 8fb57308 English: Open full Help for these controls without applying edits.
[2669] = "Ouvrir l'Aide complète de ces commandes sans appliquer les modifications.",
-- b9cc9038 English: Explain window navigation, scaling, closing and drafts.
[2670] = "Expliquer la navigation, la mise à l'échelle, la fermeture et les brouillons de la fenêtre.",
-- 859a4f2c English: Open full Help for this page without switching tabs or applying edits.
[2671] = "Ouvrir l'Aide complète de cette page sans changer d'onglet ni appliquer les modifications.",
-- c0a96039 English: Set the workbench and child-window scale from 70% to 130%; enter a whole
--     percentage or drag the slider.
[2672] = "Réglez l'échelle de l'atelier et des fenêtres enfants de 70 % à 130 % ; saisissez un pourcentage entier ou faites glisser le curseur.",
-- 36760759 English: Edit the value; Enter or leaving the field checks and accepts valid text. Page
--     Help explains when changes are saved.
[2673] = "Modifiez la valeur ; appuyer sur Entrée ou quitter le champ vérifie et accepte un texte valide. L'Aide de la page explique quand les modifications sont enregistrées.",
-- 43f47d2a English: Click to toggle this option. Page Help explains when changes are saved.
[2674] = "Cliquez pour activer ou désactiver cette option. L'Aide de la page explique quand les modifications sont enregistrées.",
-- 1b2d4c57 English: Use this control for the current page; page Help explains its options and
--     consequences.
[2675] = "Utilisez cette commande pour la page actuelle ; l'Aide de la page explique ses options et leurs conséquences.",
-- d885c6a2 English: Help for this condition is unavailable. Its registered definition is missing,
--     disabled or waiting for required functions. Opening Help does not register pending or
--     imported source.
[2676] = "L'Aide de cette condition est indisponible. Sa définition enregistrée est manquante, désactivée ou en attente de fonctions requises. Ouvrir l'Aide n'enregistre pas de source en attente ou importée.",
-- 711bb065 English: This registered condition does not provide Help.
[2677] = "Cette condition enregistrée ne fournit pas d'Aide.",
-- d9c613e5 English: Open Help for this condition without changing its fields.
[2678] = "Ouvrir l'Aide de cette condition sans modifier ses champs.",
-- ac330ed0 English: Select all export text for manual copying. This button does not send it
--     anywhere.
[2679] = "Sélectionner tout le texte d'export pour le copier manuellement. Ce bouton ne l'envoie nulle part.",
-- d8332c9a English: Clear the transfer text. A previous preview becomes invalid; saved settings
--     stay unchanged.
[2680] = "Effacer le texte de transfert. Un aperçu précédent devient invalide ; les réglages enregistrés restent inchangés.",
-- 7b980fdf English: Import into the displayed destination. Read the destination and review
--     requirements before continuing.
[2681] = "Importer dans la destination affichée. Lisez la destination et vérifiez les exigences avant de continuer.",
-- f71901b9 English: Close this dialog without importing its text.
[2682] = "Fermer cette boîte de dialogue sans importer son texte.",
-- 536a00ad English: Choose a new named copy or replacement of the selected editable entry.
[2683] = "Choisir une nouvelle copie nommée ou le remplacement de l'entrée modifiable sélectionnée.",
-- 28928c04 English: Set the name for a new copy. Replacement keeps the selected entry as its
--     destination.
[2684] = "Définir le nom d'une nouvelle copie. Un remplacement garde l'entrée sélectionnée comme destination.",
-- 128c10d4 English: Preview import shows everything this import contains, read-only, the way the
--     editor shows it. Nothing is saved.
[2685] = "Aperçu de l'import affiche tout ce que contient cet import, en lecture seule, comme le fait l'éditeur. Rien n'est enregistré.",
-- 853ec82f English: Check import lists problems with the text instead of its content: why it cannot
--     be imported and any unsupported data. It does not import or change anything.
[2686] = "Vérifier l'import énumère les problèmes du texte plutôt que son contenu : pourquoi il ne peut pas être importé et quelles données ne sont pas prises en charge. Il n'importe ni ne modifie rien.",
-- 27a3bd58 English: Explain profile import destinations and when changes are saved.
[2687] = "Expliquer les destinations d'import de profil et le moment où les modifications sont enregistrées.",
-- ca00de4c English: Copy the text to export a profile, or paste profile text to import. The
--     destination controls choose a new profile or replacement of the selected saved profile.
--     Opening Help does not decode, import, or apply the text.
[2688] = "Copiez le texte pour exporter un profil, ou collez un texte de profil pour l'importer. Les commandes de destination choisissent un nouveau profil ou le remplacement du profil enregistré sélectionné. Ouvrir l'Aide ne décode, n'importe ni n'applique le texte.",
-- 2625de29 English: REPLACE applies immediately to the selected saved profile after Import.
--     Replacing the active profile resets it and applies the imported settings; replacing another
--     profile writes that profile. Reopen the import if the selected saved profile changes.
[2689] = "REPLACE s'applique immédiatement au profil enregistré sélectionné après Importer. Remplacer le profil actif le réinitialise et applique les réglages importés ; remplacer un autre profil écrit ce profil. Rouvrez l'import si le profil enregistré sélectionné change.",
-- 74cf2bda English: NEW stages the imported profile in the Profiles editor. Import fills a
--     new-profile draft; the new profile is not saved or activated until you complete the creation
--     controls in that editor. Give it an unused name.
[2690] = "NEW prépare le profil importé dans l'éditeur de Profils. Importer remplit un brouillon de nouveau profil ; le nouveau profil n'est ni enregistré ni activé tant que vous n'avez pas terminé les commandes de création dans cet éditeur. Donnez-lui un nom inutilisé.",
-- 00c3d8f9 English: Explain this read-only review of imported source.
[2691] = "Expliquer cet examen en lecture seule de la source importée.",
-- 3b8fed45 English: This view shows the selected imported function or condition source, its
--     original and destination identifiers, and available metadata. For a condition, choose a
--     callback to inspect its text. This view and its Help do not compile, execute, accept, or
--     register the source. Return to the bundle review to decide whether to import it.
[2692] = "Cette vue affiche la source de la fonction ou de la condition importée sélectionnée, ses identifiants d'origine et de destination, ainsi que les métadonnées disponibles. Pour une condition, choisissez un callback pour examiner son texte. Cette vue et son Aide ne compilent, n'exécutent, n'acceptent ni n'enregistrent la source. Revenez à l'examen du paquet pour décider de l'importer ou non.",
-- c60faea8 English: Close this read-only source view and return to the bundle review.
[2693] = "Fermer cette vue de source en lecture seule et revenir à l'examen du paquet.",
-- 49411dfb English: Validate the pasted bundle and build a proposed import plan. Review does not
--     apply the plan.
[2694] = "Valider le paquet collé et établir un plan d'import proposé. L'examen n'applique pas le plan.",
-- b8726351 English: Include referenced custom function dependencies when producing export text.
[2695] = "Inclure les dépendances de fonctions personnalisées référencées lors de la production du texte d'export.",
-- 74de20bd English: Explain dependency-bundle export, review, and explicit import.
[2696] = "Expliquer l'export, l'examen et l'import explicite des paquets de dépendances.",
-- 4449aeeb English: Export produces a function or condition bundle, optionally with its custom
--     function dependencies. For import, paste bundle text, choose Review import, inspect the
--     proposed identifiers and conflicts, and review source before applying. Apply import can
--     register trusted Lua source; accept only source you intend to run. Changing the text
--     invalidates the prior plan. Opening Help neither reviews nor applies the bundle.
[2697] = "Exporter produit un paquet de fonction ou de condition, éventuellement avec ses dépendances de fonctions personnalisées. Pour importer, collez le texte du paquet, choisissez Examiner l'import, inspectez les identifiants et conflits proposés, et examinez la source avant d'appliquer. Appliquer l'import peut enregistrer une source Lua de confiance ; n'acceptez que du code que vous comptez exécuter. Modifier le texte invalide le plan précédent. Ouvrir l'Aide n'examine ni n'applique le paquet.",
-- 067adc87 English: Explain rotation preview, destination, and import scope.
[2698] = "Expliquer l'aperçu, la destination et la portée de l'import de rotation.",
-- fe3fd231 English: Copy the text to export the current rotation, or paste a rotation to import.
--     Choose replacement of the selected editable rotation or a new named copy. Class and This
--     character set the owner of a new copy; replacement keeps the original owner. The imported
--     rotation is opened for editing after a successful import.
[2699] = "Copiez le texte pour exporter la rotation actuelle, ou collez une rotation pour l'importer. Choisissez le remplacement de la rotation modifiable sélectionnée ou une nouvelle copie nommée. Classe et Ce personnage définissent le propriétaire d'une nouvelle copie ; un remplacement conserve le propriétaire d'origine. La rotation importée s'ouvre pour modification après un import réussi.",
-- d6789183 English: With Replace selected entry ticked, the button reads Compare import and shows
--     what would change in that rotation. For a new named copy it reads Preview import and shows
--     everything the import contains, read-only, as the rotation editor shows it. Neither saves
--     anything. Import is enabled only for a ready preview or comparison; changing the text
--     requires another one. Check import shows read-only diagnostics, including unsupported data
--     that prevents import.
[2700] = "Quand « Remplacer l'entrée sélectionnée » est cochée, le bouton s'appelle Comparer l'import et montre ce qui changerait dans cette rotation. Pour une nouvelle copie nommée, il s'appelle Aperçu de l'import et montre, en lecture seule, tout ce que contient l'import, tel que l'éditeur de rotation l'affiche. Aucun des deux n'enregistre quoi que ce soit. Importer n'est activé que pour un aperçu ou une comparaison prêts ; modifier le texte en exige un nouveau. Vérifier l'import affiche des diagnostics en lecture seule, y compris les données non prises en charge qui empêchent l'import.",
-- 9a2297f1 English: Explain this read-only incoming rotation comparison.
[2701] = "Expliquer cette comparaison en lecture seule de la rotation entrante.",
-- 4f0c847b English: This view compares the saved or exported rotation with the current incoming
--     preview. It does not apply changes. Close it to choose the destination and import from the
--     transfer dialog. A changed preview, closed owner, or changed profile retires this comparison
--     Help.
[2702] = "Cette vue compare la rotation enregistrée ou exportée avec l'aperçu entrant actuel. Elle n'applique aucune modification. Fermez-la pour choisir la destination et importer depuis la boîte de dialogue de transfert. Un aperçu modifié, un propriétaire fermé ou un profil changé met fin à l'Aide de cette comparaison.",
-- c091ac0b English: Compare import shows what would change in the entry you are replacing, side by
--     side with its current content. Nothing is saved.
[2703] = "Comparer l'import montre ce qui changerait dans l'entrée que vous remplacez, à côté de son contenu actuel. Rien n'est enregistré.",
-- 64144a9e English: Explain this read-only preview of the incoming rotation.
[2704] = "Expliquer cet aperçu en lecture seule de la rotation entrante.",
-- 91ca45b8 English: This view shows the rotation as it would be imported: name, specializations,
--     switch condition, steps and cooldowns. It is read-only and works on a copy; it saves and
--     changes nothing. Close it to choose the destination and import from the transfer dialog. A
--     changed text, closed transfer or changed profile retires this Help.
[2705] = "Cette vue montre la rotation telle qu'elle serait importée : nom, spécialisations, condition de bascule, étapes et temps de recharge. Elle est en lecture seule, travaille sur une copie et n'enregistre ni ne modifie rien. Fermez-la pour choisir la destination et importer depuis la boîte de dialogue de transfert. Un texte modifié, un transfert fermé ou un profil changé met fin à cette Aide.",
-- 5ac254c6 English: Macro invocation
-- Context: Help topic title in the Announces help: an example of how a macro calls an announcement.
[2706] = "Appel de macro",
-- 94a47c93 English: Supplied macro unit
-- Context: Help topic title in the Announces help: the unit that a macro passes to the
--     announcement.
[2707] = "Unité fournie par la macro",
-- c3039a0d English: Invoke this saved identifier directly from your macro. The supplied unit
--     controls Announcement target conditions and Whisper; there is no implicit target.
[2708] = "Invoquez cet identifiant enregistré directement depuis votre macro. L'unité fournie détermine les conditions Cible de l'annonce et Chuchoter ; il n'y a pas de cible implicite.",
-- d4f140f6 English: Via Script/Macro is invoked by its saved Identifier rather than a cast event.
--     It does not require a stored spell or item. Current conditions must match before any output.
--     This call attempts output synchronously; it does not establish that a spell was cast or
--     succeeded.
[2709] = "« Via script/macro » est déclenché par son identifiant enregistré plutôt que par un événement de lancement de sort. Il ne nécessite aucun sort ni objet enregistré. Les conditions actuelles doivent être remplies avant toute sortie. Cet appel tente la sortie de manière synchrone ; il n'établit pas qu'un sort a été lancé ni qu'il a réussi.",
-- 978b4fbf English: Use a unique, case-sensitive identifier of at most 64 ASCII characters. Start
--     with a letter or underscore; subsequent characters may also include digits, dots or hyphens.
--     Identifiers are scoped to the active profile, including disabled entries. Duplicate assigns a
--     distinct identifier; ambiguous imports and Apply are rejected.
[2710] = "Utilisez un identifiant unique, sensible à la casse, d'au plus 64 caractères ASCII. Il doit commencer par une lettre ou un trait de soulignement ; les caractères suivants peuvent aussi être des chiffres, des points ou des traits d'union. Les identifiants sont propres au profil actif, entrées désactivées comprises. Dupliquer attribue un identifiant distinct ; les imports ambigus et Appliquer sont refusés.",
-- 7247934f English: Use /run RM_Annouce('FOO','mouseover',nil). RM_Announce is the same function.
--     The target unit and spell are optional: /run RM_Announce('FOO',nil,403) or /run
--     RM_Announce('FOO','target','Lightning Bolt'). Spell names depend on client language.
--     {{event}} becomes Via Script/Macro; {{target}} and {{spell}} use the supplied arguments. A
--     required missing argument skips output. {{item}} is not supplied by this API. A resurrection
--     message announces an attempt, not a completed resurrection. Examples are text only; RM does
--     not create or execute macros.
[2711] = "Utilisez /run RM_Annouce('FOO','mouseover',nil). RM_Announce est la même fonction. L'unité cible et le sort sont facultatifs : /run RM_Announce('FOO',nil,403) ou /run RM_Announce('FOO','target','Éclair'). Les noms de sorts dépendent de la langue du client. {{event}} devient « Via script/macro » ; {{target}} et {{spell}} utilisent les arguments fournis. S'il manque un argument requis, la sortie est ignorée. {{item}} n'est pas fourni par cette API. Un message de résurrection annonce une tentative, pas une résurrection réussie. Les exemples ne sont que du texte ; RM ne crée ni n'exécute de macros.",
-- fda702d4 English: Supply a readable unit token such as mouseover, target or focus. RM resolves
--     that exact unit name and rechecks its identity during delivery. Announcement target
--     conditions and Whisper use this same unit. Omitting the argument does not use your selected
--     target, yourself, a prior cast or a prior macro call. Missing Announcement target data
--     remains unavailable, including under NOT.
[2712] = "Indiquez un identifiant d'unité lisible tel que mouseover, target ou focus. RM résout le nom exact de cette unité et revérifie son identité au moment de l'envoi. Les conditions de cible d'annonce et Chuchoter utilisent cette même unité. Omettre l'argument n'utilise ni votre cible sélectionnée, ni vous-même, ni un lancement précédent, ni un appel de macro précédent. Les données manquantes de la cible d'annonce restent indisponibles, y compris sous NOT.",
-- 4c48bcf5 English: Checked directs a named emote to the supplied macro unit. Missing or unreadable
--     target data skips the targeted emote; unchecked is targetless.
[2713] = "Cochée, l'émote nommée est dirigée vers l'unité fournie par la macro. Si les données de cible sont manquantes ou illisibles, l'émote ciblée est ignorée ; décochée, l'émote est sans cible.",
-- 4dbc9c41 English: Available only for Via Script/Macro. Attempt a Say message directly in the
--     invoking call. Blizzard may reject macro-origin chat, including during instance encounters;
--     RM does not attest hardware input, defer delivery, retry or guarantee visible output.
[2714] = "Disponible uniquement pour « Via script/macro ». Tente d'envoyer un message Dire directement dans l'appel déclencheur. Blizzard peut refuser une discussion provenant d'une macro, notamment pendant les rencontres d'instance ; RM n'atteste aucune action matérielle, ne diffère pas l'envoi, ne réessaie pas et ne garantit pas que le message soit visible.",
-- a1cf5fb0 English: Available only for Via Script/Macro. Attempt a Yell message directly in the
--     invoking call. Native macro and encounter restrictions still apply; a completed API call is
--     not confirmation of delivery.
[2715] = "Disponible uniquement pour « Via script/macro ». Tente d'envoyer un message Crier directement dans l'appel déclencheur. Les restrictions natives sur les macros et les rencontres s'appliquent toujours ; un appel d'API terminé ne confirme pas l'envoi.",
-- a736bec3 English: Available only for Via Script/Macro. Whisper uses the exact supplied unit name
--     and requires a readable player identity. No target means no Whisper. Native macro and
--     encounter restrictions still apply; RM never substitutes another recipient or retries.
[2716] = "Disponible uniquement pour « Via script/macro ». Chuchoter utilise le nom exact de l'unité fournie et exige une identité de joueur lisible. Sans cible, pas de chuchotement. Les restrictions natives sur les macros et les rencontres s'appliquent toujours ; RM ne remplace jamais le destinataire et ne réessaie pas.",
-- b6082c37 English: Offer this condition type when editing announcement conditions. This flag is
--     independent of Switch Condition and does not remove or invalidate conditions already saved in
--     announcements.
[2717] = "Proposer ce type de condition lors de la modification des conditions d'annonce. Cette option est indépendante de Condition de bascule et ne supprime ni n'invalide les conditions déjà enregistrées dans les annonces.",
-- 45320409 English: One trigger can send an ordered series of outputs. Each expanded card has its
--     own destination, text or sound, conditions and enabled state. Help describes that card.
--     Duplicate makes an independent card; delete removes it. Use the arrows, or drag a card from
--     anywhere on it, to change order. Add output, on the Outputs header row, appends a card; drag
--     it into a gap to insert one there. A legacy announcement stays unchanged on display. Adding,
--     duplicating or removing a card, choosing Channel, or changing to an action type that cannot
--     use its saved destination converts only the draft to output cards. Up to 64 outputs are
--     allowed; an empty series sends nothing. Apply saves the draft and Discard restores it.
[2718] = "Un même déclencheur peut envoyer une série ordonnée de sorties. Chaque carte dépliée a sa propre destination, son texte ou son son, ses conditions et son état d'activation. L'aide décrit cette carte. Dupliquer crée une carte indépendante ; Supprimer la retire. Utilisez les flèches, ou faites glisser une carte depuis n'importe quel point, pour changer l'ordre. Ajouter une sortie, sur la ligne d'en-tête Sorties, ajoute une carte à la fin ; faites-la glisser dans un espace pour l'y insérer. Une annonce de l'ancien format reste inchangée à l'affichage. Ajouter, dupliquer ou supprimer une carte, choisir Canal, ou passer à un type d'action qui ne peut pas utiliser sa destination enregistrée convertit uniquement le brouillon en cartes de sortie. Jusqu'à 64 sorties sont autorisées ; une série vide n'envoie rien. Appliquer enregistre le brouillon et Abandonner rétablit la version enregistrée.",
-- 3c9708b1 English: Via Script/Macro outputs can send to a joined chat channel. Open Channel to
--     refresh the joined names, then select the exact name. A saved name remains visible when
--     unavailable; that output is skipped until the channel is joined under that name. Numeric
--     channel IDs are not saved and channels are never joined automatically. Native delivery
--     permissions still apply.
[2719] = "Les sorties « Via script/macro » peuvent envoyer vers un canal de discussion rejoint. Ouvrez Canal pour actualiser les noms des canaux rejoints, puis sélectionnez le nom exact. Un nom enregistré reste visible lorsqu'il est indisponible ; cette sortie est ignorée jusqu'à ce que le canal soit rejoint sous ce nom. Les numéros de canal ne sont pas enregistrés et les canaux ne sont jamais rejoints automatiquement. Les autorisations d'envoi natives s'appliquent toujours.",
-- 6de77638 English: Choose an announcement trigger, then edit its always expanded output cards.
--     Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move
--     or drag outputs within the announcement. Joined channel names are available for Via
--     Script/Macro. New opens a draft; Apply saves it and Discard restores it. Imports are
--     validated and never execute code.
[2720] = "Choisissez un déclencheur d'annonce, puis modifiez ses cartes de sortie, toujours dépliées. Chaque carte a une destination, des conditions, un état d'activation et une aide. Ajoutez, dupliquez, supprimez, déplacez ou faites glisser les sorties au sein de l'annonce. Les noms des canaux rejoints sont disponibles pour « Via script/macro ». Nouveau ouvre un brouillon ; Appliquer l'enregistre et Abandonner rétablit la version enregistrée. Les imports sont validés et n'exécutent jamais de code.",
-- 318a2558 English: Recommends whatever spell Blizzard's Assisted Combat suggests next, read each
--     time the rotation is evaluated. It highlights that spell's button and shows in the preview
--     like a spell step, and is held to the same requirements: known, usable, off cooldown and in
--     range. When nothing is suggested, the suggested spell is not on your bars, or Assisted Combat
--     is unavailable (anywhere but Retail, or a specialization without it), the step is skipped.
--     Rotation list only.
[2721] = "Recommande le sort que l'Assistant de combat de Blizzard suggère ensuite, lu à chaque évaluation de la rotation. Elle met en surbrillance le bouton de ce sort et s'affiche dans l'aperçu comme une étape de sort, avec les mêmes exigences : connu, utilisable, hors temps de recharge et à portée. Quand rien n'est suggéré, que le sort suggéré n'est pas sur vos barres ou que l'Assistant de combat est indisponible (partout sauf sur Retail, ou pour une spécialisation qui ne l'a pas), l'étape est ignorée. Liste de rotation uniquement.",
-- d462cf8d English: Who highlights the button while a "Blizzard's suggestion" step is the
--     recommendation. Rotation Master's glow uses the effect below. Blizzard's Assisted Highlight
--     turns on the game's own highlight (Options, Gameplay, Combat, Assisted Highlight) while a
--     rotation with that step is active, and Rotation Master leaves that step's button to it; Both
--     shows the two. Rotation Master turns Blizzard's highlight on only outside combat, never
--     changes it if it was already on, and puts your setting back when the rotation ends, Rotation
--     Master is disabled, or you log out or reload. If you change the setting yourself meanwhile,
--     your choice is kept. Blizzard's highlight follows Blizzard's suggestion all the time, also
--     while another step is recommended, and it shows on Blizzard's own action bars only, so choose
--     Rotation Master's glow or Both with a bar addon. The choice is hidden on clients without
--     Blizzard's highlight (Forever and the Classic clients).
[2722] = "Qui met en surbrillance le bouton tant qu'une étape « suggestion de Blizzard » est la recommandation. La lueur de Rotation Master utilise l'effet ci-dessous. La Surbrillance assistée de Blizzard active la surbrillance propre au jeu (Options, Gameplay, Combat, Surbrillance assistée) tant qu'une rotation avec cette étape est active, et Rotation Master lui laisse le bouton de cette étape ; Les deux affiche les deux. Rotation Master n'active la surbrillance de Blizzard qu'en dehors du combat, ne la modifie jamais si elle était déjà activée et rétablit votre réglage quand la rotation se termine, que Rotation Master est désactivé, ou que vous vous déconnectez ou rechargez l'interface. Si vous modifiez vous-même le réglage entre-temps, votre choix est conservé. La surbrillance de Blizzard suit en permanence la suggestion de Blizzard, y compris quand une autre étape est recommandée, et n'apparaît que sur les barres d'action de Blizzard ; avec un addon de barres, choisissez donc la lueur de Rotation Master ou Les deux. Le choix est masqué sur les clients sans la surbrillance de Blizzard (Forever et les clients Classic).",
-- e031d376 English: Add Rotation Master lines to spell and item tooltips. This is the master
--     switch: off, Rotation Master adds nothing to any tooltip, and the options below do nothing.
--     Lines are only added, never read from the tooltip, so other tooltip addons are unaffected.
[2723] = "Ajoute des lignes de Rotation Master aux infobulles de sorts et d'objets. C'est l'interrupteur général : désactivé, Rotation Master n'ajoute rien à aucune infobulle et les options ci-dessous sont sans effet. Les lignes sont seulement ajoutées, jamais lues dans l'infobulle, donc les autres addons d'infobulles ne sont pas touchés.",
-- b52dc56f English: In an item tooltip, list the Rotation Master item sets that contain the item:
--     your profile's and the shared ones from the Item Sets page. Names beyond the limit below end
--     the line with how many more there are.
[2724] = "Dans l'infobulle d'un objet, liste les ensembles d'objets Rotation Master qui le contiennent : ceux de votre profil et les ensembles partagés de la page Ensembles d'objets. Les noms au-delà de la limite ci-dessous terminent la ligne par le nombre de noms restants.",
-- a142e568 English: In a spell or item tooltip, list the rotations for your current specialization
--     that use it as a step in the rotation or cooldown list. A rotation that is switched off is
--     shown dimmed and marked disabled. Built In rotations that are not for this version of the
--     game or your specialization are left out. The list is refreshed out of combat after a
--     rotation or item set changes.
[2725] = "Dans l'infobulle d'un sort ou d'un objet, liste les rotations de votre spécialisation actuelle qui l'utilisent comme étape dans la liste de rotation ou de récupérations. Une rotation désactivée est affichée atténuée et marquée comme désactivée. Les rotations intégrées qui ne concernent pas cette version du jeu ou votre spécialisation sont omises. La liste est actualisée hors combat après la modification d'une rotation ou d'un ensemble d'objets.",
-- 5e8b512d English: Also count a spell or item that appears only inside a condition (for example
--     "spell is ready" or "item is carried"), not just as a step. Off by default because it lists
--     more rotations.
[2726] = "Compte aussi un sort ou un objet qui n'apparaît que dans une condition (par exemple \"le sort est prêt\" ou \"l'objet est porté\"), pas seulement comme étape. Désactivé par défaut car cela liste davantage de rotations.",
-- dffd6006 English: How many names a tooltip line lists before it ends with "(+N more)". A lower
--     number keeps tooltips short.
[2727] = "Combien de noms une ligne d'infobulle liste avant de se terminer par \"(+N autres)\". Un nombre plus bas garde les infobulles courtes.",
-- 83e079d3 English: Your talent specialization. Choose a class, then one of its specializations;
--     your own class is selected first, and other classes are offered for rotations shared between
--     characters. A specialization of another class is always false.
[2728] = "Votre spécialisation de talents. Choisissez une classe, puis l'une de ses spécialisations ; votre propre classe est sélectionnée en premier, et les autres classes sont proposées pour les rotations partagées entre personnages. Une spécialisation d'une autre classe est toujours fausse.",
-- a449bf6b English: Retail and Mists of Pandaria Classic compare your active specialization.
--     Classic Era, Burning Crusade and Wrath compare your primary talent tree, the one tree with
--     the most points; Feral and Guardian both mean Feral Combat there. Forever cannot tell its
--     specializations apart this way. No specialization yet, tied or unspent trees and unreadable
--     values are unavailable, including under NOT. The answer is cached until your talents or
--     specialization change.
[2729] = "Retail et Mists of Pandaria Classic comparent votre spécialisation active. Classic Era, Burning Crusade et Wrath comparent votre arbre de talents principal, l'unique arbre qui compte le plus de points ; Farouche et Gardien signifient tous deux Combat farouche à cet endroit. Forever ne peut pas distinguer ses spécialisations de cette manière. Aucune spécialisation pour l'instant, arbres à égalité ou sans point dépensé et valeurs illisibles sont indisponibles, y compris sous NOT. La réponse est mise en cache jusqu'à ce que vos talents ou votre spécialisation changent.",
-- 86569ac1 English: What is equipped in the main hand, off hand or ranged slot: nothing, any
--     weapon, a one-handed, two-handed or ranged weapon, a shield, an off-hand item, or one weapon
--     type such as Daggers. Types are read from the item's class and subclass, so they work in
--     every language. The answer is cached until your equipment changes.
[2730] = "Ce qui est équipé dans la main droite, la main gauche ou l'emplacement à distance : rien, n'importe quelle arme, une arme à une main, à deux mains ou à distance, un bouclier, un objet de main gauche, ou un type d'arme précis comme les Dagues. Les types sont lus d'après la classe et la sous-classe de l'objet, donc ils fonctionnent dans toutes les langues. La réponse est mise en cache jusqu'à ce que votre équipement change.",
-- 96a5754f English: Dual wielding: off hand holds any weapon. Titan's Grip: off hand holds a
--     two-handed weapon. Backstab and Ambush: main hand holds Daggers. Shield Slam or a tank set:
--     off hand holds a shield. The ranged slot exists only before Mists of Pandaria; elsewhere, and
--     while item data is still loading, this condition is unavailable, including under NOT.
[2731] = "Maniement de deux armes : la main gauche tient n'importe quelle arme. Poigne du titan : la main gauche tient une arme à deux mains. Attaque dans le dos et Embuscade : la main droite tient des Dagues. Heurt de bouclier ou un ensemble de tank : la main gauche tient un bouclier. L'emplacement à distance n'existe qu'avant Mists of Pandaria ; ailleurs, et tant que les données de l'objet se chargent encore, cette condition est indisponible, y compris sous NOT.",
-- 0e0d00b2 English: Not on your action bars
[2732] = "Pas sur vos barres d'action",
-- c8117094 English: An amber border and warning mark a card whose action no action bar button holds
--     right now. Rotation Master highlights an action by lighting the button that holds it, so that
--     step is skipped (a cooldown is never shown) until you put it on a bar. The warning updates
--     when your bars change. Red still marks invalid data.
[2733] = "Une bordure ambre et un signe d'avertissement repèrent une carte dont l'action n'est actuellement contenue dans aucun bouton des barres d'action. Rotation Master met une action en surbrillance en éclairant le bouton qui la contient ; cette étape est donc ignorée (un temps de recharge n'est jamais affiché) tant que vous ne la placez pas sur une barre. L'avertissement se met à jour quand vos barres changent. Le rouge continue de signaler des données invalides.",
-- 2c7e6247 English: Actions must also be on an action bar: Rotation Master highlights an action by
--     lighting the button that holds it, so a step or cooldown that no button holds is skipped, and
--     its card shows an amber warning.
[2734] = "Les actions doivent aussi se trouver sur une barre d'action : Rotation Master met une action en surbrillance en éclairant le bouton qui la contient ; une étape ou un temps de recharge qu'aucun bouton ne contient est donc ignoré, et sa carte affiche un avertissement ambre.",
-- cc011249 English: Matches while the game says a boss encounter is in progress. Unlike the Boss
--     Mod Encounter condition it needs no boss mod, and it knows nothing of which boss or stage it
--     is. It starts when the encounter starts and ends on a kill, a wipe or a reset. It reads in
--     combat on every edition, Retail and Forever included.
[2735] = "Vrai tant que le jeu indique qu'une rencontre de boss est en cours. Contrairement à la condition Rencontre (boss mod), elle n'a besoin d'aucun boss mod et ignore quel boss ou quelle phase c'est. Elle commence avec la rencontre et se termine sur une victoire, un wipe ou une réinitialisation. Elle se lit en combat dans toutes les éditions, Retail et Forever compris.",
-- bec26f34 English: The level of the Mythic+ keystone you are running. It is 0 whenever you are not
--     in a Mythic+ dungeon, so 'at least 10' is only true inside a run of that level. Retail only.
[2736] = "Le niveau de la clé mythique+ que vous jouez. Il vaut 0 quand vous n'êtes pas dans un donjon mythique+, donc « au moins 10 » n'est vrai que dans une clé de ce niveau. Retail uniquement.",
-- a4530fa7 English: The hero talent tree you have chosen. Pick a tree from the list, which shows
--     the trees of the rotation's specialization, or choose 'Any hero talent tree' to match once
--     you have chosen one. A tree can also be entered by its ID, to share a rotation with another
--     class. Below the level that offers hero talents, or before you pick a tree, no tree is
--     chosen. Retail only.
[2737] = "L'arbre de talents de héros que vous avez choisi. Choisissez un arbre dans la liste, qui montre les arbres de la spécialisation de la rotation, ou « N'importe quel arbre de talents de héros » pour vérifier qu'un arbre est choisi. Un arbre peut aussi être saisi par son ID, pour partager une rotation avec une autre classe. En dessous du niveau qui offre les talents de héros, ou avant d'avoir choisi un arbre, aucun arbre n'est choisi. Retail uniquement.",
-- 88cf82f7 English: Matches while the game shows the activation glow on this spell, the golden
--     border an action button gets when a proc makes the spell castable or stronger. It asks the
--     game directly, so it still reads when the buff behind the proc is hidden from addons in
--     combat. Choose the spell as it appears on your bars; its base and override forms are checked
--     too. Unavailable, never simply false, if the game cannot answer.
[2738] = "Vrai tant que le jeu affiche la lueur d'activation sur ce sort, la bordure dorée que reçoit un bouton d'action quand un proc rend le sort lançable ou plus puissant. Elle interroge directement le jeu, donc elle reste lisible même quand l'amélioration à l'origine du proc est masquée aux addons en combat. Choisissez le sort tel qu'il apparaît sur vos barres ; ses formes de base et de remplacement sont aussi vérifiées. Indisponible, jamais simplement fausse, si le jeu ne peut pas répondre.",
-- c9e6ec28 English: How happy your Hunter pet is: Unhappy, Content or Happy, as the game reports
--     it. No pet, or a pet that is not a Hunter pet, is in none of these moods. Classic Era,
--     Burning Crusade and Wrath only.
[2739] = "Le degré de bonheur de votre familier de chasseur : Mécontent, Content ou Heureux, tel que le jeu l'indique. Sans familier, ou avec un familier qui n'est pas de chasseur, il n'est dans aucune de ces humeurs. Classic Era, Burning Crusade et Wrath uniquement.",
-- d6742b74 English: The damage waiting in your Brewmaster Monk's Stagger pool, or, with the box
--     ticked, that damage as a percent of your maximum health. Mists of Pandaria, Retail and
--     Forever only. On Retail and Forever the game can hide the pool from addons in combat, and
--     always hides maximum health, so the percent form is unavailable there and the amount is
--     unavailable whenever the game hides it; neither is ever guessed.
[2740] = "Les dégâts en attente dans la réserve de Report de votre moine maître brasseur ou, case cochée, ces dégâts en pourcentage de votre santé maximale. Mists of Pandaria, Retail et Forever uniquement. Sur Retail et Forever, le jeu peut masquer la réserve aux addons en combat et masque toujours la santé maximale : la forme en pourcentage y est donc indisponible et la quantité l'est chaque fois que le jeu la masque ; rien n'est jamais deviné.",
-- 22cccaf0 English: Advise a spell even when you do not have the mana or other resource for it
--     right now. Without this, a spell you cannot afford is skipped like any other step that is not
--     ready. The spell must still be learned, off cooldown and usable for another reason, and its
--     conditions still apply.
[2741] = "Conseille un sort même si vous n'avez pas, à cet instant, le mana ou l'autre ressource qu'il demande. Sans cette option, un sort que vous ne pouvez pas payer est ignoré comme toute autre étape qui n'est pas prête. Le sort doit toujours être appris, ne pas être en recharge et rester utilisable pour une autre raison, et ses conditions continuent de s'appliquer.",
-- 1bf91ced English: Retail and Forever can hide whether a spell is usable from addons in some
--     situations. The spell is then skipped whether or not this option is on.
[2742] = "Retail et Forever peuvent, dans certaines situations, cacher aux addons si un sort est utilisable. Le sort est alors ignoré, que cette option soit activée ou non.",
-- 0c4bd263 English: Advise a spell or item even when your target is out of its range. Without this,
--     a step whose range check fails is skipped. The spell or item must still be learned or owned,
--     off cooldown and usable, and its conditions still apply.
[2743] = "Conseille un sort ou un objet même si votre cible est hors de portée. Sans cette option, une étape dont le test de portée échoue est ignorée. Le sort ou l'objet doit toujours être appris ou possédé, ne pas être en recharge et rester utilisable, et ses conditions continuent de s'appliquer.",
-- cb691e6c English: Adopt several at once
[2744] = "Adopter plusieurs à la fois",
-- 6ac62581 English: Adopt all and Adopt all from specialization adopt every listed record in one
--     step, for the owner chosen under Applies to. Each record is adopted on its own, exactly as a
--     single adoption would be: a record whose destination already exists, or that is incomplete,
--     stays in the archive and is named in the result.
[2745] = "Adopter tout et Adopter tout de la spécialisation adoptent en une seule étape chaque enregistrement listé, pour le propriétaire choisi sous S'applique à. Chaque enregistrement est adopté séparément, exactement comme une adoption unique : un enregistrement dont la destination existe déjà, ou qui est incomplet, reste dans l'archive et est nommé dans le résultat.",
-- d3742617 English: the number of {item} you are carrying {comparison} {quantity}
