[3261] = "Attribution de rotation : indisponible ; les secondes de capture ne sont pas des secondes de rencontre.",
-- 19f6c4f8 English: Rows omitted: %d
-- %d #1: %d #1: how many rows are left out of the report, e.g. 25
[3262] = "Lignes omises : %d",
-- bed3540d English: Scoring: unavailable
[3263] = "Notation : indisponible",
-- 2e738179 English: Tank: unavailable (no threat, mitigation or survival observations).
[3264] = "Tank : indisponible (aucune observation de menace, d'atténuation ou de survie).",
-- 16603b59 English: Advice/presentation rows describe observed delivery boundaries only;
--     ordinary-cast proof: not available.
[3265] = "Les lignes conseil/présentation décrivent uniquement les limites de livraison observées ; preuve de lancer ordinaire : non disponible.",
-- c7dc0ff3 English: Coverage rows: advice=%d presentation=%d visible=%d hidden=%d unknown=%d
--     retired=%d (not opportunities).
-- %d #1: %d #1: number of "advice" rows, e.g. 40
-- %d #2: %d #2: number of "presentation" rows, e.g. 40
-- %d #3: %d #3: number of "visible" rows, e.g. 30
-- %d #4: %d #4: number of "hidden" rows, e.g. 10
-- %d #5: %d #5: number of "unknown" rows, e.g. 0
-- %d #6: %d #6: number of "retired" rows, e.g. 0
[3266] = "Lignes de couverture : advice=%d presentation=%d visible=%d hidden=%d unknown=%d retired=%d (pas des occasions).",
-- c419fb3c English: Visible means RM-owned preview frame state at a delivery boundary; it does not
--     prove perception or native pixel rendering.
[3267] = "Visible désigne l'état du cadre d'aperçu propre à RM à une limite de livraison ; cela ne prouve ni la perception ni le rendu natif des pixels.",
-- fe67ade9 English: START witness rows: observed=%s matched=%s mismatch=%s excluded=%s unknown=%s
--     (not ordinary proof).
-- %s #1: %s #1: number of START rows observed, e.g. 40 (or "?" when unknown)
-- %s #2: %s #2: number of rows that matched, e.g. 38
-- %s #3: %s #3: number of rows that mismatched, e.g. 1
-- %s #4: %s #4: number of rows excluded, e.g. 1
-- %s #5: %s #5: number of rows with unknown status, e.g. 0
[3268] = "Lignes de témoins START : observed=%s matched=%s mismatch=%s excluded=%s unknown=%s (pas une preuve ordinaire).",
-- 159c3cdb English: START witnesses compare current cast identity and non-autorepeat classification
--     only; they do not classify ordinary casts or enable scoring.
[3269] = "Les témoins START comparent uniquement l'identité du lancer en cours et la classification hors répétition automatique ; ils ne classent pas les lancers ordinaires et n'activent pas la notation.",
-- d16fd756 English: Timeline watch finished. Run /rm debug timeline show to view it.
