[3378] = "Page officielle du projet. Cette page nécessite JavaScript ; les métadonnées d'édition n'ont pas pu être lues de façon indépendante.",
-- 8c9c8997 English: Full EllesmereUI suite including the Action Bars module. Retail and Forever.
[3379] = "Suite EllesmereUI complète, avec le module de barres d'action. Retail et Forever.",
-- 0553000e English: Standalone Action Bars only. Retail and Forever. Its install folder was not
--     confirmed; RM also recognizes the bars by the frames they create.
[3380] = "Barres d'action autonomes uniquement. Retail et Forever. Son dossier d'installation n'a pas été confirmé ; RM reconnaît aussi les barres aux cadres qu'elles créent.",
-- e70d09da English: Official source repository. The action bars are the EllesmereUIActionBars
--     folder. Source availability does not certify integration behavior.
[3381] = "Dépôt source officiel. Les barres d'action sont le dossier EllesmereUIActionBars. La disponibilité des sources ne garantit pas le comportement de l'intégration.",
-- 19905387 English: BigWigs plugin for dungeon and delve bosses. Requires BigWigs and feeds the
--     same bars and stages, so the BigWigs row covers it; no separate RM connection.
[3382] = "Extension de BigWigs pour les boss de donjons et d'expéditions. Nécessite BigWigs et alimente les mêmes barres et phases ; la ligne BigWigs la couvre donc, sans connexion RM distincte.",
-- 6bc1ceb1 English: DBM module pack for dungeons, delves and events. Requires DBM-Core and
--     registers through it, so the DBM row covers it; no separate RM connection.
[3383] = "Pack de modules DBM pour les donjons, expéditions et événements. Nécessite DBM-Core et s'enregistre par son intermédiaire ; la ligne DBM le couvre donc, sans connexion RM distincte.",
-- 828e6463 English: GitHub — LUI Classic fork
[3384] = "GitHub — fork LUI Classic",
