[3398] = "l'unité marquée la plus prioritaire",
-- 60b66204 English: the highest-priority marked unit's
[3399] = "de l'unité marquée la plus prioritaire",
-- 4f69582c English: Raid Mark
-- Context: Name of the Raid Mark condition in the condition list: true while a unit carries a raid
