[3406] = "Retirer le marqueur",
-- 32436d10 English: Put on an action bar
[3407] = "Placer sur une barre d'action",
-- eb8dfba9 English: Makes a macro that presses this step's hidden button, and picks it up. Drop it
--     on an action bar slot and Rotation Master lights it while this step is advised. In a raid
--     only the leader and assistants can place marks.
[3408] = "Crée une macro qui appuie sur le bouton caché de cette étape et la prend en main. Déposez-la sur un emplacement de barre d'action et Rotation Master la met en évidence tant que cette étape est conseillée. Dans un raid, seuls le chef et les assistants peuvent placer des marqueurs.",
-- 406b0045 English: Drag the macro %s to an action bar slot.
-- Context: Message after pressing Put on an action bar: the macro is now on the mouse cursor and
--     the player has to drop it on an action bar slot.
-- %s #1: the name of the macro that was created, e.g. "RM skull/tgt"
[3409] = "Faites glisser la macro %s sur un emplacement de barre d'action.",
-- 45a37997 English: Empty your cursor before binding.
[3410] = "Videz votre curseur avant d'associer.",
-- 69f3d263 English: Your character macros are full, so the macro could not be made.
[3411] = "Les macros de votre personnage sont pleines : la macro n'a pas pu être créée.",
-- b9f12561 English: Raid marks cannot be placed on this client.
[3412] = "Les marqueurs de raid ne peuvent pas être placés sur ce client.",
-- 90c22683 English: The macro could not be made.
[3413] = "La macro n'a pas pu être créée.",
-- 19a35f5c English: Recommends pressing a macro that places the raid mark
[3414] = "Recommande d'appuyer sur une macro qui place le marqueur de raid",
-- 2dacd008 English: uses a Set Mark step this client cannot run
[3415] = "utilise une étape Placer un marqueur que ce client ne peut pas exécuter",
-- bd3e44b0 English: uses Set Mark, which only works in the rotation list
[3416] = "utilise Placer un marqueur, qui ne fonctionne que dans la liste de rotation",
-- 0d936a8d English: /rm debug marks - Report the raid mark table and what each mark unit resolves
