-- %s #1: the unit phrase, e.g. "your target"
-- %s #2: the game's name of the one mark, e.g. "Skull"
[3428] = "%s {{!a|n'a pas}} le marqueur %s",
-- 58d8289e English: the number of marked units
[3429] = "le nombre d'unités marquées",
-- e5568f80 English: the number of marked enemy units
[3430] = "le nombre d'unités ennemies marquées",
-- 0112a03e English: the number of marked friendly units
[3431] = "le nombre d'unités amicales marquées",
-- e2490322 English: Marked units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count every unit that
--     carries a marker.
[3432] = "Unités marquées",
-- cfc9ed3d English: Marked enemies
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     the player can attack.
[3433] = "Ennemis marqués",
-- e9c0dcf1 English: Marked friendly units
-- Context: Choice in the Count dropdown of the Raid Mark Count condition: count only marked units
--     that are friendly.
[3434] = "Unités amicales marquées",
-- 205bd60c English: A number from 0 to 8: there are eight marks, and a unit carries at most one.
[3435] = "Un nombre de 0 à 8 : il y a huit marqueurs, et une unité en porte au plus un.",
-- 6bc4e7b1 English: Matches while the unit carries a raid target marker. Choose Any mark, No mark,
--     or One of these marks and tick the marks you want (skull, cross, square, moon, triangle,
--     diamond, circle, star). A unit that does not exist never matches, not even for No mark. Where
--     the game hides a marker (Retail and Forever restrict some data in combat) the condition is
--     unavailable, also under NOT, never false. To act on whichever unit carries a mark, pick the
--     mark itself as the Unit of another condition: Skull, Cross and the rest, or the
--     highest-priority marked unit, which tries skull first and star last.
[3436] = "Vrai tant que l'unité porte un marqueur de raid. Choisissez N'importe quel marqueur, Aucun marqueur ou L'un de ces marqueurs et cochez ceux que vous voulez (crâne, croix, carré, lune, triangle, losange, cercle, étoile). Une unité qui n'existe pas ne correspond jamais, pas même à Aucun marqueur. Là où le jeu masque un marqueur (Retail et Forever restreignent certaines données en combat), la condition est indisponible, y compris sous NON, et jamais fausse. Pour agir sur l'unité qui porte un marqueur, choisissez le marqueur lui-même comme Unité d'une autre condition : Crâne, Croix et les autres, ou l'unité marquée la plus prioritaire, qui essaie le crâne en premier et l'étoile en dernier.",
-- 74adf719 English: Counts the marked units Rotation Master knows of. It finds them on your target,
--     focus, mouseover, nameplates, group members and their targets, bosses and arena opponents
--     each time a mark changes, so a marked unit you cannot reach right now still counts until the
--     mark is seen to be gone or you leave the area. Count every marked unit, only enemies, or only
--     friendly units. If a marker cannot be read, or a unit's hostility is unknown for the filter
--     you chose, the condition is unavailable, also under NOT. A unit carries at most one mark, so
--     the count is never more than eight.
[3437] = "Compte les unités marquées que Rotation Master connaît. Il les trouve sur votre cible, votre focalisation, la cible sous la souris, les barres de nom, les membres du groupe et leurs cibles, les boss et les adversaires d'arène à chaque changement de marqueur ; une unité marquée hors de portée continue donc d'être comptée jusqu'à ce que son marqueur soit vu disparu ou que vous quittiez la zone. Comptez toutes les unités marquées, seulement les ennemis ou seulement les unités amicales. Si un marqueur est illisible, ou si l'hostilité d'une unité est inconnue pour le filtre choisi, la condition est indisponible, y compris sous NON. Une unité porte au plus un marqueur : le nombre ne dépasse jamais huit.",
-- b5559325 English: When its conditions match, attempts to set or clear the selected raid marker on
--     the chosen unit, then continues to the next rotation step.
[3438] = "Lorsque ses conditions sont remplies, tente de placer ou de retirer le marqueur de raid choisi sur l’unité sélectionnée, puis passe à l’étape suivante de la rotation.",
-- d607ecc3 English: Include disabled rotations
-- Context: Check box on the General settings page, Tooltips section. On: spell and item tooltips
--     also list rotations that are switched off (grayed, marked disabled). Off: only rotations that
--     are on are listed.
[3439] = "Inclure les rotations désactivées",
-- e1738cc8 English: Exclude disabled conditions
-- Context: Check box on the General settings page, Tooltips section, next to 'Include rotation
--     conditions'. On: a condition that is switched off in the rotation editor is not counted when
--     tooltips list the rotations that use a spell or item.
[3440] = "Exclure les conditions désactivées",
-- e3334d5c English: Also list the rotations for your current specialization that are switched off,
--     dimmed and marked disabled, after the ones that are on. Turn this off to list only rotations
--     that are on; the "(+N more)" count then leaves the switched-off ones out too.
[3441] = "Liste aussi les rotations de votre spécialisation actuelle qui sont désactivées, atténuées et marquées comme désactivées, après celles qui sont actives. Désactivez cette option pour ne lister que les rotations actives ; le décompte \"(+N autres)\" omet alors aussi les rotations désactivées.",
-- 766abde1 English: With rotation conditions included, leave out any condition that is switched off
--     in the rotation editor, together with everything under it, because a disabled condition no
--     longer affects the rotation. Off by default: a spell or item that appears only in a disabled
--     condition still counts.
[3442] = "Lorsque les conditions des rotations sont incluses, omet toute condition désactivée dans l'éditeur de rotations, ainsi que tout ce qu'elle contient, car une condition désactivée n'influence plus la rotation. Désactivé par défaut : un sort ou un objet qui n'apparaît que dans une condition désactivée est quand même compté.",
-- 9d030584 English: Unit Exists
[3443] = "L’unité existe",
-- 57e392e8 English: {unit} {{!exists|does not exist}}
[3444] = "{unit} {{!existe|n’existe pas}}",
-- 8dfc9fc3 English: Matches when the selected unit exists. A marked unit exists when that mark is
--     known, even if the unit is currently out of reach.
[3445] = "Correspond si l’unité choisie existe. Une unité marquée existe si sa marque est connue, même hors de portée.",
-- ab06b6f8 English: Highest priority unset
[3446] = "Priorité libre la plus élevée",
-- da73f55a English: Raid Role
[3447] = "Rôle de raid",
-- 7c968fb7 English: Member
[3448] = "Membre",
-- 391e4051 English: Assistant
[3449] = "Assistant",
-- 3f53871b English: Leader
[3450] = "Chef",
-- 901e4ca6 English: you {{!are|are not}} a raid %s
[3451] = "vous {{!êtes|n’êtes pas}} %s de raid",
-- 8aee3f95 English: Matches your role in a raid: member, assistant or leader. Outside a raid it
--     does not match.
[3452] = "Correspond à votre rôle en raid : membre, assistant ou chef. Hors raid, la condition ne correspond pas.",
-- b1df5d42 English: {unit} {{!exist|do not exist}}
[3453] = "{unit} {{!existez|n’existez pas}}",
}
